-- CNC MSP FORGE | HSF-GUIDE-01 | guidance for a first Health and Safety File
-- GENERATED by hsf/build_guidance.py from hsf/guidance/guidance.json (build contract
-- section 12, Amendment 4). Do not edit by hand: change the fragments in
-- hsf/guidance/ and run  python3 hsf/build_guidance.py
--
-- Loads guidance for 15 sections, 256 elements, 41 appointment types and 34
-- element classes, the first File order and the guidance meta (HSF-GUIDE-1.0, draft).
-- Reference content, nothing personal: readable by anon and authenticated, written
-- only by the service role. hsf_public_guidance returns one jsonb document shaped
-- like guidance.json. The last step refuses the migration when any section,
-- element, appointment type or class in the library has no guidance.

-- 1. Tables -------------------------------------------------------------------------------

create table hsf_guidance_meta (
  id int primary key default 1 check (id = 1),
  version text not null,
  status text not null check (status in ('draft','reviewed')),
  reviewed_by text,
  note text not null,
  first_file_intro text not null,
  first_file_order jsonb not null check (jsonb_typeof(first_file_order) = 'array'),
  before_you_start jsonb not null check (jsonb_typeof(before_you_start) = 'array')
);
comment on table hsf_guidance_meta is 'Contract 12.1. One row: the guidance version and review status, and the first File panel (intro, the recommended order of sections with the reason for each, what to have ready).';

create table hsf_section_guidance (
  section_code text primary key references hsf_section(code),
  intro text not null,
  what_goes_here jsonb not null check (jsonb_typeof(what_goes_here) = 'array' and jsonb_array_length(what_goes_here) >= 1),
  who_usually_holds text[] not null check (cardinality(who_usually_holds) >= 1),
  first_file_tips jsonb not null check (jsonb_typeof(first_file_tips) = 'array')
);
comment on table hsf_section_guidance is 'Contract 12.1 and 12.4. What goes in each File section, the departments that usually hold it (the builder preselects the first), and tips for a first File.';

create table hsf_element_guidance (
  element_code text primary key references hsf_element(code),
  what_to_submit jsonb not null check (jsonb_typeof(what_to_submit) = 'array' and jsonb_array_length(what_to_submit) between 2 and 5),
  why text not null,
  example text not null check (example like 'Example%'),
  common_gaps jsonb not null default '[]'::jsonb check (jsonb_typeof(common_gaps) = 'array' and jsonb_array_length(common_gaps) <= 3),
  suggested_department text not null references hsf_department(code)
);
comment on table hsf_element_guidance is 'Contract 12.1. Per element: what to submit, why it matters, a fictitious example and common gaps, with the department the document usually belongs to.';

create table hsf_appointment_guidance (
  appointment_code text primary key references hsf_appointment_type(code),
  what_to_submit jsonb not null check (jsonb_typeof(what_to_submit) = 'array' and jsonb_array_length(what_to_submit) between 2 and 5),
  why text not null,
  example text not null check (example like 'Example%'),
  common_gaps jsonb not null default '[]'::jsonb check (jsonb_typeof(common_gaps) = 'array' and jsonb_array_length(common_gaps) <= 3)
);
comment on table hsf_appointment_guidance is 'Contract 12.1. Per appointment type (APP-nn): what to submit, why, a fictitious example and common gaps. Shown on each per appointment item.';

create table hsf_class_guidance (
  class_code text primary key references hsf_element_class(code),
  what_to_submit jsonb not null check (jsonb_typeof(what_to_submit) = 'array' and jsonb_array_length(what_to_submit) between 2 and 5),
  why text not null,
  example text not null check (example like 'Example%'),
  common_gaps jsonb not null default '[]'::jsonb check (jsonb_typeof(common_gaps) = 'array' and jsonb_array_length(common_gaps) <= 3)
);
comment on table hsf_class_guidance is 'Contract 12.1. Per course, licence class and examination class (D04-nn, D05-nn, E06-nn): what to submit, why, a fictitious example and common gaps.';

-- 2. Rows -----------------------------------------------------------------------------------

insert into hsf_guidance_meta (id, version, status, reviewed_by, note, first_file_intro, first_file_order, before_you_start) values
  (1, 'HSF-GUIDE-1.0', 'draft', null,
   'General guidance for a first Health and Safety File, written in plain words for a small business owner. It is being reviewed by Care Net''s Health and Safety Manager and does not replace the advice of your health and safety practitioner or occupational health practitioner. Legal intervals, ratios and competence requirements are shown only where the File library holds them; everything else follows your risk assessment or your practitioner.',
   'Building your first Health and Safety File is a project, not a form. Start with who you are and who is responsible, then work out what can hurt your people, and only then gather the training, medical, register and emergency records that prove you control those risks. Upload what you already have as you go: a signed page today is worth more than a perfect File next year.',
   '[{"section": "A", "reason": "Your company details, sites, COIDA letter of good standing and contractor agreements define what the File covers and who it belongs to. Everything else hangs off this."}, {"section": "B", "reason": "The signed policy, the section 16(2) assignment and your appointments name the people who will build and keep the rest of the File. Without them nobody owns the work."}, {"section": "C", "reason": "Your risk assessment tells you which training, medical surveillance, registers, permits and hygiene surveys you actually need, so do it before you collect those records."}, {"section": "D", "reason": "Once you know the risks, match each person to the training and competence the risk assessment calls for, starting with inductions and the appointees from Section B."}, {"section": "E", "reason": "Your Medical Surveillance Plan, a separate Care Net product signed by the OMP, follows from the exposures found in Section C. Only certificates of fitness (the outcome) go in the File; clinical records stay with the occupational health practitioner."}, {"section": "K", "reason": "Contractors and visitors bring risk onto your site from day one, so get their Files, section 37(2) agreements and site rules in place early."}, {"section": "F", "reason": "List the equipment, machinery and installations your risk assessment found and file their latest inspection records."}, {"section": "G", "reason": "Set up permits for the high risk work your risk assessment identified (hot work, work at height, confined spaces, isolation) before that work next happens."}, {"section": "H", "reason": "Write the emergency plan around your real sites and people, then run and record a drill so you know it works."}, {"section": "I", "reason": "Start the incident register and reporting route now, so the next injury or near miss is recorded and handled properly, including COIDA."}, {"section": "L", "reason": "Committee minutes, representative inspections and toolbox talks show the File is alive and that workers are consulted. They build up month by month, so start the rhythm early."}, {"section": "J", "reason": "Occupational hygiene surveys take time to book and report. Commission them once Section C shows which exposures need measuring."}, {"section": "M", "reason": "Welfare facilities, the workplace environment and waste are usually quick to evidence once the core risk work is done."}, {"section": "O", "reason": "Decide how long you keep each record, where it is stored and who may see it, especially personal and medical information, before the File grows large."}, {"section": "N", "reason": "Audit and review come last on a first File: once the other sections hold evidence, review them, set objectives and track the corrective actions."}]'::jsonb,
   '["Decide who in your company will own the File day to day. This is usually the person you assign in writing under section 16(2) of the OHS Act.", "Gather your company registration documents, your COIDA letter of good standing and a list of every site with its physical address.", "Make a simple list of your people by job role and headcount per site; the File uses it to work out which appointments and training apply.", "List the work you do that carries higher risk, for example work at height, machinery, chemicals, driving, construction or confined spaces.", "Collect what you already have (old appointment letters, training certificates, inspection records, incident reports) and scan it as PDF; it saves time even if some of it needs updating.", "Keep medical files out of the File: ask your occupational health practitioner for certificates of fitness only.", "Check whether you have a registered, competent health and safety practitioner to guide and sign the File. No suitable person in house? The recruitment button in Section B and on the File header takes you to Care Net''s Recruitment Portal (or to a sales executive until the portal address is live), which places and onboards a registered, competent practitioner with the appointment and engagement letters your File needs."]'::jsonb);

insert into hsf_section_guidance (section_code, intro, what_goes_here, who_usually_holds, first_file_tips) values
  ('A',
   'Section A proves who your company is, where it works, what the File covers and that the basic legal paperwork is in place. An inspector or a client usually asks for these documents first.',
   '["Company registration documents, VAT registration and the physical address of every site", "A scope page naming the sites, activities, dates and any contract or project reference", "Your current COIDA letter of good standing", "Proof that a copy of the OHS Act and its regulations is available at the workplace", "Construction notifications, client specifications and approved health and safety plans, if you do construction work", "Signed section 37(2) agreements and a contractor register, if you use contractors", "A dated legal register and your document control procedure"]'::jsonb,
   array['EXEC', 'SHE', 'PROC', 'HR']::text[],
   '["Start with the scope page: once you have written down which sites and activities the File covers, the rest of the File knows what it must evidence.", "Put the expiry date of your COIDA letter of good standing in your diary; clients often stop work when it lapses.", "If you do no construction work and use no contractors, mark those items not applicable with a short reason rather than leaving them blank."]'::jsonb),
  ('B',
   'Section B shows who is responsible for health and safety in your company and that every person with a legal role has been appointed in writing, has accepted, and is competent for it.',
   '["Your health and safety policy, signed and dated by the chief executive", "The chief executive''s written acknowledgement of responsibility", "The section 16(2) assignment letter, accepted in writing", "Designation letters for health and safety representatives, with their training records", "The health and safety committee constitution, membership list and minutes", "One signed and accepted appointment letter for every appointment that applies to you, with competence evidence", "An organogram of the health and safety structure and a roles and responsibilities document"]'::jsonb,
   array['EXEC', 'SHE', 'HR']::text[],
   '["An appointment is only complete when the letter is signed by the company, signed in acceptance by the appointee, and backed by proof of competence such as a certificate or registration.", "Use one appointment letter per person per role, and update it when the person or the scope changes.", "No suitable person in house? The recruitment button on this section and on the File header takes you to Care Net''s Recruitment Portal (or to a sales executive until the portal address is live), which places and onboards a registered, competent practitioner with the appointment and engagement letters your File needs."]'::jsonb),
  ('C',
   'This section shows how you find out what can hurt people in your business and what you do about it. It starts with your baseline risk assessment and hazard register, then adds the plans and procedures for the higher risk work you actually do. Almost every other section of your File follows from what you record here.',
   '["Your signed baseline risk assessment for each site and activity", "Issue based and task based risk assessments", "Your hazard register and evidence of how you chose controls", "Safe work procedures and method statements", "Activity plans such as fall protection, lifting, excavation, confined space and hot work plans", "Specialist assessments for noise, chemicals, biological agents, ergonomics and physical agents where they apply"]'::jsonb,
   array['SHE', 'OPS', 'ENG']::text[],
   '["Start with one honest baseline risk assessment walked on the floor with your supervisors and a health and safety representative; the other items build on it.", "Only switch on the activity plans for work you really do, and mark the rest not applicable with a short written reason.", "Every assessment needs a named, competent assessor and a signature. No competent person in house to sign your risk assessments? Care Net''s Recruitment Portal places and onboards one, with the appointment and engagement letters your File needs; use the recruitment button on Section B or on the File header, which puts you in touch with a sales executive until the portal address is live.", "Keep the last superseded version of each assessment when you revise it, so you can show how your controls improved."]'::jsonb),
  ('D',
   'Section D proves that every person doing the work knows the hazards, has been trained for the job they actually do, and holds any licence or permit the work needs. It starts from a training needs analysis per job role, is tracked in one training matrix, and is backed by the certificates, induction records and toolbox talk registers themselves.',
   '["A training needs analysis listing what each job role must be trained in", "A training matrix showing every person, every required course, the date done, the expiry date and where the proof is", "Signed induction records for employees, contractors and visitors", "Certificates for statutory and safety critical courses such as first aid, fire fighting and health and safety representative training", "Copies of licences and permits held by people, such as professional driving permits and operator certificates", "Toolbox talk registers with attendance signatures, and competency assessment records"]'::jsonb,
   array['TRAIN', 'HR', 'SHE', 'OPS']::text[],
   '["Do the training needs analysis first, from your risk assessment in Section C; it stops you paying for courses nobody needs and missing the ones the work demands.", "Build the matrix in one spreadsheet before chasing certificates, then fill the gaps oldest expiry first.", "Keep a clear copy of every certificate and licence, front and back, and write the expiry date on the matrix, not only on the card.", "No competent person in house to assess risk, train people or sign competency assessments? Care Net''s Recruitment Portal places and onboards one, with the appointment and engagement letters your File needs; use the recruitment button on Section B or on the File header, which puts you in touch with a sales executive until the portal address is live."]'::jsonb),
  ('E',
   'Section E shows that people are fit for the work and exposures your risk assessment found, and that their health information is handled confidentially. Its key document is your Medical Surveillance Plan, a separate Care Net product signed by the occupational medical practitioner (OMP), and this section is signed off by the OMP only. Care Net screens fitness for work and does not diagnose. Clinical records stay with the occupational health practitioner; your File holds only the outcome for each person: fit, fit with restrictions or unfit.',
   '["The released Medical Surveillance Plan, a separate Care Net product signed by the OMP", "Certificates of fitness per employee: baseline, periodic and exit", "Construction, driving permit and mine fitness certificates where that work applies", "Outcomes of the specific examinations your exposures call for, such as lead, noise or hazardous chemical agents", "A register of fitness restrictions and how each one was reflected in the person''s job", "Proof that occupational diseases were reported (date, body notified and reference), first aid records and a note on how medical records are kept confidential"]'::jsonb,
   array['OH', 'HR', 'SHE']::text[],
   '["Finish your risk assessment in Section C first; the Medical Surveillance Plan, a separate Care Net product signed by the OMP, is built from the exposures it finds, not from job titles.", "Never upload clinical notes, test results or doctors'' letters to your File. Upload only the certificate of fitness showing the outcome.", "Put each person''s certificate expiry date in your training and medical diary so nobody works past it.", "If a certificate says fit with restrictions, record what you changed in the person''s job; that record matters as much as the certificate."]'::jsonb),
  ('F',
   'Section F is the proof that your equipment, installations and workplaces are checked before they hurt someone. Each register lists what you have, and the inspection records beside it show who checked it, when, what they found and what was fixed. Inspectors and clients usually open this section first on a site visit, because an empty register means nobody is looking.',
   '["A register per equipment type: ladders, scaffolds, lifting gear, portable electrical tools, fire equipment, pressure equipment, vehicles and mobile plant", "The inspection checklists or pages that go with each register, signed and dated by the appointed inspector", "The electrical certificate of compliance for each installation", "The hazardous chemical register with current safety data sheets", "The personal protective equipment issue register signed by each person", "Walkabout, housekeeping, stacking and welfare facility inspection records"]'::jsonb,
   array['SHE', 'ENG', 'OPS', 'FAC']::text[],
   '["Walk the site with a clipboard first and list every ladder, extinguisher, tool and machine you actually have; a register built from memory always misses items.", "Give every item a number and mark it on the item itself, so the register and the equipment can be matched in seconds.", "Only switch on the registers your activities need; a small office will not need a scaffold or excavation register.", "Link each register to the person appointed to inspect it in Section B, so the signature on the page matches the appointment letter.", "No competent person in house to inspect this equipment? Care Net''s Recruitment Portal places and onboards one, with the appointment and engagement letters your File needs; use the recruitment button on Section B or on the File header, which puts you in touch with a sales executive until the portal address is live."]'::jsonb),
  ('G',
   'Section G shows how you control high risk work that cannot be made safe by ordinary rules alone: hot work, confined spaces, excavations, work at height, electrical isolation, lifting and demolition. A permit to work makes someone competent check the conditions, sign that controls are in place, and close the job off before people are exposed.',
   '["Your permit to work procedure and a register of permits issued", "Completed permits for hot work, confined space entry, excavation, work at height, lifting and demolition", "Electrical isolation, lockout and tagout records", "Road closure or traffic accommodation approvals where you work on or near a road", "Radiation work authorisations where radiation sources are used"]'::jsonb,
   array['SHE', 'OPS', 'ENG']::text[],
   '["Start with the permit to work procedure and a numbered permit book; everything else in this section flows from it.", "File the closed permit, not only the issued one; a permit that was never signed off is a gap an auditor will find.", "Only activate the permit types your risk assessment in Section C calls for.", "Make sure the person who signs each permit is the one appointed for that work in Section B."]'::jsonb),
  ('H',
   'Section H proves that if something goes badly wrong, people know what to do, where to go and who to call. It holds the emergency plan for each site, the fire plan, the medical emergency arrangements and the records of drills that tested them. A plan that has never been practised is only paper.',
   '["An emergency plan per site with roles, assembly points, escape routes and emergency numbers", "A site plan marking exits, assembly points, fire equipment and first aid boxes", "Drill records with the date, time to evacuate, findings and actions taken", "The fire risk assessment and fire plan", "Medical emergency arrangements, including the nearest hospital and ambulance number", "Spill response, security emergency and major hazard installation plans where they apply"]'::jsonb,
   array['SHE', 'FAC', 'OPS']::text[],
   '["Write one short plan per site rather than one long plan for the company; people need to know their own exits and assembly point.", "Name real people as emergency coordinator, wardens and first aiders, and cover every shift.", "Hold a first drill early, time it, and file what went wrong; the findings are as valuable as the plan.", "Check the emergency numbers in the plan actually work before you file it."]'::jsonb),
  ('I',
   'Section I shows what happens when someone is hurt, made ill or nearly hurt at work: how it is reported, recorded, reported onward to the inspector and COIDA where required, investigated and fixed. A good incident section proves you learn from events so they do not happen again.',
   '["Your incident and near miss reporting procedure", "The incident register, kept up to date", "Records of incidents reported to the inspector", "Investigation reports with root cause and corrective actions", "COIDA claim records and employer''s reports of accidents and diseases", "Occupational disease notifications, showing outcomes only, and the corrective action register"]'::jsonb,
   array['SHE', 'HR', 'OH']::text[],
   '["Set up the incident register on day one, even if it stays empty; an empty register that exists is better than none.", "Encourage near miss reports; a File with injuries but no near misses suggests people are not reporting.", "Keep COIDA claim numbers and correspondence together per incident so you can follow a claim to the end.", "Never file medical reports or doctors'' notes here; the clinical detail stays with the occupational health practitioner."]'::jsonb),
  ('J',
   'Section J holds the measurements that prove what your people are actually exposed to: noise, chemicals, dust, lighting, heat, asbestos and lead. These surveys decide which controls, personal protective equipment and medical surveillance you need, so the rest of the File depends on them being current and done by someone competent.',
   '["An occupational hygiene survey programme listing which surveys are due and when", "Noise surveys with the noise zone map, done by a competent person or approved inspection authority, as your practitioner confirms", "Hazardous chemical agent exposure monitoring reports", "Illumination, ventilation and thermal surveys", "Asbestos and lead air monitoring where those hazards exist", "Aggregate biological monitoring results only, never individual clinical results"]'::jsonb,
   array['SHE', 'OH', 'ENG']::text[],
   '["Let your risk assessment in Section C decide which surveys you need; do not buy surveys for hazards you do not have.", "Check that each survey report names the approved inspection authority or competent person who did it and the date of measurement.", "Read the recommendations page of every report and log each one in your corrective action register.", "No competent person in house to plan these surveys and act on the reports? Care Net''s Recruitment Portal places and onboards one, with the appointment and engagement letters your File needs; use the recruitment button on Section B or on the File header, which puts you in touch with a sales executive until the portal address is live."]'::jsonb),
  ('K',
   'Section K shows how you keep contractors, visitors and members of the public safe while they are on or near your site. You remain responsible for people you bring in, so this section proves you chose competent contractors, agreed safety terms in writing, inducted everyone and protected the public.',
   '["Contractor selection criteria and completed evaluations", "Section 37(2) agreements and each contractor''s own File", "Contractor induction records, permits and daily coordination notes", "The visitor register and visitor induction", "Public protection records such as hoarding, signage and public liability insurance"]'::jsonb,
   array['PROC', 'SHE', 'FAC']::text[],
   '["Do not let a contractor start work until the signed section 37(2) agreement and its File are in your hands.", "Use one short checklist to evaluate every contractor so decisions are consistent and easy to defend.", "A visitor book at reception with a short safety briefing card is enough for most small businesses.", "Cross reference Section A, where the contractor register and agreements also appear, rather than filing two different versions."]'::jsonb),
  ('L',
   'Section L proves that you talk to your people about health and safety and listen to them. It holds committee minutes, the health and safety representatives'' inspection reports, toolbox talks, the notices on your walls and records of the changes you told Care Net and your client about.',
   '["Health and safety committee minutes with an action list", "Health and safety representative inspection reports and your responses", "Toolbox talk registers with topics and signatures", "A record of the notices displayed and when they were checked", "Change notifications sent to Care Net and to your client"]'::jsonb,
   array['SHE', 'HR', 'OPS']::text[],
   '["Keep the committee action list separate from the minutes and carry open items forward until they are closed.", "Answer every representative''s recommendation in writing, even if the answer is no, and give the reason.", "Photograph your notice board once a year and file the photo; it is the simplest proof of what was displayed.", "When you add a new process, chemical or site, tell Care Net so the Medical Surveillance Plan, a separate Care Net product, can be updated."]'::jsonb),
  ('M',
   'Section M covers the everyday conditions people work in: toilets, drinking water, change rooms and eating areas, the physical environment, smoking controls and, where environmental law applies, how you manage and dispose of waste. These are the items workers notice first and complain about most.',
   '["An annual review of welfare facilities against the number of workers on site", "A review of lighting, ventilation, temperature and housekeeping", "Environmental management records where environmental law applies to you", "Waste manifests and safe disposal certificates from licensed contractors", "Your smoking policy and designated smoking area"]'::jsonb,
   array['FAC', 'SHE', 'OPS']::text[],
   '["Count your workers by gender and shift before you count toilets and basins; the facilities must match the people who use them.", "Keep every waste manifest and disposal certificate; they prove your waste went where it should.", "Use the survey results in Section J as the evidence for the physical environment review rather than guessing.", "Photographs of facilities with a date make the annual review quick and convincing."]'::jsonb),
  ('N',
   'Section N proves that you check your own system, find what is not working and fix it. It holds internal and external audit reports, management review records, objectives and targets, the non conformance log and the record of legislation updates applied to the File. It is the section that turns a pile of documents into a system that improves.',
   '["An internal audit schedule and the completed audit reports", "External audit reports from clients, principal contractors, certification bodies or the inspector", "Minutes of management reviews led by the chief executive", "Health and safety objectives and targets with the measurements against them", "The non conformance and corrective action log with closure evidence", "The log of legislation release notes applied to your File"]'::jsonb,
   array['SHE', 'EXEC']::text[],
   '["Your File should be audited by someone whose registration and experience fit your industry. The auditor recruitment button on this section has Care Net''s Recruitment Portal match and onboard one; until the portal address is live, it puts you in touch with a sales executive.", "Set two or three measurable objectives for your first year; a short list you track beats a long list you ignore.", "Close every audit finding with evidence such as a photo, a new form or a training record, not just a tick.", "Hold the first management review after your first audit, so the review has real findings to discuss."]'::jsonb),
  ('O',
   'Section O shows how long you keep each kind of record, where it is stored, who may see it, and the agreement that governs the records Care Net holds for you. Health and safety records often need to be produced years later, especially medical surveillance records for hazardous exposure, so losing them can leave you with no defence.',
   '["A retention schedule listing each record type and how long it is kept", "A storage and access control list showing where each record type lives and who can open it", "The signed operator agreement for personal information between your company and Care Net"]'::jsonb,
   array['EXEC', 'SHE', 'HR']::text[],
   '["Build the retention schedule from the section list of your File so no record type is forgotten.", "Keep medical records apart from everything else, with access only for the occupational health practitioner.", "Decide who holds the keys and passwords to each store, and what happens when that person leaves.", "Sign the operator agreement before any worker records are shared with Care Net."]'::jsonb);

insert into hsf_element_guidance (element_code, what_to_submit, why, example, common_gaps, suggested_department) values
  ('HSF-A-01',
   '["Company registration certificate (CIPC documents)", "VAT registration letter, if you are VAT registered", "List of every site with its full physical address and a contact person"]'::jsonb,
   'An inspector, client or insurer must be able to see exactly which legal entity is the employer and where it works. It also tells the File which sites the other records must cover. Update it whenever a detail changes.',
   'Example: Dube Engineering (Pty) Ltd files its CIPC registration, its VAT letter and a one page site list naming its workshop in Rosslyn and its store in Pretoria West.',
   '["Using a trading name without the registered company name and number", "Listing a postal address or head office only, not the physical address of each site", "Forgetting to add a new site or remove a closed one"]'::jsonb,
   'EXEC'),
  ('HSF-A-02',
   '["Signed scope page naming the sites, activities and dates the File covers", "Contract or project reference, where the File is for a client or project", "Client or tender requirement that asked for the File, if any"]'::jsonb,
   'The scope tells a reader what this File covers and what it does not, so nobody assumes it covers a site or activity it never looked at. It is kept up to date by your section 16(2) assignee whenever the work changes.',
   'Example: Khumalo Shopfitters'' scope page says the File covers its Germiston workshop and the fit out of a retail store in Menlyn for the period of that contract.',
   '["Writing a scope so broad it cannot be evidenced", "Not updating the scope when a new site or project starts"]'::jsonb,
   'SHE'),
  ('HSF-A-03',
   '["Current COIDA letter of good standing, showing the expiry date", "Proof of registration with the Compensation Fund", "Latest return of earnings acknowledgement, if you have it"]'::jsonb,
   'The letter of good standing shows you are registered and paid up for COIDA, so injured workers can be compensated. Clients and principal contractors normally will not let you on site without a valid one. Replace it before it expires.',
   'Example: Nel Plumbing uploads its letter of good standing and sets a reminder two weeks before the expiry date printed on it.',
   '["Filing an expired letter", "Filing a letter issued to a different entity in the same group", "Only renewing it when a client asks"]'::jsonb,
   'HR'),
  ('HSF-A-04',
   '["Photo or note showing where the OHS Act and its regulations are kept at each site (printed copy or an accessible electronic copy)", "For mines, the equivalent under the MHSA regime", "Date the copy was last checked as current"]'::jsonb,
   'Workers are entitled to read the law that protects them, and an inspector may ask where it is. A current copy also helps your supervisors check what is required. Replace it when the law changes.',
   'Example: Mokoena Logistics keeps a printed OHS Act and regulations file in the canteen at its Isando depot and a link on the tablet at reception, and photographs both for the File.',
   '["Keeping only an old copy that still contains regulations that have since been replaced", "Keeping the only copy locked in a manager''s office"]'::jsonb,
   'SHE'),
  ('HSF-A-05',
   '["Construction work notification submitted to the Department of Employment and Labour", "The Department''s acknowledgement or reference, or a construction work permit where one applies", "Copy displayed on site"]'::jsonb,
   'The Department must know about construction work before it starts so it can plan inspections. The acknowledgement proves the notification was made. Do this per project, before work begins, as the Construction Regulations, 2014 require.',
   'Example: Sibiya Builders, principal contractor for a small office block in Pinetown, notifies the Department before work starts and files the acknowledgement it received before site establishment.',
   '["Starting work before the notification was submitted", "Using a notification from an earlier project", "Not displaying the notification on site"]'::jsonb,
   'SHE'),
  ('HSF-A-06',
   '["The client''s health and safety specification for the project, signed and dated", "Any revisions issued during the project", "Proof that the specification was given to the principal contractor"]'::jsonb,
   'The specification sets out the client''s health and safety requirements for the project and is what every contractor''s health and safety plan must answer. Without it, contractors are pricing and planning blind. It is kept per project.',
   'Example: Botha Property Trust issues a health and safety specification for re roofing its Bloemfontein warehouse and files the version sent with the tender documents.',
   '["Using a generic specification that does not mention the project''s actual hazards", "Not issuing the specification with the tender, so contractors cannot price for it"]'::jsonb,
   'PROC'),
  ('HSF-A-07',
   '["The contractor''s health and safety plan for the project", "The client''s written approval of the plan", "Records of revisions and re approval when the work changes"]'::jsonb,
   'The plan shows how the contractor will control the project''s risks, and the client''s written approval shows it was checked before work started. Your construction manager is responsible for it, per project.',
   'Example: Mthembu Builders files its health and safety plan for a school classroom extension in Polokwane with the client agent''s signed approval letter.',
   '["Starting work on an unapproved plan", "Not updating the plan when the method or scope changes", "Copying a plan from a previous project without changing the hazards"]'::jsonb,
   'SHE'),
  ('HSF-A-08',
   '["Signed section 37(2) agreement with each mandatary and contractor", "List of contractors covered, with the agreement date for each", "Contractor''s scope of work attached to the agreement"]'::jsonb,
   'A section 37(2) agreement records that the contractor accepts responsibility for health and safety in its own work on your premises. Without it, you may carry the contractor''s failures as your own. Update it when a contractor or scope changes.',
   'Example: Pillay Foods has a signed section 37(2) agreement with the cleaning company and the refrigeration technicians who work at its Durban factory.',
   '["Having only a purchase order, not a signed agreement", "Letting the agreement lapse when a contract is renewed", "Forgetting small or once off contractors"]'::jsonb,
   'PROC'),
  ('HSF-A-09',
   '["Contractor register listing each contractor, its scope and dates on site", "For each contractor: its Health and Safety File index, COIDA letter of good standing and appointments", "Notes of your check that each File was reviewed before work started"]'::jsonb,
   'The register lets you and an inspector see at a glance which contractors are on site and whether each one is in order. It is kept current by your section 16(2) assignee whenever a contractor starts, changes or leaves.',
   'Example: Venter Mining Services keeps a contractor register showing that the scaffold contractor''s File was reviewed on induction day and its letter of good standing runs to the end of the project.',
   '["Not checking that the contractor''s letter of good standing is still valid", "Allowing a contractor on site before its File was reviewed"]'::jsonb,
   'PROC'),
  ('HSF-A-10',
   '["Dated legal register listing the laws that apply to your industry and activities", "Record of the monthly check for changes", "Notes of what you did about any change"]'::jsonb,
   'The legal register shows you know which laws apply to you and keep track of changes. The File builder draws it from Care Net''s legal library for your industry; your section 16(2) assignee checks it every month and records the check.',
   'Example: Ndlovu Agri checks its legal register each month and notes that a new chemical rule affects its crop spraying, with a task to update the spraying procedure.',
   '["A register that has never been dated or reviewed", "Listing laws with no link to what the company actually does about them"]'::jsonb,
   'SHE'),
  ('HSF-A-11',
   '["Document control procedure (how documents are numbered, approved, issued and withdrawn)", "The File''s revision history page", "Master list of controlled documents with current revision numbers"]'::jsonb,
   'Document control makes sure people work from the current version of a procedure or form, and the revision history shows how the File has changed over time. Update it whenever a controlled document changes.',
   'Example: Smit Electrical numbers its procedures by type and year, and its revision history shows that the lockout procedure was revised after a near miss in June.',
   '["Old versions still in use on site", "No record of who approved a change and when"]'::jsonb,
   'SHE'),
  ('HSF-B-01',
   '["Health and safety policy signed and dated by the chief executive", "Photo of the policy displayed at each site", "Record of the annual review, even when nothing changed"]'::jsonb,
   'The policy is your company''s public commitment to keeping people safe and healthy, and it sets the direction for the whole File. Clients and inspectors expect to see it signed, displayed and reviewed every year.',
   'Example: Molefe Transport''s managing director signs the policy each February after the management review and the new copy is put up in the dispatch office and the workshop.',
   '["An unsigned or undated policy", "A policy copied from another company that does not fit your work", "No evidence of the annual review"]'::jsonb,
   'EXEC'),
  ('HSF-B-02',
   '["Signed statement by the chief executive acknowledging personal responsibility for health and safety", "The chief executive''s name and date of appointment as chief executive", "Updated statement when the chief executive changes"]'::jsonb,
   'Under the OHS Act the chief executive carries responsibility for health and safety, and this cannot be delegated away by assigning duties to others. The signed acknowledgement shows the top of the company understands this.',
   'Example: When Lindiwe Sithole became chief executive of Sithole Security Solutions she signed a new acknowledgement and the old one was archived.',
   '["Not updating the statement when the chief executive changes", "Believing the section 16(2) assignment removes the chief executive''s own responsibility"]'::jsonb,
   'EXEC'),
  ('HSF-B-03',
   '["Section 16(2) assignment letter signed by the chief executive", "Written acceptance signed by the assignee", "Scope of the assignment (sites, departments, duties) attached"]'::jsonb,
   'The section 16(2) assignment gives a named person specific health and safety duties to carry out day to day; the chief executive stays responsible. Putting it in writing, with the assignee''s acceptance and a clear scope, is good practice that makes the assignment easy to defend. Update it when the person or scope changes.',
   'Example: Mahlangu Civils keeps a signed letter appointing Thandi Nkosi as its section 16(2) assignee for its Emalahleni yard and all its road projects, with her signed acceptance.',
   '["No signed acceptance by the assignee", "No scope, so nobody knows which sites the assignee covers", "Assigning someone with no authority or budget to act"]'::jsonb,
   'EXEC'),
  ('HSF-B-04',
   '["Designation letters for each health and safety representative, signed and accepted", "Record of the consultation with workers or their union before designation", "Training certificates for each representative", "Calculation showing enough representatives for your headcount"]'::jsonb,
   'Representatives are workers'' voice on health and safety and inspect the workplace for hazards. The number required depends on your headcount; the File works it out for you. Update when a representative leaves or headcount changes.',
   'Example: Naidoo Packaging consulted staff at a shift meeting, designated Sipho Mabaso and Anele Dlamini as representatives for its two shifts and filed their training certificates.',
   '["Management choosing representatives without consulting workers", "Representatives who were never trained", "Not replacing a representative who has left"]'::jsonb,
   'SHE'),
  ('HSF-B-05',
   '["Committee constitution or terms of reference", "Current membership list, with representatives and employer members", "Signed minutes of each meeting, with action lists"]'::jsonb,
   'The committee brings representatives and management together to deal with health and safety issues and keeps a record of decisions. The File expects minutes every month; the minutes are the best proof that problems are raised and fixed.',
   'Example: Kruger Timber''s committee meets on the first Tuesday of each month; the minutes record that the damaged forklift guard raised in May was repaired by June.',
   '["Meetings that happen without minutes", "Actions that roll over from month to month with no owner", "Membership lists that still show people who have left"]'::jsonb,
   'SHE'),
  ('HSF-B-06',
   '["One appointment letter per applicable appointment, signed by the company", "The appointee''s signed acceptance", "Competence evidence for each appointee (certificate, registration or training record)", "An appointments matrix listing every appointment and its status"]'::jsonb,
   'Many kinds of work need a named, competent person appointed in writing. This item groups them: the File creates one entry per appointment that applies to you, and each must be signed, accepted and backed by competence evidence. Update when a person or role changes.',
   'Example: Mabena Steel keeps an appointments matrix showing its first aiders, ladder inspector and lifting machine operators, each with a signed letter and a current certificate.',
   '["Letters signed by the company but never accepted by the appointee", "Competence evidence that has expired", "No appointment for someone who has been doing the role for years"]'::jsonb,
   'SHE'),
  ('HSF-B-07',
   '["Organogram showing the chief executive, section 16(2) assignee, representatives, committee and every appointee", "Date of the organogram", "Updated version when someone joins or leaves a role"]'::jsonb,
   'The organogram shows at a glance who is responsible for what and who reports to whom on health and safety. It helps new staff and inspectors find the right person, and it exposes gaps where a role is empty.',
   'Example: Moodley Retail''s organogram shows the store manager as section 16(2) assignee for each branch with first aiders and evacuation wardens below, and is redated when staff change.',
   '["Showing positions without names", "Not updating after resignations, so the chart names people who have left"]'::jsonb,
   'HR'),
  ('HSF-B-08',
   '["Roles and responsibilities document for each appointment", "Health and safety duties in each job description", "Signed acknowledgement by each role holder"]'::jsonb,
   'People can only carry out duties they know they have. This document spells out what each appointee and each job role must do for health and safety, so responsibilities do not fall through the cracks.',
   'Example: Hlongwane Farming adds a health and safety duties paragraph to each job description, and the tractor driver signs that he must do a pre use check each morning.',
   '["Duties written so generally they mean nothing", "Job descriptions that never mention health and safety"]'::jsonb,
   'HR'),
  ('HSF-C-01',
   '["Signed baseline risk assessment for each site and activity", "Risk assessor''s appointment letter and proof of competence", "Attendance list of the people consulted, including health and safety representatives", "Next review date written on the cover page"]'::jsonb,
   'The baseline risk assessment is the foundation of your whole File: it records every significant hazard at each site and how you control it. An inspector or client will usually ask for it first, and your medical surveillance, training and PPE choices must all trace back to it. Review it every year and whenever something significant changes.',
   'Example: Dlamini Steel Works in Germiston keeps a baseline risk assessment for its workshop and its yard, signed by its appointed risk assessor Sipho Zulu on 12 February 2026, with the next review set for February 2027.',
   '["Buying a generic template and never walking the actual site", "One assessment covering several very different sites", "No signature, no assessor name or no review date"]'::jsonb,
   'SHE'),
  ('HSF-C-02',
   '["Issue based risk assessment for each change, incident, new task or new substance", "Short note of what triggered it (change request, incident number, new product)", "Updated controls and who must act by when", "Signature of the risk assessor"]'::jsonb,
   'Your baseline goes out of date the moment something changes. An issue based assessment shows that you looked at the new risk before people were exposed, and that you learnt from incidents. Do one for each event rather than waiting for the yearly review.',
   'Example: After a forklift struck a racking upright, Steyn Cold Storage completed an issue based risk assessment on 4 May 2026 that led to floor markings and a pedestrian walkway, signed by its risk assessor Lerato Mokoena.',
   '["Changing equipment or chemicals without any assessment", "Investigating an incident but never updating the risk assessment", "Not linking the assessment back to the baseline"]'::jsonb,
   'SHE'),
  ('HSF-C-03',
   '["Completed daily or shift pre task assessment forms (for example a take five or safe task card)", "Supervisor''s signed log or register of the forms", "Sample of forms showing hazards raised and actions taken"]'::jsonb,
   'Conditions on the floor change every day. A short pre task assessment done by the team before starting makes people stop and think about today''s hazards, and the supervisor''s log proves it actually happens. Complete it every day or shift where this work applies.',
   'Example: Cele Glass Fitters in Umhlanga asks each team to complete a pre task card before every installation; supervisor Ayanda Cele signs the daily log and files the cards weekly.',
   '["Forms filled in at the end of the shift or all ticked the same", "Supervisor never reviews or signs the forms", "No action taken on hazards the team wrote down"]'::jsonb,
   'OPS'),
  ('HSF-C-04',
   '["Hazard register listing hazards per job role", "Job role list matched to the hazard register", "Date and signature of the last update"]'::jsonb,
   'A hazard register per job role lets you see at a glance what each person is exposed to, which drives training, PPE and medical surveillance for that role. Update it whenever roles, tasks or hazards change.',
   'Example: Qwabe Packaging keeps a hazard register showing that its machine operators face noise, moving parts and manual handling, while its dispatch clerks face vehicle traffic in the loading bay; last updated 20 March 2026.',
   '["A register by department instead of by job role", "Roles in the register that no longer exist, or new roles missing", "Hazards listed with no link to the controls"]'::jsonb,
   'SHE'),
  ('HSF-C-05',
   '["Report showing, for each major hazard, whether you eliminated, substituted, engineered, administered or protected against it", "Photographs or records of engineering controls installed", "Reasons where a higher level of control was not reasonably practicable"]'::jsonb,
   'The law expects you to remove or reduce a hazard at source before relying on rules and PPE. This report proves you considered the stronger options first, which is one of the first things an inspector tests. Review it every year.',
   'Example: Masilela Furniture Makers replaced a solvent based glue with a water based one and fitted extraction on its sanders, then recorded in its 2026 control report why dust masks are still worn as a last line of defence.',
   '["Going straight to PPE for every hazard", "No written reason why a better control was not used", "Controls listed but never checked to see if they work"]'::jsonb,
   'SHE'),
  ('HSF-C-06',
   '["Safe work procedures for routine tasks", "Method statements for high risk tasks", "Signed record that workers were trained on each procedure", "Document control list with revision dates"]'::jsonb,
   'Written procedures turn your risk assessment into clear steps that workers can follow, and they show a client or inspector that high risk work is planned, not improvised. Update a procedure whenever the task, equipment or risk assessment changes.',
   'Example: Molefe Borehole Services in Mahikeng has a method statement for pump pulling, approved by its section 16(2) assignee Kagiso Molefe and signed by every crew member after training on 9 April 2026.',
   '["Procedures copied from another company that do not match your equipment", "Workers never trained on or shown the procedure", "Old versions still in use on site"]'::jsonb,
   'OPS'),
  ('HSF-C-07',
   '["Fall protection plan for the project or site", "Appointment letter and proof of competence of the fall protection planner", "Rescue plan for a person suspended in a harness", "Inspection records of harnesses and anchor points"]'::jsonb,
   'Falls from height are among the most common causes of serious injury and death at work. The Construction Regulations, 2014 require a fall protection plan by a competent person where there is a risk of falling, and most clients will not let you onto site without one. Prepare one for each project.',
   'Example: Nkosi Roofing prepared a fall protection plan for a warehouse roof in Pietermaritzburg, drawn up by its appointed fall protection planner Themba Khumalo and approved on 2 June 2026, including a rescue plan using a rescue kit kept on site.',
   '["A generic plan that ignores the actual roof or structure", "No rescue plan for a worker left hanging in a harness", "Planner not appointed in writing or not competent"]'::jsonb,
   'SHE'),
  ('HSF-C-08',
   '["Traffic management plan with a site layout drawing", "Signage, speed limit and pedestrian route records", "Briefing record for drivers and pedestrians"]'::jsonb,
   'Where vehicles, forklifts and people share space, collisions can kill. A traffic management plan separates them with routes, barriers and rules, and it is often requested by clients for warehouses and sites. Update it whenever the layout or traffic pattern changes.',
   'Example: Masiphile Logistics in Pinetown has a traffic management plan showing one way truck routes, a fenced walkway and a no go zone around reversing trucks, approved by its section 16(2) assignee on 15 January 2026.',
   '["A plan that no longer matches the yard after a layout change", "Pedestrian routes painted but blocked by stock", "Visiting drivers never briefed"]'::jsonb,
   'OPS'),
  ('HSF-C-09',
   '["Lifting plan for each lift that needs one", "Load chart and details of the crane or lifting machine", "Certificates of the lifting tackle used", "Names of the operator, rigger and signaller"]'::jsonb,
   'A dropped or toppled load can kill people nearby. A lifting plan checks the load, the machine, the ground and the people before the lift happens, and it is the record the lifting machine inspector and the client will ask for. Prepare one for each lift that requires it.',
   'Example: Vaal Mechanical Erectors prepared a lifting plan for placing a chiller on a factory roof in Vanderbijlpark on 18 August 2026, drawn up by its lifting supervisor Pieter van Wyk and backed by current inspection certificates for the crane and slings.',
   '["Lifting without a plan because the crane hire company is \"handling it\"", "Using tackle whose inspection has lapsed", "No exclusion zone under the load"]'::jsonb,
   'ENG'),
  ('HSF-C-10',
   '["Excavation plan for the project", "Appointment letter of the excavation supervisor", "Record of services located (cables, pipes) before digging", "Daily excavation inspection records"]'::jsonb,
   'Trench collapses bury workers quickly and are often fatal. The Construction Regulations, 2014 expect excavation work to be planned and supervised by a competent person, with shoring and inspections in place. Prepare a plan for each project.',
   'Example: Mogale Pipelines prepared an excavation plan for a sewer upgrade in Krugersdorp, with shoring details and a service locating report, signed by its excavation supervisor Johannes Maseko on 6 July 2026.',
   '["Digging before locating underground services", "No shoring or battering because the trench is \"only for a day\"", "Inspections done but not written down"]'::jsonb,
   'OPS'),
  ('HSF-C-11',
   '["Demolition plan and method statement", "Appointment letter of the demolition supervisor", "Engineering or structural survey where required", "Asbestos and hazardous materials check before work starts"]'::jsonb,
   'Demolition can cause sudden collapse, flying debris and exposure to asbestos or lead. A demolition plan sets the sequence and controls, and the Construction Regulations, 2014 expect it to be done under a competent supervisor. Prepare a plan for each project.',
   'Example: Ntshona Wreckers prepared a demolition plan for an old workshop in East London, with an asbestos survey and a sequence drawing, signed by its demolition supervisor Luvuyo Ntshona on 11 March 2026.',
   '["Starting demolition without checking for asbestos", "No plan for the order in which walls and roofs come down", "Public and neighbours not protected from falling debris"]'::jsonb,
   'OPS'),
  ('HSF-C-12',
   '["Confined space plan for each entry", "Entry permit with gas test results", "Appointment letter of the confined space supervisor", "Standby person and rescue arrangements"]'::jsonb,
   'Tanks, pits, manholes and silos can hold toxic gas or too little oxygen, and would be rescuers often die too. The plan and permit prove the space was tested, ventilated and watched before anyone went in. Prepare one for each entry.',
   'Example: Mokone Tank Cleaning completes a confined space plan and entry permit for every tank it enters; on 23 April 2026 its confined space supervisor Nomsa Radebe signed the permit after a gas test at a client''s plant in Secunda.',
   '["Gas testing not recorded, or done with an uncalibrated meter", "No trained standby person at the entrance", "Rescue plan that relies on calling the fire brigade only"]'::jsonb,
   'SHE'),
  ('HSF-C-13',
   '["Hot work plan or permit for each job", "Fire watch record after the work ends", "Appointment letter of the hot work supervisor", "Proof that fire extinguishers were available and inspected"]'::jsonb,
   'Welding, cutting and grinding cause fires, burns and fume exposure. A hot work permit shows the area was cleared of flammables, a fire watch was in place and the work was supervised. Prepare one for each hot work job.',
   'Example: Adams Engineering Services in Kimberley issues a hot work permit for every welding job outside its workshop; on 30 May 2026 hot work supervisor Grant Adams signed off a permit that included a fire watch after the welding stopped.',
   '["Permits signed after the work is done", "No fire watch once the welder leaves", "Hot work permits not used for contractors"]'::jsonb,
   'ENG'),
  ('HSF-C-14',
   '["Ergonomic risk assessment covering manual handling, repetitive work and workstations", "Action plan with changes made (lifting aids, workstation adjustments)", "Risk assessor''s signature and date"]'::jsonb,
   'Back, neck and upper limb injuries from lifting, awkward postures and repetitive work are a leading cause of lost time. An ergonomic risk assessment identifies the tasks that strain people and records what you changed. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Jacobs Fruit Packers assessed its packing line on 14 January 2026, raised the packing tables and introduced job rotation; the assessment is signed by its risk assessor Marlize Jacobs.',
   '["Only looking at office chairs and ignoring manual handling", "No follow up to check the changes helped", "Workers not asked where it hurts"]'::jsonb,
   'SHE'),
  ('HSF-C-15',
   '["Noise survey and noise risk assessment by a competent person or approved inspection authority, as your practitioner confirms", "Noise zone map with signage", "Appointment letter of the noise zone controller", "Hearing protection issue records"]'::jsonb,
   'Noise damage to hearing is permanent and builds up slowly. The survey shows where noise is high enough to need zoning and hearing protection, and it decides who needs hearing tests through your medical surveillance. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Dube Steel Fabricators in Newcastle had a noise survey done on 8 February 2026, marked the press shop as a noise zone with signs at every entrance, and appointed foreman Bongani Dube as noise zone controller.',
   '["Relying on an old survey after new machinery was installed", "Noise zones marked on paper but not signposted", "Hearing protection issued without any fit or training"]'::jsonb,
   'SHE'),
  ('HSF-C-16',
   '["Hazardous chemical agent risk and exposure assessment", "Chemical inventory with current safety data sheets", "Air monitoring results where required", "Appointment letter of the person who controls hazardous chemical agents"]'::jsonb,
   'The Hazardous Chemical Agents Regulations require you to assess how workers are exposed to the chemicals you use, store or produce and to control that exposure. The assessment also decides who needs medical surveillance. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Aloe Coatings in Pietermaritzburg keeps a chemical exposure assessment for its spray booth, backed by air monitoring results from 19 March 2026 and a chemical inventory with safety data sheets for every product.',
   '["Safety data sheets missing or older than the product on the shelf", "Assessing only the chemicals in the store and not those made in the process", "No link between the assessment and medical surveillance"]'::jsonb,
   'SHE'),
  ('HSF-C-17',
   '["Asbestos inventory and survey report", "Asbestos risk assessment and management plan", "Appointment letter of the asbestos work supervisor", "Records of any asbestos removal by a registered contractor"]'::jsonb,
   'Asbestos fibres cause fatal lung disease decades after exposure, and old roofs, ceilings, pipes and floor tiles often contain it. The inventory and management plan show you know where it is and that nobody will disturb it without controls. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Venter Mill Holdings in Bloemfontein keeps an asbestos inventory showing asbestos cement roof sheets on two old sheds, with a management plan dated 5 February 2026 that forbids drilling or cutting without its asbestos work supervisor''s approval.',
   '["Assuming a building is asbestos free because nobody has checked", "Maintenance contractors not told where asbestos is", "Removal done by a contractor who is not registered for asbestos work"]'::jsonb,
   'FAC'),
  ('HSF-C-18',
   '["Lead risk assessment", "Air monitoring or exposure measurement results", "Appointment letter of the lead work supervisor", "Hygiene facilities and clothing arrangements"]'::jsonb,
   'The Lead Regulations require you to assess exposure where people work with lead, for example in battery work, soldering, some paints and smelting. Lead builds up in the body, so the assessment decides the controls and who needs medical surveillance. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Ngema Battery Recyclers in Benoni completed a lead risk assessment on 17 June 2026 covering its breaking and smelting areas, with air monitoring results and a separate clean change room for workers.',
   '["Workers eating or smoking in lead areas", "Work clothing taken home and washed with family laundry", "No air monitoring to back up the assessment"]'::jsonb,
   'SHE'),
  ('HSF-C-19',
   '["Hazardous biological agent risk assessment", "List of biological agents and the tasks that expose people", "Control measures such as vaccination offers, PPE and cleaning procedures", "Risk assessor''s signature and date"]'::jsonb,
   'The Hazardous Biological Agents Regulations require you to assess exposure to germs such as bacteria, viruses and fungi, for example in healthcare, sewage, waste and animal work, and the assessment decides the controls and any medical surveillance. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in your File. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Mthethwa Waste Services assessed its refuse collection teams on 21 January 2026 for exposure to sewage and sharps, and recorded controls including gloves, wash stations and an offer of hepatitis B vaccination.',
   '["Treating biological risk as only a healthcare problem", "No assessment for cleaners who handle waste or sanitary bins", "Medical results filed in the File instead of with the practitioner"]'::jsonb,
   'SHE'),
  ('HSF-C-20',
   '["Psychosocial and fatigue risk assessment", "Shift rosters and overtime records reviewed in the assessment", "Records of support measures (debriefing after violent incidents, access to counselling)", "Risk assessor''s signature and date"]'::jsonb,
   'Long shifts, night work and exposure to violence or aggression cause fatigue, errors and lasting harm to wellbeing. This assessment looks at rosters, rest and support so that tired or traumatised people are not put at risk. Review it every year.',
   'Example: Sentinel Night Retail, a fictitious chain of all night convenience stores in Durban, assessed fatigue and robbery risk on 3 March 2026 and changed its rosters so that no cashier works more than a set number of night shifts in a row, with trauma debriefing after any robbery.',
   '["Looking only at physical hazards", "No review of rosters and overtime", "No support offered after a violent incident"]'::jsonb,
   'HR'),
  ('HSF-C-21',
   '["Major hazard installation risk assessment, done by the approved inspection authority or competent person the governing regulations require", "Inventory of listed substances and quantities held", "On site emergency plan linked to the assessment", "Proof of the notifications the governing regulations require, including to the local emergency services"]'::jsonb,
   'Where you hold large quantities of dangerous substances, a fire, explosion or toxic release can harm your workers and the community around you. The major hazard installation risk assessment sets out what could happen and how you will prevent and respond to it. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Indlovu Gas Storage in Richards Bay commissioned a major hazard installation risk assessment on 10 April 2026 for its LPG storage, and shared the emergency plan with the local fire services.',
   '["Not checking whether stock levels reach the major hazard installation thresholds", "Assessment done but the community and emergency services never informed", "Stock levels increased without updating the assessment"]'::jsonb,
   'SHE'),
  ('HSF-C-22',
   '["Physical agents exposure risk assessment", "Measurement results for heat, cold, lighting, indoor air, vibration or non ionising radiation where they apply", "Control measures and who is affected", "Assessor''s signature and date"]'::jsonb,
   'Heat, cold, poor lighting, stale indoor air, vibrating tools and sources such as lasers or welding arcs can all harm health over time. This assessment shows you looked at each one that applies to your workplace. Review it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Ramaano Brickworks in Polokwane assessed kiln heat, dust in indoor air and hand arm vibration from jackhammers on 25 February 2026, and introduced water stations, rest cycles and anti vibration gloves.',
   '["Only assessing noise and ignoring other physical agents", "No measurements, only guesses", "Office lighting and ventilation never checked"]'::jsonb,
   'SHE'),
  ('HSF-D-01',
   '["Training needs analysis listing each job role and the training it requires", "The risk assessment or job descriptions it was built from", "Signature and date of your section 16(2) assignee approving it"]'::jsonb,
   'It links the hazards in your risk assessment to the training each role needs, so nobody is sent to work untrained and you do not pay for courses that do not fit the job. Your section 16(2) assignee reviews it once a year and whenever a role, process or piece of equipment changes.',
   'Example: Sithole Precast in Brits lists five roles; the batching plant operator needs forklift, hazardous chemical handling and hearing conservation training, while the yard cleaner needs induction, ergonomics and emergency evacuation.',
   '["Listing people instead of roles, so the analysis breaks when staff change", "Copying a generic course list that ignores your own risk assessment", "Forgetting supervisors, appointees and office staff who visit the floor"]'::jsonb,
   'TRAIN'),
  ('HSF-D-02',
   '["Training matrix naming every person, each required course, date completed and expiry date", "A reference to where each certificate is filed", "A monthly sign off or date stamp showing the matrix was checked"]'::jsonb,
   'The matrix is the one page an inspector, auditor or client looks at to see whether your people are trained and in date. Checking it every month lets you book refresher training before a certificate lapses; where Care Net delivered the training, the record can arrive from MyClinicOnline once it is connected.',
   'Example: Mokoena Logistics in Germiston keeps a matrix of its 34 staff; in the June check the safety officer, Lerato Dlamini, flags two forklift certificates expiring and books the refresher before month end.',
   '["A matrix with no expiry column, so lapses go unnoticed", "New starters added to payroll but not to the matrix", "Entries marked done with no certificate on file to prove it"]'::jsonb,
   'TRAIN'),
  ('HSF-D-03',
   '["Signed induction record for each employee, with the date and the modules covered", "Contractor induction records before they start work on site", "Visitor register or visitor induction slip showing site rules were explained"]'::jsonb,
   'Induction is where every person first learns the hazards, the emergency route and how to report a problem, so it protects people from day one. An inspector will often pick names from your staff list and ask to see their induction record; complete one each time a new person, contractor or visitor arrives.',
   'Example: Naidoo Food Packers in Pinetown inducts new packer Sipho Zulu on his first morning; he initials the modules on noise zones, chemical labels and the evacuation route, and his supervisor countersigns.',
   '["Inducting in a language or way the person cannot follow", "No induction for contractors or temporary workers", "Records without the employee''s own signature"]'::jsonb,
   'TRAIN'),
  ('HSF-D-04',
   '["Certificate of each statutory or safety critical course, per person", "Attendance register or provider confirmation for group training", "Training provider''s accreditation or the trainer''s credentials", "Matrix entry showing the expiry date"]'::jsonb,
   'These courses are what the risk assessment and your appointments rely on: without them first aiders, representatives and operators are named on paper but not able to act. Renew each one before the certificate expires; where Care Net delivered the course the record can come from MyClinicOnline once it is connected.',
   'Example: Botha Steel Fabricators in Vanderbijlpark files its fire fighting, first aid and working at height certificates per person, each cross referenced to its training matrix.',
   '["Keeping certificates for people who have left while current staff have none", "Accepting certificates from providers you cannot verify", "Letting refresher dates slip because nobody owns the diary"]'::jsonb,
   'TRAIN'),
  ('HSF-D-05',
   '["Clear copy of each licence, permit or registration card, front and back", "A record of the date you checked it was valid", "Matrix entry showing the expiry date"]'::jsonb,
   'Some work may only be done by a person who holds a licence, permit or registration, and an incident involving an unlicensed person is hard to defend to an inspector, client or insurer. Check each one before the person starts and renew it before it expires.',
   'Example: Khoza Transport in Polokwane copies each driver''s licence and professional driving permit on the first working day of the month and notes the expiry dates on its matrix.',
   '["Copying the licence once at hiring and never checking it again", "No licence on file for relief or temporary operators"]'::jsonb,
   'HR'),
  ('HSF-D-06',
   '["Toolbox talk register with topic, date, presenter and attendee signatures", "The short talk notes or handout used", "Any action raised during the talk and who followed it up"]'::jsonb,
   'Short regular talks keep hazards front of mind and show that you keep informing people after induction, especially after an incident or a change. Your supervisor records each talk as it happens; auditors look for talks that match your real risks and recent incidents.',
   'Example: Pillay Plumbing''s supervisor in Durban runs a Monday talk on trench collapse after a near miss, and six workers sign the register.',
   '["The same talk repeated every week regardless of what is happening on site", "Registers signed by people who were not there", "No link between talks and recent incidents or new hazards"]'::jsonb,
   'OPS'),
  ('HSF-D-07',
   '["Competency assessment record per person, naming the task and the outcome", "The assessor''s name and credentials", "Any observation checklist or practical test used"]'::jsonb,
   'Some roles need proof that a person can actually do the task safely, not only that they sat in a class. A signed assessment shows the person was watched doing the work and judged competent; reassess before the assessment expires or when the task changes.',
   'Example: Mathebula Mining Supplies in Rustenburg has its workshop foreman, a qualified assessor, watch forklift operator Neo Molefe complete a practical route and signs him competent, filing the checklist.',
   '["Treating an attendance certificate as proof of competence", "Assessments signed by someone who is not competent to assess", "No reassessment after a person returns from long absence"]'::jsonb,
   'TRAIN'),
  ('HSF-E-01',
   '["The released Medical Surveillance Plan, a separate Care Net product signed by the OMP", "The list of exposure groups and jobs the Plan covers", "Record of the yearly review and any changes"]'::jsonb,
   'The Plan is Section E''s key evidence: it sets out which people need which examinations, based on the exposures your risk assessment found. It is a separate Care Net product signed by the occupational medical practitioner, and it is reviewed once a year and whenever your exposures change.',
   'Example: Ndlovu Engineering in Middelburg files its Medical Surveillance Plan, a separate Care Net product signed by its OMP,, covering welders for noise and fumes and stores staff for manual handling only.',
   '["A Plan copied from another company that does not match your exposures", "An unsigned draft filed as the final Plan", "No review after a new process or chemical is introduced"]'::jsonb,
   'OH'),
  ('HSF-E-02',
   '["Certificate of fitness per employee showing the outcome: fit, fit with restrictions or unfit", "Baseline certificate for new starters, periodic certificates, and exit certificates for leavers", "The Plan protocol or exposure group each certificate relates to"]'::jsonb,
   'Certificates show that each person was screened against the exposures in the Plan before and while doing the work. Care Net screens fitness for work and does not diagnose; clinical records stay with the occupational health practitioner and only the outcome (fit, fit with restrictions or unfit) goes in your File, renewed before each certificate expires.',
   'Example: Molefe Bricks in Brakpan files a baseline certificate for new kiln operator Themba Mahlangu marked fit, and an exit certificate for a retiring operator marked fit, with no clinical notes attached.',
   '["Filing clinical results or doctors'' letters in the File", "No exit certificates, so later disease claims cannot be traced to a start point", "Letting certificates expire while the person keeps working"]'::jsonb,
   'OH'),
  ('HSF-E-03',
   '["Construction medical certificate of fitness for each person working on the site", "A site list matching each worker to a current certificate", "Certificates for contractors'' workers, obtained from each contractor"]'::jsonb,
   'The Construction Regulations, 2014 expect workers on a construction site to have a valid medical certificate of fitness for the work they do, and the principal contractor checks this at the gate. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Renew each certificate before it expires.',
   'Example: Shabangu Civils in Emalahleni keeps a site list for a road upgrade that ticks each of its 22 workers against a current construction certificate of fitness from Care Net.',
   '["Allowing a worker on site while the certificate is being renewed", "Not collecting certificates from subcontractors", "Certificates that do not state the type of work assessed, such as work at height"]'::jsonb,
   'OH'),
  ('HSF-E-04',
   '["Fitness outcome (fit, fit with restrictions or unfit) for each professional driving permit holder", "Copy of the driver''s current professional driving permit", "A diary of permit and fitness expiry dates"]'::jsonb,
   'A professional driving permit needs a medical fitness declaration, and a driver who becomes unfit puts other road users at risk. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Keep the fitness outcome with the permit copy and renew both before they expire.',
   'Example: Venter Bus Services in Bloemfontein files each driver''s fitness outcome from its occupational health provider next to the permit copy, and diarises both expiry dates.',
   '["Filing the permit medical form itself instead of the fitness outcome", "No check that relief drivers hold a current permit and fitness outcome"]'::jsonb,
   'OH'),
  ('HSF-E-05',
   '["Mine certificate of fitness for each person working at the mine", "The fitness to perform work procedure or code of practice your mine follows", "Access control record linking entry to a current certificate"]'::jsonb,
   'Mines work under the MHSA regime, which has its own fitness requirements and codes of practice, so people must be certified fit before they go underground or into the plant. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Renew before expiry.',
   'Example: Themba Drilling Contractors, working at a quarry near Kuruman, files a mine certificate of fitness for each driller and checks it against the mine''s access card list.',
   '["Using an ordinary certificate of fitness where the mine requires its own", "Contract workers entering on another company''s certificate"]'::jsonb,
   'OH'),
  ('HSF-E-06',
   '["Certificate of fitness for each specific examination your exposures call for", "The Plan protocol that sets the examination and how often it is done", "The exposure group list showing who needs each examination"]'::jsonb,
   'Certain exposures, such as lead, asbestos, hazardous chemical agents, biological agents or noise, come with their own examinations, and people must stay fit for them while exposed. The timing follows the applicable regulation and your Plan, as the OMP sets; clinical results stay with the occupational health practitioner, and only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Hendricks Furniture in Atlantis files noise examination outcomes for its machine shop and solvent examination outcomes for its spray team, each linked to a protocol in its Plan, while the test results stay with the occupational health practitioner.',
   '["Examining everyone for everything instead of by exposure", "Missing the examination for workers moved into an exposed job", "Filing test results instead of the fitness outcome"]'::jsonb,
   'OH'),
  ('HSF-E-07',
   '["Register of fitness restrictions with the person, the restriction as the OMP worded it and its review date", "Record of how each restriction was reflected in the person''s job or duties", "Signed acknowledgement by the employee and supervisor"]'::jsonb,
   'A restriction only protects the person if the job actually changes, and the employer may hold only what it needs to act on, not the medical reason. Record each change as it happens and review it when the certificate is renewed.',
   'Example: Dube Furniture in Pinetown records that sander Mpho Kekana is fit with restrictions, no work above ladder height, and moves him to bench finishing, with both signatures.',
   '["Writing the diagnosis in the register instead of the restriction", "Recording the restriction but not what changed in the job", "Dismissing or moving a person without following a fair process"]'::jsonb,
   'HR'),
  ('HSF-E-08',
   '["Proof that each occupational disease was reported: the date, the body notified and the reference number", "COIDA claim reference and the correspondence that carries no clinical detail", "Actions taken in the workplace after the case", "The fitness outcome only (fit, fit with restrictions or unfit); disease reports and referral letters stay with the occupational health practitioner"]'::jsonb,
   'When a disease may be caused by work, it must be reported and the person referred, so they get care and compensation under COIDA and you can fix the cause. Keep a record each time it happens; the reports, referral letters and clinical details stay with the occupational health practitioner, and only the fitness outcome goes in your File.',
   'Example: Radebe Panelbeaters in Soweto files the date its OMP notified a suspected occupational disease, the COIDA claim reference and the record of its spray booth ventilation repair; the report itself stays with the OMP.',
   '["Treating an occupational disease as a private medical matter and not reporting it", "Filing the disease report or referral letter in the File", "No follow up on the workplace cause"]'::jsonb,
   'OH'),
  ('HSF-E-09',
   '["Current list of first aiders per site and shift, with certificate expiry dates", "Monthly first aid box inspection checklist, signed", "First aid treatment register"]'::jsonb,
   'Someone trained must be able to help an injured person quickly, with a stocked box, on every shift. Your appointed first aider checks the boxes every month, and the treatment register often reveals injuries nobody reported.',
   'Example: Mahlaba Hardware in Mbombela has two first aiders per shift; its store manager, Zanele Mthethwa, ticks the box checklist on the last Friday of every month and replaces used plasters and gloves.',
   '["First aiders whose certificates have lapsed", "Boxes checked but items never replaced", "Night shift or weekends with no first aider on site"]'::jsonb,
   'SHE'),
  ('HSF-E-10',
   '["A signed note describing which medical information the employer holds, which the occupational health practitioner holds, and why", "Who in your company may see certificates of fitness and how they are stored", "Your consent and privacy notice for employees", "Record of the yearly review"]'::jsonb,
   'Health information is sensitive, and privacy law expects you to hold only what you need, for a clear purpose, and keep it secure. The note shows that clinical records stay with the occupational health practitioner and that your File holds only the outcome (fit, fit with restrictions or unfit); review it once a year.',
   'Example: Petersen Laundry in Paarl files a one page note: certificates of fitness sit in a locked HR cabinet and a restricted folder, clinical records stay with its occupational health provider, and only the HR officer and section 16(2) assignee may see outcomes.',
   '["Medical files kept in the general personnel file", "Managers emailing certificates around without control", "No written purpose for holding each kind of record"]'::jsonb,
   'OH'),
  ('HSF-F-01',
   '["Scaffold register listing every scaffold by number, location and erection date", "Signed inspection records by your appointed scaffold inspector", "Handover or tag record showing each scaffold was declared safe before use"]'::jsonb,
   'Scaffold collapses and falls from scaffolds cause serious injuries and deaths. The register proves each scaffold was inspected by your appointed scaffold inspector, and inspected again after bad weather or any change. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Ndlovu Builders in Polokwane numbers its three mobile scaffolds S1 to S3 and its inspector, Sipho Maluleke, signs a green tag and the register page before the plasterers start each Monday.',
   '["Inspection pages signed by someone who is not the appointed scaffold inspector", "Scaffolds hired in by a subcontractor missing from your register", "No inspection recorded after strong wind or heavy rain"]'::jsonb,
   'OPS'),
  ('HSF-F-02',
   '["Ladder register with a number, type and location for every ladder", "Inspection checklist pages signed by your ladder inspector", "A note of damaged ladders removed from use and how they were destroyed"]'::jsonb,
   'Falls from ladders are one of the most common serious injuries in small businesses. The register shows every ladder is inspected and that damaged ones are taken out of service instead of being left for someone to use. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Pillay Shopfitters in Durban paints a number on each of its eight ladders; in March its ladder inspector, Kevin Naidoo, cuts up ladder L5 after finding a cracked stile and records it in the register.',
   '["Ladders in the storeroom or vehicles never added to the register", "Damaged ladders marked on the register but still in use", "Homemade or painted over wooden ladders that hide defects"]'::jsonb,
   'OPS'),
  ('HSF-F-03',
   '["Register of every lifting machine and item of lifting tackle, with a unique number and safe working load", "Load test certificates for each machine", "Signed inspection records by your lifting machine and lifting tackle inspector"]'::jsonb,
   'A failed chain, sling or hoist can drop a load onto people. The register and certificates prove each item was load tested and inspected, and inspectors and clients ask for the certificates before a crane or hoist is used on site. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Van Wyk Steel in Vanderbijlpark keeps a register of two overhead cranes and forty slings and shackles, each tagged with its safe working load, and files the load test certificate for crane C1 dated 12 May 2026.',
   '["Slings and shackles not individually numbered, so nobody can prove which were inspected", "Load test certificates expired or missing for hired equipment", "Damaged tackle left in the rack instead of being quarantined"]'::jsonb,
   'ENG'),
  ('HSF-F-04',
   '["Register of portable electrical tools and extension leads with an asset number for each", "Inspection and test records signed by the appointed electrical installation supervisor", "Record of faulty tools withdrawn and repaired or scrapped"]'::jsonb,
   'Damaged cables and faulty tools cause shocks, burns and fires. The register proves every drill, grinder and extension lead is inspected and that faulty items are tagged out before someone is hurt. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Mthembu Joinery in Pietermaritzburg tags its 22 power tools with coloured labels after each inspection and records that grinder G4 was withdrawn on 8 July 2026 for a damaged plug.',
   '["Workers'' own tools brought from home never inspected", "Extension leads and multi plugs left off the register", "Tags on the tools but no matching register entry"]'::jsonb,
   'ENG'),
  ('HSF-F-05',
   '["Electrical certificate of compliance for each site or installation", "Installation inspection register signed by the electrical installation supervisor", "A new certificate or record for every alteration or addition to the installation"]'::jsonb,
   'An unsafe electrical installation can cause electrocution and fire. The certificate proves a registered person tested the installation and the register shows it is inspected; landlords, insurers and inspectors routinely ask for both. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Botha Printing in Bloemfontein files the certificate of compliance issued when it moved into its unit, plus a second certificate for the new press circuit added in April 2026.',
   '["Relying on the landlord''s certificate without a copy on file", "No new certificate after a circuit or distribution board was added", "Inspection register started but not kept up"]'::jsonb,
   'ENG'),
  ('HSF-F-06',
   '["Register of every fire extinguisher, hose reel and hydrant with its location", "Service certificates or labels from the fire equipment service provider", "Routine visual check records between services, signed by your fire equipment inspector"]'::jsonb,
   'Fire equipment that is empty, blocked or out of service cannot save anyone. The register shows every item is checked and serviced, and your insurer and the local fire authority may ask to see it. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Khumalo Motors in Soweto lists nine extinguishers and two hose reels on a site plan; its fire equipment inspector, Palesa Mokoena, initials each service label monthly and files the service provider''s certificate dated February 2026.',
   '["Extinguishers moved around the site so the register no longer matches", "Service certificates filed but no record of the checks between services", "Equipment blocked by stock or pallets"]'::jsonb,
   'FAC'),
  ('HSF-F-07',
   '["Emergency lighting test records per site", "Exit and escape route signage checklist", "Record of faulty lights or signs fixed, with dates"]'::jsonb,
   'When the power fails during an emergency, people need lights and signs to find the way out. These records prove emergency lighting and signage are tested and repaired when they fail. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Molefe Cold Storage in Rustenburg switches off the mains in its warehouse once a month, times the emergency lights and records that the fitting above exit B failed on 4 August 2026 and was replaced two days later.',
   '["Lights tested but the test not written down", "Signs covered by racking or new partitions", "Load shedding assumed to count as a test without any record"]'::jsonb,
   'FAC'),
  ('HSF-F-08',
   '["Register of compressors, air receivers, boilers and other pressure equipment", "Inspection and test certificates for each vessel", "Records of safety valve checks signed by the pressure equipment supervisor"]'::jsonb,
   'Pressure vessels can explode with enough force to kill. The register and certificates prove every vessel was inspected and tested and that its safety devices work. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Dlamini Panelbeaters in Mbombela registers one compressor and air receiver, files its inspection certificate from May 2026 and keeps a sticker on the receiver showing the next inspection date.',
   '["Small compressors assumed to be exempt without checking", "Certificates for the compressor but not for the air receiver", "No record of who is appointed to supervise the equipment"]'::jsonb,
   'ENG'),
  ('HSF-F-09',
   '["Register of vehicles, forklifts and mobile plant with a unique number for each", "Daily pre use checklists signed by the operator", "Service and maintenance records for each machine"]'::jsonb,
   'Mobile plant and vehicles injure pedestrians and operators when brakes, lights, horns or reverse alarms fail. Daily checks catch faults before a shift starts, and the maintenance record shows faults are fixed, not just noted.',
   'Example: Sibiya Earthworks in Emalahleni keeps a daily checklist book in each of its four machines; its mobile plant supervisor, Themba Zulu, reviews the books every Friday and files them with the service invoices.',
   '["Checklists ticked in advance or all signed at the end of the week", "Defects noted on the checklist but no repair record", "Hired machines never added to the register"]'::jsonb,
   'OPS'),
  ('HSF-F-10',
   '["Excavation inspection register for each open excavation", "Daily inspection entries signed by the excavation supervisor", "Record of inspections after rain, blasting or any collapse"]'::jsonb,
   'Trench collapses bury workers in seconds. Checking every excavation every day, and again after rain or other changes, is how you catch cracking, water and loose material before anyone is trapped.',
   'Example: Mahlangu Civils keeps a register for its sewer trench in Mamelodi; its excavation supervisor, Johannes Mathebula, records the shoring and edge protection each morning and adds an extra entry after the storm on 16 October 2026.',
   '["Entries missed on days when the supervisor was off site", "No extra inspection after heavy rain", "Shallow excavations ignored even where people work in them"]'::jsonb,
   'OPS'),
  ('HSF-F-11',
   '["Personal protective equipment issue register signed by each person on receipt", "A list of what equipment each job role needs, taken from your risk assessment", "Records of inspections and replacement of worn or damaged equipment"]'::jsonb,
   'Personal protective equipment is the last line of defence, so it must match the hazard, fit the person and be in good condition. The signed register proves each person received the right equipment, and it helps when a worker disputes what they were given.',
   'Example: Nkosi Cleaning Services in Durban issues gloves, goggles and aprons to its 18 cleaners; each signs the issue register, and the supervisor, Ayanda Cele, replaces torn gloves weekly and records it.',
   '["Equipment handed out with no signature", "One size bought for everyone so it does not fit", "The register not updated when the job or the chemicals change"]'::jsonb,
   'SHE'),
  ('HSF-F-12',
   '["Register of every hazardous chemical, with where it is stored and roughly how much you hold", "A current safety data sheet for each chemical", "Storage inspection records signed by the hazardous chemical agent controller"]'::jsonb,
   'You cannot control chemicals you have not listed. The register and safety data sheets tell workers, first aiders and emergency services what each substance does and how to handle a spill or exposure, and they underpin the chemical risk assessment and any medical surveillance under the Hazardous Chemical Agents Regulations. Update it whenever a chemical is added, removed or moved.',
   'Example: Govender Pool Supplies in Umhlanga lists 14 chemicals, keeps their safety data sheets in a red file at the store entrance, and its controller, Priya Govender, updates the register the day a new product arrives.',
   '["Safety data sheets missing or years out of date", "Cleaning products and workshop sprays left off the register", "No quantities, so the risk of a large spill is unknown"]'::jsonb,
   'SHE'),
  ('HSF-F-13',
   '["Asbestos inventory listing each location, type and condition of asbestos containing material", "The survey or report the inventory is based on", "Signed inspection records by the asbestos work supervisor"]'::jsonb,
   'Asbestos fibres released from damaged material cause fatal lung diseases years after exposure. The inventory tells maintenance staff and contractors where asbestos is so nobody drills, cuts or breaks it unprotected, and the inspections track its condition. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Mofokeng Properties in Kimberley keeps an inventory showing asbestos cement roof sheets on two older buildings, marked on a site plan that every contractor must see before starting work.',
   '["Assuming a building has no asbestos without a survey", "Contractors not shown the inventory before drilling or roofing work", "Condition not rechecked after storms or renovations"]'::jsonb,
   'FAC'),
  ('HSF-F-14',
   '["Register of machines with moving parts that need guards", "Guarding inspection checklists signed by the general machinery supervisor", "Records of missing or damaged guards and when they were replaced"]'::jsonb,
   'Unguarded belts, gears, blades and rollers cause amputations. The register proves guards are checked and that a machine is stopped when a guard is missing. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Venter Packaging in Paarl lists 11 machines; its general machinery supervisor, Riaan Venter, finds a missing guard on the slitter in June 2026, locks the machine out and records the repair the next day.',
   '["Guards removed for cleaning and not refitted", "New or second hand machines not added to the register", "Interlocks bypassed without anyone noticing"]'::jsonb,
   'ENG'),
  ('HSF-F-15',
   '["Monthly walkabout or housekeeping checklist per area", "Photographs of findings where useful", "An action list showing who fixed each finding and when"]'::jsonb,
   'Most slips, trips and many fires start with poor housekeeping. A supervisor walking the site every month and writing down what needs fixing shows you look for hazards before they cause harm.',
   'Example: Hlongwane Hardware in Mthatha has its floor supervisor, Nomsa Hlongwane, walk the yard and store monthly; in September 2026 she records blocked aisle 3 and an oil spill at the loading bay, both cleared the same day.',
   '["Checklists ticked with no findings month after month", "Findings written down but never closed", "Outside areas and storerooms skipped"]'::jsonb,
   'OPS'),
  ('HSF-F-16',
   '["Monthly stacking and storage inspection checklist", "Racking load signs and any racking inspection report", "Record of damaged racking or unstable stacks and the action taken"]'::jsonb,
   'Collapsing racks and falling stock crush people. The monthly inspection by your stacking and storage supervisor shows stacks are stable, racking is undamaged and loads stay within the marked limits.',
   'Example: Mabaso Distribution in Pinetown has its stacking supervisor, Lindiwe Mabaso, inspect the warehouse monthly; she records a bent upright in bay 12 hit by a forklift and the bay is emptied until it is repaired.',
   '["Racking damage from forklifts not reported", "No load limits shown on the racking", "Stacks built higher than the storage supervisor allows"]'::jsonb,
   'OPS'),
  ('HSF-F-17',
   '["Register of harnesses, lanyards, lifelines and anchor points with a number for each", "Pre use check records signed by the user or the fall protection planner", "Records of equipment withdrawn after a fall or damage"]'::jsonb,
   'A harness that fails in a fall is worse than none. Checking fall arrest equipment before each use, and taking it out of service after a fall or damage, is what keeps it reliable.',
   'Example: Maseko Roofing in East London numbers its six harnesses; each roofer checks and signs the card before going up, and harness H2 is destroyed after it arrested a fall on 21 July 2026.',
   '["Pre use checks done but not recorded", "Harnesses kept after arresting a fall", "Anchor points never checked"]'::jsonb,
   'OPS'),
  ('HSF-F-18',
   '["Confined space register listing every tank, pit, manhole, silo or vessel people may enter", "Warning signs or photographs showing each space is marked", "The hazards and entry controls noted for each space"]'::jsonb,
   'People die in confined spaces from lack of oxygen, toxic gas or engulfment, and often the rescuers die too. The register makes sure every such space is known, marked and entered only under a permit.',
   'Example: Modise Water Services in Mahikeng lists four sumps and two reservoirs as confined spaces, each with a padlocked hatch and a warning sign, supervised by its confined space supervisor, Kagiso Modise.',
   '["Only obvious tanks listed while pits and ducts are forgotten", "Spaces not marked, so workers enter without a permit", "Register not updated when new tanks or pits are built"]'::jsonb,
   'OPS'),
  ('HSF-F-19',
   '["Register of explosive powered tools with a serial number for each", "Issue and return log signed by the explosive powered tool issuer", "Cartridge issue and return records"]'::jsonb,
   'Explosive powered tools can fire nails through materials and people, and cartridges must never go missing. The issue log shows each tool and every cartridge went to an authorised operator and came back.',
   'Example: Zwane Ceilings in Emalahleni keeps its two nail guns in a locked box; the issuer, Mandla Zwane, records each issue with the operator''s name and the cartridges given and returned.',
   '["Tools lent to workers who are not authorised operators", "Spent and unused cartridges not counted back in", "Tools left on site overnight unsecured"]'::jsonb,
   'OPS'),
  ('HSF-F-20',
   '["Monthly welfare facilities checklist covering toilets, basins, drinking water, change rooms and eating areas", "Cleaning schedules signed by cleaning staff", "Records of faults reported and fixed"]'::jsonb,
   'Dirty or broken toilets, no clean water and nowhere hygienic to eat affect health and morale, and they are among the first things an inspector or worker complains about. The monthly check shows these facilities are kept working and clean.',
   'Example: Mokwena Farming in Tzaneen checks the toilets, water point and eating shelter at its packhouse monthly; in August 2026 it records a broken tap and the plumber''s repair two days later.',
   '["Only the office toilets checked, not those used by field or shift workers", "Faults noted but no repair date", "No soap or towels recorded as an issue month after month"]'::jsonb,
   'FAC'),
  ('HSF-F-21',
   '["Lighting, ventilation and temperature measurement reports", "The name and credentials of the person or body that took the measurements", "A list of the actions you took on the recommendations"]'::jsonb,
   'Poor lighting causes accidents and eye strain, and poor ventilation or heat makes people ill. Measured results show where conditions need improving and prove you acted. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Nkuna Textiles in Hammarsdale has an occupational hygienist measure lighting, ventilation and heat on its weaving floor; the report finds the dye house too hot and an extraction fan is added in May 2026.',
   '["Measurements never taken, only a walk through opinion", "Reports filed without the recommendations being actioned", "No new measurements after a move or a big layout change"]'::jsonb,
   'SHE'),
  ('HSF-F-22',
   '["Waste register listing each waste type, quantity and date removed", "Name of the licensed waste contractor for each waste stream", "Monthly register sign off"]'::jsonb,
   'Hazardous waste that is stored badly or dumped can harm workers, neighbours and the environment. The register tracks what waste you create and where it goes, and signing it off every month links it to the disposal certificates in Section M.',
   'Example: Mhlongo Auto Repairs in Pietermaritzburg records used oil, oil filters and batteries monthly, each collected by a licensed recycler whose collection slip is filed in Section M.',
   '["General and hazardous waste mixed in the same skip", "Quantities guessed or left blank", "No link between the register and the disposal certificates"]'::jsonb,
   'FAC'),
  ('HSF-G-01',
   '["Your written permit to work procedure listing which jobs need a permit", "A numbered permit register showing every permit issued, who issued it and when it was closed", "Blank permit forms for each permit type"]'::jsonb,
   'A permit to work system makes sure dangerous jobs are checked, authorised and closed off by competent people. The register proves the system runs and lets you find any permit quickly if something goes wrong. Review the procedure whenever new high risk work starts.',
   'Example: Moloi Engineering in Germiston uses a numbered permit book; permit number 214, issued on 3 September 2026 for welding in the paint shop, is recorded as closed at 16:30 the same day.',
   '["Permits used but no register to track them", "Procedure not reviewed when new high risk work starts", "Permits issued by people who are not authorised to issue them"]'::jsonb,
   'SHE'),
  ('HSF-G-02',
   '["Completed hot work permits for welding, cutting and grinding outside the workshop", "The fire watch record for each permit", "Sign off showing the area was checked after the work ended"]'::jsonb,
   'Sparks from welding and grinding start fires that can smoulder for hours. A hot work permit makes someone remove combustibles, provide fire equipment and check the area afterwards.',
   'Example: Kruger Welding in Middelburg issues a hot work permit for repairs in a feed store; its hot work supervisor, Pieter Kruger, records the fire watch and signs the area clear an hour after the job ends.',
   '["No fire watch after the work ends", "Permit issued for the whole week instead of each job", "Combustibles left nearby because the area was not inspected"]'::jsonb,
   'OPS'),
  ('HSF-G-03',
   '["Completed confined space entry permits", "Gas test readings taken before and during entry", "Names of entrants, the standby person and the rescue arrangements"]'::jsonb,
   'Most confined space deaths happen because the air was not tested or no one was standing by. The permit proves the atmosphere was tested, the space isolated, a standby person present and rescue ready before anyone went in.',
   'Example: Modise Water Services in Mahikeng issues an entry permit to clean sump 2; the supervisor records oxygen and gas readings at 08:00 and 10:00 and names the standby person at the hatch.',
   '["Gas readings not recorded or the detector not calibrated", "No standby person named", "Permit not closed and the space not secured afterwards"]'::jsonb,
   'OPS'),
  ('HSF-G-04',
   '["Excavation permits for each dig", "Service clearance records showing buried cables and pipes were located", "Drawings or scan records from the service owners"]'::jsonb,
   'Hitting an underground cable or gas pipe can kill instantly, and unsupported excavations collapse. The permit proves services were located and the excavation method agreed before digging started.',
   'Example: Mahlangu Civils obtains service drawings from the municipality, scans the route in Mamelodi and issues excavation permit 41 on 2 October 2026 before the excavator starts.',
   '["Digging started before service drawings arrived", "Hand digging near services not required on the permit", "Permit not updated when the dig was extended"]'::jsonb,
   'OPS'),
  ('HSF-G-05',
   '["Working at height permits for each job", "Reference to the fall protection plan for the task", "Record of the equipment and anchor points used"]'::jsonb,
   'Falls from height are a leading cause of death at work. The permit makes the supervisor confirm edge protection, fall arrest equipment and rescue arrangements are in place before anyone climbs.',
   'Example: Maseko Roofing in East London issues a working at height permit for a warehouse roof in Gonubie, listing the anchor points, the harnesses by number and the rescue plan.',
   '["Short jobs done without a permit because they only take a few minutes", "No rescue plan for a worker left hanging in a harness", "Permit not linked to the fall protection plan"]'::jsonb,
   'OPS'),
  ('HSF-G-06',
   '["Electrical isolation and lockout records for each job", "Lock and tag register showing who holds which lock", "Test records showing the equipment was proved dead before work"]'::jsonb,
   'Equipment that is switched back on while someone works on it can electrocute or crush them. Lockout records prove the energy was isolated, locked, tagged and tested dead, and that only the person who fitted the lock removed it.',
   'Example: Botha Printing in Bloemfontein records that its electrician, Johan Botha, isolated press 2, fitted lock 7 and his personal tag, tested for zero voltage and removed the lock at 14:10.',
   '["Tags used without locks", "Shared locks, so nobody knows who is still working", "No test for dead before starting work"]'::jsonb,
   'ENG'),
  ('HSF-G-07',
   '["Lifting operation permits for non routine or heavy lifts", "The lifting plan with load weight, crane and tackle to be used", "Record of the operator and signaller for each lift"]'::jsonb,
   'Dropped loads and overturned cranes kill people below. The lifting permit makes a competent person plan the lift, check the equipment and keep people out of the danger zone.',
   'Example: Van Wyk Steel in Vanderbijlpark issues a lifting permit to place a steel beam of about four tonnes, recording crane C1, two numbered slings, the operator and the signaller.',
   '["Load weight guessed instead of confirmed", "Tackle used that is not on the lifting register", "No exclusion zone recorded"]'::jsonb,
   'OPS'),
  ('HSF-G-08',
   '["Demolition permits for each stage of the work", "The demolition method statement", "Records of services disconnected and asbestos checks done before work"]'::jsonb,
   'Uncontrolled demolition causes collapses and falling debris and can release asbestos. The permit proves the structure was assessed, services disconnected and the work sequence agreed before demolition began.',
   'Example: Mokoena Demolition in Welkom issues a permit to take down an old workshop wall only after its demolition supervisor, David Mokoena, confirms the power is disconnected and the asbestos survey is clear.',
   '["Demolition started before services were confirmed off", "No asbestos check on older buildings", "Permit covering the whole job instead of each stage"]'::jsonb,
   'OPS'),
  ('HSF-G-09',
   '["Written approval from the road authority for the closure or lane restriction", "The traffic accommodation layout with signs, cones and flag people", "Daily checks that the layout is in place"]'::jsonb,
   'Workers on or next to a road are at risk from passing vehicles. The approval and layout show the road authority agreed how traffic is controlled and that your team set it out correctly each day.',
   'Example: Sibiya Earthworks obtains approval from the local roads department to close one lane of a street in Secunda for three days, and its flag person records the layout checks each morning.',
   '["Work started before written approval arrived", "Layout on site different from the approved drawing", "Signs left out after the work ended"]'::jsonb,
   'OPS'),
  ('HSF-G-10',
   '["Current licence or authorisation for each radiation source or device", "Register of sources with their location", "Appointment of your radiation protection officer and personal dose monitoring records"]'::jsonb,
   'Radiation cannot be seen or felt and can cause serious harm. The authorisation proves the regulator has approved your use of the source, and the records show it is controlled by a competent radiation protection officer and renewed before it expires.',
   'Example: Tshabalala Pipe Inspection in Sasolburg files the authorisation for its industrial radiography source, with the expiry date marked in the File diary two months ahead.',
   '["Authorisation expired while the source is still in use", "Source moved to a new site without updating the authorisation", "Dose monitoring badges not returned on time"]'::jsonb,
   'ENG'),
  ('HSF-H-01',
   '["An emergency plan for each site naming the emergency coordinator and wardens", "A site plan showing exits, escape routes, assembly points and fire equipment", "Emergency contact numbers, checked and dated"]'::jsonb,
   'In a fire, gas leak or other emergency, people panic unless they know what to do. The plan, reviewed once a year and whenever the site changes, tells everyone where to go and who is in charge, and it is one of the first documents an inspector or client asks for.',
   'Example: Maluleke Foods in Tzaneen has a two page plan for its packhouse naming Grace Maluleke as emergency coordinator, with a marked site plan at each exit and the assembly point at the main gate.',
   '["One plan copied across different sites with the wrong exits", "Wardens who have left the company still named", "Night shift left without a named coordinator"]'::jsonb,
   'SHE'),
  ('HSF-H-02',
   '["A schedule of planned emergency drills", "A record for each drill with the date, scenario and time taken to evacuate", "Findings from the drill and the corrective actions taken"]'::jsonb,
   'A drill tests whether the plan works in real life: whether alarms are heard, exits are clear and everyone is accounted for. Holding drills and fixing what they reveal is what makes the plan dependable. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Pillay Shopfitters in Durban runs an evacuation drill on 14 May 2026; the factory clears in four minutes, but the spray booth staff did not hear the alarm, so a flashing light is added.',
   '["Drills held but not written up", "The same findings repeated drill after drill without action", "Only day shift ever drilled"]'::jsonb,
   'SHE'),
  ('HSF-H-03',
   '["Fire risk assessment for each site", "A fire plan covering prevention, detection, fire fighting and evacuation", "Any approval or inspection report from the local fire authority"]'::jsonb,
   'Fire can destroy a business and kill people in minutes. The fire risk assessment finds what could start a fire and what would help it spread, and the plan, reviewed once a year, sets out how you prevent, detect and respond to it.',
   'Example: Govender Pool Supplies in Umhlanga identifies its chlorine store and forklift charging bay as its main fire risks and moves the charging bay away from the stock racking.',
   '["Fire risk assessment copied from another business", "Changes in stored materials not reflected in the plan", "No reference to the local fire authority''s requirements"]'::jsonb,
   'FAC'),
  ('HSF-H-04',
   '["Written medical emergency arrangements for each site and shift", "Names of first aiders and where the first aid boxes are", "Nearest hospital or clinic, ambulance number and directions"]'::jsonb,
   'When someone is injured, minutes matter. The arrangements, reviewed once a year, make sure a trained first aider and a stocked box are always available and that everyone knows how to get help fast.',
   'Example: Mokwena Farming in Tzaneen posts a card at each packhouse door naming its first aiders per shift, the box locations, and the route to the nearest hospital.',
   '["First aider lists not updated when staff leave or shifts change", "Remote sites without a first aider on every shift", "Directions to the hospital never checked"]'::jsonb,
   'OH'),
  ('HSF-H-05',
   '["Written spill response procedure for your chemicals", "A list of spill kits, their contents and locations", "Records of spill drills or actual spills and how they were cleaned up"]'::jsonb,
   'A chemical spill can burn, poison or cause fire, and it can reach drains and rivers. The procedure, reviewed once a year, and the spill kits make sure people contain and clean it up safely using the safety data sheets.',
   'Example: Nkosi Cleaning Services in Durban keeps a spill kit at its chemical store; when a container of degreaser splits in March 2026, the team contains it and records what was used and how the waste was disposed of.',
   '["Spill kits empty after the last use", "Staff never shown how to use the kit", "Procedure not matched to the chemicals you actually hold"]'::jsonb,
   'SHE'),
  ('HSF-H-06',
   '["The on site emergency plan for the major hazard installation", "Records of information given to the public and neighbours who could be affected", "Records of liaison with the local emergency services and the municipality"]'::jsonb,
   'A major hazard installation can harm people well beyond its fence. The plan and public information prove that you, your neighbours and the emergency services know what to do if a major incident happens. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Nel Gas Storage in Secunda shares an information leaflet with the nearby school and businesses and files the minutes of its meeting with the municipal disaster management officer.',
   '["Neighbours never told about the hazard", "The plan not shared with the local fire services", "Contact details for the municipality out of date"]'::jsonb,
   'SHE'),
  ('HSF-H-07',
   '["Security emergency procedures, such as for armed robbery, bomb threats or unrest", "Contact details for your security provider and the police", "Records of security staff briefings on these procedures"]'::jsonb,
   'Security incidents put staff and guards at serious risk. Written procedures, reviewed once a year, tell people how to stay safe and who to call. Where guards are supplied, this ties in with the security provider working under the PSIRA regime.',
   'Example: Khumalo Motors in Soweto has a one page armed robbery procedure telling staff not to resist, to press the panic button and to gather in the service bay office, and the guards sign that they were briefed.',
   '["Procedures kept by the security company but not on your File", "New guards never briefed", "Panic buttons not tested"]'::jsonb,
   'FAC'),
  ('HSF-H-08',
   '["A document showing how your emergency plan links to the municipal disaster management plan", "Contact details for the municipal disaster management centre", "Records of any joint planning or exercises"]'::jsonb,
   'A major incident at your site may need the municipality''s disaster management services. Recording how your plan fits theirs, reviewed once a year, makes sure help arrives quickly and nobody works from different assumptions.',
   'Example: Nel Gas Storage in Secunda files a letter from the municipal disaster management centre confirming it holds a copy of the site emergency plan, dated 10 June 2026.',
   '["No contact ever made with the municipality", "Municipal contact numbers never checked", "Plan updated but the municipality not sent the new version"]'::jsonb,
   'SHE'),
  ('HSF-I-01',
   '["Your written incident and near miss reporting procedure", "The reporting form employees use", "Evidence that staff were told how to report, such as a toolbox talk register"]'::jsonb,
   'People can only report what they know how to report. The procedure, reviewed once a year, tells everyone what to report, to whom and how fast, so injuries and near misses are recorded and serious incidents reach the inspector in time.',
   'Example: Mabaso Distribution in Pinetown uses a one page report form kept at each supervisor''s desk and explains the procedure at every induction.',
   '["Procedure written but staff do not know it exists", "Near misses left out of the procedure", "No named person to receive reports on night shift"]'::jsonb,
   'SHE'),
  ('HSF-I-02',
   '["The incident register with each incident recorded", "Supporting incident report forms", "Signature of the person who keeps the register"]'::jsonb,
   'The register is the official record of injuries and incidents at your workplace. Recording each event as it happens lets you spot trends, supports COIDA claims and is one of the first things an inspector asks to see.',
   'Example: Venter Packaging in Paarl records a hand laceration on the slitter on 11 June 2026, with the injured person, time, place and first aid given, and links it to investigation report number 7.',
   '["Minor injuries not recorded because no time was lost", "Register kept on loose sheets that go missing", "Contractor injuries left out"]'::jsonb,
   'SHE'),
  ('HSF-I-03',
   '["Copies of the reports made to the inspector for each reportable incident", "Proof of the date and way each report was sent", "The matching internal incident record"]'::jsonb,
   'Certain serious incidents must be reported to the inspector without delay. Your File needs proof that each one was reported, because failing to report is itself an offence and it hides serious risks.',
   'Example: Sibiya Earthworks files the report sent to the Department of Employment and Labour after a worker was hospitalised in a machine incident in Emalahleni, with the email confirmation of receipt.',
   '["Not knowing which incidents must be reported", "No proof the report was received", "Report made by phone with no written record"]'::jsonb,
   'SHE'),
  ('HSF-I-04',
   '["Investigation report for each incident, with the facts, root cause and corrective actions", "Witness statements, photographs and sketches", "Sign off by the incident investigator and management"]'::jsonb,
   'An investigation finds out why something happened so it does not happen again. Each report, done after every incident by your incident investigator, shows the real cause was found and fixed, not just that someone was blamed.',
   'Example: Venter Packaging in Paarl finds that the slitter injury happened because the guard was removed for cleaning and not refitted, and adds an interlock and a cleaning procedure.',
   '["The cause recorded as worker carelessness with no deeper look", "Corrective actions without owners or dates", "Near misses never investigated"]'::jsonb,
   'SHE'),
  ('HSF-I-05',
   '["Employer''s reports of accidents and diseases submitted under COIDA, or proof of the date each was submitted", "Claim numbers and correspondence for each claim", "Proof that the medical reports for each claim were sent, with the reports themselves kept by the occupational health practitioner"]'::jsonb,
   'COIDA lets injured or ill workers receive compensation without suing you, but only if claims are reported and followed through. Your records show each claim was lodged, followed up and closed, and protect you if a claim is disputed. The COIDA papers in your File hold the employer''s report, dates, claim numbers and payment letters; medical reports and other clinical records stay with the occupational health practitioner.',
   'Example: Mhlongo Auto Repairs in Pietermaritzburg files the employer''s report for a mechanic''s burned hand, the claim number from the Compensation Fund and the final payment letter.',
   '["Claims lodged late or not at all", "No follow up once a claim number is issued", "Claim papers mixed with personnel files so nobody can find them"]'::jsonb,
   'HR'),
  ('HSF-I-06',
   '["Confirmation from the occupational medical practitioner that a notification was made", "The date, the body notified and its reference number", "The outcome of fitness only: fit, fit with restrictions or unfit"]'::jsonb,
   'When a work related disease is found, it must be reported so the worker can be compensated and the cause controlled. The clinical records stay with the occupational health practitioner; your File holds only proof that the notification was made and the fitness outcome, never the clinical details.',
   'Example: Van Wyk Steel in Vanderbijlpark files a letter from its occupational medical practitioner confirming a notification was made on 5 August 2026, with the body notified, its reference number and the worker''s outcome recorded as fit with restrictions.',
   '["Clinical reports or test results filed in the File", "Notification left to the employee to arrange", "No change made to controls after the disease was found"]'::jsonb,
   'OH'),
  ('HSF-I-07',
   '["Corrective and preventive action register listing each action, owner and due date", "Closure evidence such as photos, invoices or training records", "Monthly review sign off"]'::jsonb,
   'Findings from incidents, inspections and audits only reduce risk if they are acted on. The register, reviewed every month, tracks each action to closure and shows an inspector that problems are fixed, not forgotten.',
   'Example: Mabaso Distribution in Pinetown tracks 12 actions in a spreadsheet; the October review closes the racking repair with a photo and moves the late signage action to a new date.',
   '["Actions closed without evidence", "Overdue actions not escalated", "Separate lists for incidents, audits and inspections that never get combined"]'::jsonb,
   'SHE'),
  ('HSF-J-01',
   '["Occupational hygiene survey programme listing each hazard, the survey needed and when it is due", "Link to the risk assessment the programme is based on", "Annual review sign off"]'::jsonb,
   'The programme makes sure measurements are planned, not forgotten. Reviewed once a year, it links hazards from your risk assessment to the surveys that prove exposure is controlled and tells you what to budget for.',
   'Example: Sithole Precast in Brits plans noise, dust and illumination surveys in its programme, with the noise survey booked for March and the dust survey for July 2026.',
   '["Surveys ordered one by one with no plan", "Programme not updated when new processes start", "Due dates not tracked so surveys lapse"]'::jsonb,
   'SHE'),
  ('HSF-J-02',
   '["Noise survey report by a competent person or approved inspection authority, as your practitioner confirms", "Noise zone map showing where hearing protection is required", "Photographs of the noise zone signs in place"]'::jsonb,
   'Loud noise causes permanent hearing loss that cannot be reversed. The survey shows where noise is too high so you can mark noise zones, reduce noise at source and include the right people in medical surveillance. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Sithole Precast in Brits receives a noise survey in March 2026 from the surveyor its practitioner confirmed; the batching plant and block press are marked as noise zones and signs are put up the same week.',
   '["Survey done by someone the practitioner has not confirmed as competent for noise surveys", "Noise zones on the map but no signs on site", "No new survey after new machines were installed"]'::jsonb,
   'SHE'),
  ('HSF-J-03',
   '["Exposure monitoring report by an approved inspection authority", "The list of chemicals and work areas measured", "Your actions on the report''s recommendations"]'::jsonb,
   'Some chemicals cause cancer, lung disease or poisoning long after exposure. Monitoring proves whether controls keep exposure low enough under the Hazardous Chemical Agents Regulations, and it decides who needs medical surveillance. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Govender Pool Supplies in Umhlanga has an approved inspection authority measure chlorine exposure in the mixing room in June 2026 and adds extraction after the report recommends it.',
   '["Monitoring skipped because the smell seems fine", "Report filed but recommendations not actioned", "Only some shifts or areas measured"]'::jsonb,
   'SHE'),
  ('HSF-J-04',
   '["Illumination survey report with measurements per work area", "The name of the competent person who measured", "Record of lighting improvements made"]'::jsonb,
   'Poor lighting causes trips, mistakes with machines and eye strain. The survey shows which areas are too dark so you can fix them. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Radebe Call Centre in Midrand has its illumination measured in April 2026, finds the stairwell and two workstations too dark, and replaces the fittings.',
   '["Lighting judged by eye, not measured", "Outdoor work areas and stairways left out", "No new survey after a layout change"]'::jsonb,
   'FAC'),
  ('HSF-J-05',
   '["Ventilation and thermal survey report", "Measurements for hot, cold or poorly ventilated areas", "Actions taken, such as fans, extraction, rest breaks or water points"]'::jsonb,
   'Heat, cold and stale air make people ill, and heat stress can kill. The survey shows which areas are a risk and supports controls such as breaks, water and extraction. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Molefe Bakery in Rustenburg has its oven area surveyed in November 2026, finds high heat stress and introduces extra breaks, cool water and an extraction fan.',
   '["Only measured in winter", "Cold stores ignored", "Actions not linked to the survey results"]'::jsonb,
   'FAC'),
  ('HSF-J-06',
   '["Asbestos air monitoring reports during and after asbestos work", "Clearance certificate before the area is reoccupied, where the governing regulations or your practitioner require one", "The name of the approved body that did the monitoring"]'::jsonb,
   'Asbestos fibres are invisible and deadly. Air monitoring proves fibres stayed controlled during the work and that the area was safe before people returned. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Mofokeng Properties in Kimberley receives air monitoring results and a clearance certificate after its asbestos roof sheets are removed in July 2026, before tenants move back in.',
   '["Area reoccupied before clearance", "No monitoring during the work itself", "Monitoring done by an unapproved body"]'::jsonb,
   'SHE'),
  ('HSF-J-07',
   '["Lead in air monitoring reports", "The list of areas and tasks measured", "Actions taken on the results"]'::jsonb,
   'Lead dust and fumes are absorbed into the body and damage the blood, nerves and kidneys. Monitoring shows whether controls under the Lead Regulations work and who needs medical surveillance. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Botha Battery Recycling in Brakpan has lead in air measured in its breaking area in May 2026 and improves local extraction after the report.',
   '["Monitoring only in the main process area, not in cleaning or maintenance", "Results not shared with the health and safety committee", "Controls not changed after high readings"]'::jsonb,
   'SHE'),
  ('HSF-J-08',
   '["Aggregate summary from the occupational medical practitioner showing trends, not names", "The practitioner''s recommendations for controls", "Individual fitness outcomes only: fit, fit with restrictions or unfit"]'::jsonb,
   'Biological monitoring, such as blood lead, shows whether controls are really protecting people. The clinical records stay with the occupational health practitioner; your File holds only the group summary and each person''s fitness outcome, so you can improve controls without exposing anyone''s medical information.',
   'Example: Botha Battery Recycling in Brakpan files a one page summary from its occupational medical practitioner showing blood lead trends for the breaking team rising, and the extraction upgrade it recommended.',
   '["Individual test results filed in the File", "Summary received but controls not reviewed", "Results reported late, after people are already affected"]'::jsonb,
   'OH'),
  ('HSF-K-01',
   '["Contractor selection criteria covering safety record, competence and insurance", "Completed evaluation form for each contractor", "Letters of good standing and safety documents received"]'::jsonb,
   'You remain responsible for contractors you bring in, so choosing competent ones is your first control. The evaluation, done for each project, shows you checked their safety record and competence before awarding work.',
   'Example: Radebe Call Centre in Midrand evaluates three electrical contractors for its office fit out and chooses Mokoena Electrical because it provided a current letter of good standing and a safety file.',
   '["Contractor chosen on price alone", "Evaluation done after work already started", "Letters of good standing expired"]'::jsonb,
   'PROC'),
  ('HSF-K-02',
   '["Signed section 37(2) agreement with each contractor", "The contractor''s own health and safety File or its index", "Cross reference to the contractor register in Section A"]'::jsonb,
   'The section 37(2) agreement records that the contractor accepts responsibility for health and safety in its own work. Keeping it with the contractor''s File, updated whenever the scope or contractor changes, proves both parties agreed their duties in writing.',
   'Example: Ndlovu Builders in Polokwane signs a section 37(2) agreement with its plumbing subcontractor on 1 February 2026 and files it with the subcontractor''s File index.',
   '["Agreement signed after work started", "Different versions filed in Section A and Section K", "Agreement not renewed when the scope changed"]'::jsonb,
   'PROC'),
  ('HSF-K-03',
   '["Contractor induction records signed by each contractor worker", "Permits issued to contractors", "Daily coordination notes or meeting records"]'::jsonb,
   'Contractors do not know your site''s hazards unless you tell them. Inductions, permits and daily coordination prove every contractor worker was briefed and that work was coordinated so teams did not endanger each other.',
   'Example: Mahlangu Civils holds a ten minute coordination meeting every morning with its three subcontractors in Mamelodi and records the attendees and the day''s high risk tasks.',
   '["Only the contractor''s supervisor inducted, not the workers", "Contractor permits not in your permit register", "Coordination meetings held but never recorded"]'::jsonb,
   'OPS'),
  ('HSF-K-04',
   '["Visitor register with names, dates, times and who they visited", "Visitor safety briefing card or induction record", "Record of personal protective equipment issued to visitors"]'::jsonb,
   'Visitors do not know your hazards or your emergency plan. The register tells you who is on site if you evacuate, and the briefing keeps them safe while they are there.',
   'Example: Mthembu Joinery in Pietermaritzburg has each visitor sign the book at reception, read a short safety card and wear safety glasses in the workshop.',
   '["Visitors not signed out, so the evacuation count is wrong", "Delivery drivers skipped", "Briefing card outdated"]'::jsonb,
   'FAC'),
  ('HSF-K-05',
   '["Photographs or plans of hoarding, barricades and public warning signs", "Proof of public liability insurance", "Inspection records of public protection measures"]'::jsonb,
   'Members of the public can be injured by falling objects, open trenches or moving vehicles near your work. These records, kept for each project, prove you separated the public from the work and have insurance if something goes wrong.',
   'Example: Ndlovu Builders in Polokwane erects hoarding along the pavement for a shop renovation, photographs it weekly and files its public liability insurance certificate.',
   '["Barricades removed and not replaced", "Insurance expired during the project", "No lighting on barricades at night"]'::jsonb,
   'OPS'),
  ('HSF-L-01',
   '["Health and safety committee minutes, signed", "Action list with owners and due dates", "Attendance register for each meeting"]'::jsonb,
   'The committee is where management and workers discuss health and safety together. Monthly minutes and the action list prove meetings happen and that concerns raised are acted on.',
   'Example: Venter Packaging in Paarl holds its committee meeting on the first Tuesday of each month; the October minutes close the slitter guard action and open one on forklift speed.',
   '["Meetings held but no minutes kept", "Actions carried forward month after month without progress", "Representatives not invited or not attending"]'::jsonb,
   'SHE'),
  ('HSF-L-02',
   '["Inspection reports by the health and safety representatives", "Recommendations made to management", "Management''s written response to each recommendation"]'::jsonb,
   'Health and safety representatives inspect the workplace and raise concerns on behalf of workers. Their monthly reports and your written responses show you take their recommendations seriously and act on them.',
   'Example: Mabaso Distribution in Pinetown files its representative''s September report recommending a pedestrian walkway in the warehouse and management''s reply approving it with a completion date.',
   '["Recommendations never answered in writing", "Representatives not given time to inspect", "Reports filed without closing the items"]'::jsonb,
   'SHE'),
  ('HSF-L-03',
   '["Toolbox talk register with topic, date and presenter", "Signatures of attendees", "A copy or summary of the talk content"]'::jsonb,
   'Toolbox talks keep hazards front of mind and let workers ask questions. The register proves each talk happened, who attended and what was covered.',
   'Example: Maseko Roofing in East London gives a talk on harness checks every Monday; the register shows eight attendees and the supervisor''s signature.',
   '["Topics repeated without link to recent incidents", "Attendees not signing", "No record of what was actually said"]'::jsonb,
   'OPS'),
  ('HSF-L-04',
   '["A checklist of notices displayed at each site, including the Act, appointments, emergency numbers and the health and safety policy", "A dated photograph of the notice board", "Annual review sign off"]'::jsonb,
   'Workers have a right to see the law and know who is appointed and how to get help. The annual check, with a photograph, proves the right notices are displayed and current.',
   'Example: Khumalo Motors in Soweto photographs its notice board in January 2026 showing the OHS Act, the appointments list, emergency numbers and the signed policy.',
   '["Notices faded or outdated", "Appointment list showing people who have left", "Notices at head office but not at other sites"]'::jsonb,
   'SHE'),
  ('HSF-L-05',
   '["Log of changes notified to Care Net for medical surveillance", "Log of changes notified to your client for construction work", "Copies of the notifications sent"]'::jsonb,
   'When your processes, chemicals, sites or workforce change, your medical surveillance and your client''s safety planning must change too. The log shows each change was notified so the Medical Surveillance Plan, a separate Care Net product signed by the occupational medical practitioner, and the client''s plans stay accurate.',
   'Example: Govender Pool Supplies in Umhlanga emails Care Net on 2 June 2026 that it has started handling a new chlorine compound and files the email in this log.',
   '["Changes made without telling anyone", "Notification made by phone with no written record", "New sites opened without informing the client"]'::jsonb,
   'SHE'),
  ('HSF-M-01',
   '["Annual review of toilets, basins, drinking water, change rooms and eating areas", "A headcount by gender and shift used for the review", "Photographs and a list of improvements made"]'::jsonb,
   'The right number of clean facilities for your workforce is a basic legal duty and a matter of dignity. The annual review compares what you have with the number of people using it and shows what you fixed.',
   'Example: Mokwena Farming in Tzaneen counts 40 seasonal workers in its March 2026 review and adds two portable toilets and a handwash station at the orchard.',
   '["Review not updated when seasonal staff arrive", "Women''s facilities not counted separately", "No drinking water at remote work areas"]'::jsonb,
   'FAC'),
  ('HSF-M-02',
   '["Annual review of lighting, ventilation, temperature and housekeeping", "Reference to the survey results in Section J", "Actions taken and their completion dates"]'::jsonb,
   'The physical environment affects health, comfort and accidents every day. The annual review brings the survey results and housekeeping findings together and shows what you improved.',
   'Example: Radebe Call Centre in Midrand uses its illumination and ventilation surveys in its 2026 review and records new lights and a serviced air conditioner.',
   '["Review done without looking at the survey results", "Housekeeping findings not included", "No actions recorded"]'::jsonb,
   'FAC'),
  ('HSF-M-03',
   '["Environmental management plan or procedure", "Any environmental licences or authorisations you hold", "Annual review record"]'::jsonb,
   'Where environmental law applies to your business, you need to show how you prevent pollution and manage your impact. The documents, reviewed once a year, prove you know your obligations and act on them.',
   'Example: Mhlongo Auto Repairs in Pietermaritzburg keeps a short environmental procedure for oil, fuel and battery storage, reviewed annually.',
   '["Assuming environmental law does not apply without checking", "Licences not renewed", "Procedure not matching what happens on site"]'::jsonb,
   'SHE'),
  ('HSF-M-04',
   '["Waste manifests for each hazardous waste collection", "Safe disposal certificates from the licensed contractor", "A copy of the contractor''s waste licence"]'::jsonb,
   'You remain responsible for your hazardous waste until it is safely disposed of. Each manifest and certificate proves the waste went to a licensed site.',
   'Example: Mhlongo Auto Repairs in Pietermaritzburg files the manifest for used oil collected on 15 August 2026 and the recycler''s disposal certificate received a week later.',
   '["Manifests filed without disposal certificates", "Contractor''s licence not checked", "Waste collected by unlicensed people for cash"]'::jsonb,
   'FAC'),
  ('HSF-M-05',
   '["Your smoking policy", "A plan or photograph showing designated smoking areas", "Annual review record"]'::jsonb,
   'Smoking near flammable materials is a fire risk, and non smokers must be protected from smoke. The policy, reviewed once a year, shows where smoking is allowed and forbidden.',
   'Example: Govender Pool Supplies in Umhlanga designates a smoking area near the car park, well away from its chemical store, and records the policy review in February 2026.',
   '["Smoking area next to a store of flammable materials", "No signs marking no smoking zones", "Policy not reviewed when the site layout changes"]'::jsonb,
   'FAC'),
  ('HSF-N-01',
   '["Internal audit schedule covering every section of your File", "Completed audit reports with findings", "The name and credentials of the auditor"]'::jsonb,
   'An internal audit checks that your File matches what really happens on site and finds gaps before an inspector or client does. If nobody suitable is available, the auditor recruitment button on Section N finds one whose registration and experience fit your industry. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.',
   'Example: Ndlovu Builders in Polokwane schedules two internal audits for 2026; the June audit by a registered practitioner finds three expired certificates and two missing permits.',
   '["Audits done by the person who wrote the documents", "Findings not added to the corrective action log", "Audit schedule not followed"]'::jsonb,
   'SHE'),
  ('HSF-N-02',
   '["External audit reports from clients, principal contractors, certification bodies or the inspector", "Your response to each finding", "Closure evidence"]'::jsonb,
   'External audits show how others see your system, and clients often make payment or further work depend on them. Keeping each report and your response proves you took findings seriously.',
   'Example: Mahlangu Civils files the principal contractor''s audit of its Mamelodi site in September 2026 with its written response and photos showing each finding closed.',
   '["Reports received but not filed", "Findings not responded to in writing", "Inspector''s notices not linked to the corrective action log"]'::jsonb,
   'SHE'),
  ('HSF-N-03',
   '["Signed minutes of the management review", "Inputs reviewed, such as audits, incidents and objectives", "Decisions and actions with owners"]'::jsonb,
   'Management review is when leadership looks at the whole system once a year and decides what to change. The minutes prove the chief executive is involved and that decisions are made and followed through.',
   'Example: Venter Packaging in Paarl holds its review in November 2026; the chief executive, Anna Venter, approves a budget for machine guarding upgrades after reviewing the year''s incidents.',
   '["Review held without looking at audit or incident data", "No decisions recorded", "Chief executive not present"]'::jsonb,
   'EXEC'),
  ('HSF-N-04',
   '["Written health and safety objectives and targets for the year", "Measurements against each target", "Annual review of results"]'::jsonb,
   'Objectives give your health and safety effort direction and measurable results. Reviewed once a year, they show whether things are getting better and where to focus next.',
   'Example: Mabaso Distribution in Pinetown sets targets to close every audit finding within a month and to hold 40 toolbox talks in 2026, and reports progress quarterly.',
   '["Targets that cannot be measured", "Only lagging targets like injury counts", "Results never reviewed"]'::jsonb,
   'EXEC'),
  ('HSF-N-05',
   '["Non conformance and corrective action log", "Closure evidence for each item", "Monthly review sign off"]'::jsonb,
   'This log is where every audit finding, inspection gap and complaint is tracked until fixed. Reviewing it every month keeps actions moving and proves nothing is ignored.',
   'Example: Ndlovu Builders in Polokwane reviews its log monthly; in July 2026 it closes the expired certificate items with copies of the renewed certificates.',
   '["Log not reviewed regularly", "Items closed without evidence", "Duplicate logs for different sources"]'::jsonb,
   'SHE'),
  ('HSF-N-06',
   '["Log of legislation release notes received from Care Net", "The date each release was applied to your File", "A short note of what changed in your File"]'::jsonb,
   'Health and safety law changes over time, and your File must keep up. This log shows each legislation update was received, understood and applied, so your File stays current.',
   'Example: Radebe Call Centre in Midrand logs a release note received on 1 September 2026 and records that its legal register and noise section were updated the following week.',
   '["Release notes received but not applied", "No record of what changed", "Only one person knows about updates"]'::jsonb,
   'SHE'),
  ('HSF-O-01',
   '["Retention schedule listing each record type and how long it is kept", "The source of each retention period", "Annual review record"]'::jsonb,
   'Some records must be kept for many years; medical surveillance records of hazardous exposure are kept for 40 years under Care Net''s retention standard, and the schedule names the source of every period. Reviewed once a year, it makes sure nothing is destroyed too early or kept longer than needed.',
   'Example: Botha Battery Recycling in Brakpan lists incident records, lead monitoring and medical surveillance records in its schedule, each with its retention period and source.',
   '["Records destroyed during an office move", "No retention period for electronic records", "Medical records mixed with general files"]'::jsonb,
   'EXEC'),
  ('HSF-O-02',
   '["List of where each record type is stored, paper or electronic", "Who has access to each record type", "Backup arrangements for electronic records"]'::jsonb,
   'Records are only useful if you can find them and if private information is protected. This list, reviewed once a year, proves records are safe, backed up and only seen by people who need them.',
   'Example: Mthembu Joinery in Pietermaritzburg stores its File in a locked cabinet and on a shared drive with daily backup; only the safety officer and the owner have access.',
   '["No backup of electronic records", "Everyone with access to medical records", "Access not removed when staff leave"]'::jsonb,
   'EXEC'),
  ('HSF-O-03',
   '["Signed operator agreement for personal information between your company and Care Net", "The date of signature and any amendments", "A list of records Care Net holds for you"]'::jsonb,
   'When Care Net holds records about your workers, the operator agreement sets out how the information is protected and used. Having it signed, and updated whenever the service changes, shows you took responsibility for your workers'' personal information.',
   'Example: Govender Pool Supplies in Umhlanga signs the operator agreement with Care Net on 15 January 2026 before any medical surveillance records are shared.',
   '["Records shared before the agreement was signed", "Agreement not updated when services changed", "Agreement signed but not filed"]'::jsonb,
   'EXEC'),
  ('HSF-OV-AGRI-01',
   '["Written procedure for mixing, spraying and storing pesticides", "Pesticide register (product, quantity, date, field, sprayer)", "Current safety data sheets for each product", "Training records of the sprayers"]'::jsonb,
   'Organophosphates and other pesticides can poison workers through the skin and lungs. The Hazardous Chemical Agents Regulations expect you to control this exposure, and your register shows who used what, where and when. Review it every year.',
   'Example: Louw Table Grapes keeps a spray register at its chemical store in De Doorns and a written mixing procedure signed by farm manager Gerrit Louw on 7 August 2026.',
   '["Pesticides decanted into cooldrink bottles", "No record of who sprayed which block", "Sprayers without the right gloves, respirators or wash facilities"]'::jsonb,
   'OPS'),
  ('HSF-OV-AGRI-02',
   '["Cholinesterase surveillance outcome per person who mixes or sprays organophosphate or carbamate pesticides: fit, fit with restrictions or unfit", "Your list of spray workers and the pesticides they use", "The Plan protocol for pesticide exposure, signed by the OMP"]'::jsonb,
   'Some pesticides slow an enzyme in the blood, and surveillance picks up overexposure before a worker becomes seriously ill; the Hazardous Chemical Agents Regulations drive this for exposed farm workers. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Van der Merwe Citrus near Citrusdal files a fit outcome for each of its six sprayers before the spraying season, and moves one to packing when the OMP records a temporary restriction.',
   '["Testing only after someone falls ill instead of before and during the season", "Filing laboratory values instead of the outcome"]'::jsonb,
   'OH'),
  ('HSF-OV-AGRI-03',
   '["Inspection checklist for tractors and implements, including power take off guards", "Defect register and repair records", "Operator authorisation list"]'::jsonb,
   'Unguarded power take off shafts and implements cause entanglement and amputations on farms. Regular guarding inspections prove your machinery is safe before it goes out. Review the inspection programme every year.',
   'Example: Sondela Farming in Bethlehem inspects every tractor and implement at the start of the season; the checklist dated 1 September 2026 shows a missing shaft guard was replaced before ploughing started.',
   '["Guards removed for maintenance and never refitted", "Inspections done but not written down", "Untrained or unauthorised people driving tractors"]'::jsonb,
   'ENG'),
  ('HSF-OV-AGRI-04',
   '["Chainsaw operator competency certificate per operator", "Tree felling or harvesting machine competency records for forestry crews", "Record of the practical assessment and the assessor''s name"]'::jsonb,
   'Chainsaws and harvesting machines cause severe cuts and crush injuries, so only people assessed as competent should operate them in the plantation. Review it once a year and whenever the work or the people change.',
   'Example: Shongwe Forestry Contractors near Sabie files a chainsaw competency certificate and practical assessment for each of its nine fellers.',
   '["Crews trained informally by a colleague with no record", "Operators moved from brush cutting to felling without a new assessment"]'::jsonb,
   'TRAIN'),
  ('HSF-OV-AGRI-05',
   '["Zoonosis risk controls for livestock and game work", "Procedure for handling sick or dead animals", "PPE and hygiene facilities provided", "Record of health education given to workers"]'::jsonb,
   'Diseases passed from animals to people, such as brucellosis, anthrax and Q fever, can seriously harm farm and abattoir workers, and the Hazardous Biological Agents Regulations expect you to assess and control this exposure. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in your File. Review it every year.',
   'Example: Botha Merino Farms has a zoonosis procedure for lambing season that requires gloves and face protection when handling aborted foetuses, signed by owner Hannes Botha on 12 July 2026.',
   '["Handling dead animals without gloves", "No hand washing facilities in the field", "Workers not told the early signs of disease"]'::jsonb,
   'OPS'),
  ('HSF-OV-AGRI-06',
   '["Policy prohibiting children from doing hazardous work", "Age verification records for seasonal and casual workers", "Record of the tasks that are closed to young workers"]'::jsonb,
   'Children must not be exposed to dangerous work such as spraying, operating machinery or heavy lifting. A clear policy and age checks protect children and show a client or inspector that you control who is on your farm. Review it every year.',
   'Example: Mopani Sun Citrus checks the ID of every picker at recruitment and keeps a signed policy dated 15 March 2026 that no person under the legal working age works on its farm, and no young worker handles chemicals or machinery.',
   '["No age check for workers brought by a labour broker", "Children of workers helping in the orchards", "Policy exists but supervisors do not know it"]'::jsonb,
   'HR'),
  ('HSF-OV-AGRI-07',
   '["Seasonal worker induction programme", "Signed induction attendance records for each season", "Induction content in the languages your workers understand"]'::jsonb,
   'Seasonal workers arrive quickly and in large numbers, often unfamiliar with your farm. A proper induction tells them about the hazards, the rules and what to do in an emergency, and the signed record proves it happened. Review it every year before the season starts.',
   'Example: Koue Berg Orchards in Ceres inducted its seasonal pickers in isiXhosa and Afrikaans in the week of 2 February 2026, and each worker signed the attendance register.',
   '["Workers start picking before induction", "Induction only in English", "No record of who attended"]'::jsonb,
   'HR'),
  ('HSF-OV-AGRI-08',
   '["Heat exposure control plan", "Records of water, shade and rest breaks provided", "Weather monitoring and work schedule changes on hot days", "Training on the signs of heat stress"]'::jsonb,
   'Working outdoors in South African summers can lead to heat exhaustion and heat stroke, which can kill. The plan shows you provide water, shade and rest and change the work on hot days. Review it every year before summer.',
   'Example: Gariep Sun Vineyards starts harvesting at dawn during heatwaves, keeps shaded water stations at every block and trained supervisors on 1 December 2025 to spot heat stress.',
   '["Water only at the farmyard, far from the work", "Piece rate pay that discourages breaks", "No plan for new workers who are not used to the heat"]'::jsonb,
   'OPS'),
  ('HSF-OV-AGRI-09',
   '["Remote site emergency response plan", "Communication arrangements (radio, cellphone coverage map)", "First aid kits and first aider positions in the field", "Transport plan to the nearest hospital"]'::jsonb,
   'Farms and forests are often far from help, and delays can turn an injury into a death. This plan shows how you will raise the alarm, give first aid and get an injured person to care. Review it every year.',
   'Example: Bosrand Timber has an emergency plan listing radio channels, the nearest helicopter landing area and the route to the hospital in Knysna, updated on 18 January 2026.',
   '["No way to call for help where there is no signal", "First aider not with the team in the field", "Nobody knows the route to the nearest hospital"]'::jsonb,
   'SHE'),
  ('HSF-OV-CLEAN-01',
   '["Current safety data sheet for every cleaning product at each client site", "Site chemical list matched to the safety data sheets", "Signed site checklist confirming the file is present"]'::jsonb,
   'Cleaners use chemicals at many sites, and if someone is splashed or poisoned the safety data sheet tells first aiders and doctors what to do. The Hazardous Chemical Agents Regulations expect this information to be available where the chemicals are used. Review it every year.',
   'Example: Zungu Office Cleaning keeps a safety data sheet folder in the cleaners'' store at each of its client offices in Sandton, checked by area supervisor Zanele Mthembu on 10 June 2026.',
   '["Safety data sheets only at head office", "New products introduced without a safety data sheet", "Folder present but outdated"]'::jsonb,
   'OPS'),
  ('HSF-OV-CLEAN-02',
   '["Method statement for facade and high level cleaning", "Fall protection plan and equipment inspection records", "Rope access or suspended platform competence records"]'::jsonb,
   'Window and facade cleaning at height is high risk work, and where it counts as construction the Construction Regulations, 2014 apply. The method statement shows the equipment, anchor points and rescue arrangements were planned before anyone went over the edge. Review it every year.',
   'Example: Van Rooyen Window Cleaning keeps a method statement for the glass facade of a client building in Cape Town, approved on 22 April 2026, with rope access certificates for both of its technicians.',
   '["Anchor points on the roof never tested", "No rescue plan for a technician stuck on a rope", "Using ladders where a platform is needed"]'::jsonb,
   'OPS'),
  ('HSF-OV-CLEAN-03',
   '["Confined space entry procedure for tanks and ducts", "Entry permits with gas test results", "Training records of entrants and standby persons"]'::jsonb,
   'Cleaning inside tanks, ducts and sumps can expose workers to toxic fumes or lack of oxygen. A permit and gas test before entry prevent deaths, and they are what a client will check before letting you work. Review the procedure every year.',
   'Example: Chetty Duct Hygiene completes a confined space entry permit for every kitchen extraction duct clean; the permit dated 14 May 2026 at a hotel in Umhlanga records the gas test and the standby person.',
   '["Entering because the space \"looks fine\"", "Using cleaning chemicals that give off fumes inside the space", "Standby person leaving to do other work"]'::jsonb,
   'SHE'),
  ('HSF-OV-CLEAN-04',
   '["Biological agent risk assessment for healthcare and sanitation cleaning", "Procedures for blood spills, sharps and body fluids", "Records of vaccination offers and PPE issue"]'::jsonb,
   'Cleaners in clinics, hospitals and ablution facilities can be exposed to blood, body fluids and sharps, and the Hazardous Biological Agents Regulations expect you to assess and control this risk. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in your File. Review it every year.',
   'Example: Moeng Hygiene Cleaning, which cleans a private clinic in Bloemfontein, has a blood spill procedure and a record that every cleaner was offered hepatitis B vaccination in January 2026.',
   '["No sharps procedure for cleaners", "Using the same mop for clinical and general areas", "Vaccination offers not recorded"]'::jsonb,
   'SHE'),
  ('HSF-OV-CLEAN-05',
   '["Lone worker and night work procedure", "Check in or call back records", "Night work risk assessment and roster", "Transport arrangements for night shift workers"]'::jsonb,
   'Cleaners often work alone or at night, when help is far away and the risk of crime and fatigue is higher. This procedure shows how you keep in touch with them and get them home safely. Review it every year.',
   'Example: Maake Cleaning requires every lone cleaner in its Pretoria office contracts to check in by phone at set times during the shift; supervisor Kabelo Sithole reviews the call log each morning.',
   '["No way to know if a lone worker is hurt", "No safe transport after late shifts", "Night workers not considered in the fatigue assessment"]'::jsonb,
   'OPS'),
  ('HSF-OV-CLEAN-06',
   '["Client site induction record for each cleaner at each site", "Site specific hazard and emergency information sheet", "Register showing which cleaners are cleared for which sites"]'::jsonb,
   'Each client site has its own hazards, alarms and exits. A site induction record proves your cleaner knows them before starting, and clients usually ask for it. Review the register every year and when you add a site.',
   'Example: Shezi Cleaning Services keeps a register showing that cleaner Palesa Ndlovu completed the site induction at a client''s warehouse in Midrand on 3 August 2026.',
   '["Relief cleaners sent to a site without induction", "Inductions not repeated when the client''s rules change", "No record held by your company, only by the client"]'::jsonb,
   'HR'),
  ('HSF-OV-CONSTR-01',
   '["Construction work permit issued for the project", "Copy of the permit application", "Proof that the permit number is displayed on site"]'::jsonb,
   'Larger or higher risk construction projects need a construction work permit before work starts, under the Construction Regulations, 2014. The thresholds are being confirmed by Care Net; your client or practitioner can tell you whether your project needs one. Review it every year and for each new project.',
   'Example: Selepe Builders obtained a construction work permit for a new shopping centre in Vereeniging before breaking ground on 1 April 2026 and displays the permit number at the site gate.',
   '["Starting work while the application is still pending", "Assuming the permit is only the client''s concern", "Permit number not displayed on site"]'::jsonb,
   'EXEC'),
  ('HSF-OV-CONSTR-02',
   '["Designer''s report on the hazards of the design", "Record of the design risk information given to the client and contractor", "Designer''s sign off on changes"]'::jsonb,
   'The Construction Regulations, 2014 place duties on designers to consider safety during building and later maintenance. The designer''s record shows the hazards were thought about before anything was built. Review it every year and when the design changes.',
   'Example: Naicker Structural Engineers gave the client a design risk report for a steel canopy in Durban on 19 February 2026, highlighting safe anchor points for later roof maintenance.',
   '["Designer never asked for design risk information", "Design changes made on site without the designer", "Maintenance hazards ignored"]'::jsonb,
   'ENG'),
  ('HSF-OV-CONSTR-03',
   '["Structures inspection records", "Engineer''s inspection reports for temporary and permanent structures", "Defect register and corrective action close out"]'::jsonb,
   'Collapsing structures kill workers and the public. Inspections by a competent person show that formwork, support work and structures were checked before and during use. Review the inspection programme every year and for each project.',
   'Example: Tshikovhi Concrete keeps weekly structures inspection reports for a parking deck in Centurion, signed by its engineer Rudzani Tshikovhi, with the last report dated 12 September 2026.',
   '["Formwork loaded before inspection", "Inspection reports kept by the engineer only", "Defects noted but not fixed"]'::jsonb,
   'ENG'),
  ('HSF-OV-CONSTR-04',
   '["Register of suspended platforms on site", "Inspection records before use and periodic inspections", "Operator competence records", "Manufacturer''s documentation for each platform"]'::jsonb,
   'Suspended platforms (cradles) used on facades can fall if not installed, inspected and operated correctly. The register and inspections show each platform is safe to use. Review it every year and for each installation.',
   'Example: Kekana Facades keeps a register of the two suspended platforms on a Sandton office block, inspected on 4 June 2026 by its competent inspector before the glazing work started.',
   '["Platforms moved to a new drop without reinspection", "Untrained operators", "No secondary safety line"]'::jsonb,
   'ENG'),
  ('HSF-OV-CONSTR-05',
   '["Flammable liquid and gas storage plan for the site", "Inventory of flammables on site", "Fire extinguisher inspection records at the store", "Signage and no smoking controls"]'::jsonb,
   'Petrol, diesel, thinners and gas stored on construction sites can start fires and explosions. This record shows flammables are stored away from ignition sources, in the right quantities and with fire equipment nearby. Review it every year and for each site.',
   'Example: Karee Road Construction keeps a flammables store at its road project near Kroonstad, with an inventory updated on 8 May 2026 and two inspected extinguishers at the door.',
   '["Fuel kept inside the site office", "No inventory of what is stored", "Smoking near the store"]'::jsonb,
   'OPS'),
  ('HSF-OV-CONSTR-06',
   '["Plan for work on, over or next to water", "Life jackets and rescue equipment inspection records", "Rescue team and training records"]'::jsonb,
   'Work near rivers, dams or the sea carries the risk of drowning. The plan shows you provide life jackets, rescue equipment and a trained rescue team. Review it every year and for each site.',
   'Example: Tugela Bridge Contractors keeps a water safety plan for a bridge repair, with life jackets checked on 20 March 2026 and a rescue boat crewed by trained workers during all work over the river.',
   '["Life jackets available but not worn", "No plan for a sudden rise in water level", "Rescue equipment kept far from the work"]'::jsonb,
   'SHE'),
  ('HSF-OV-CONSTR-07',
   '["Fire precautions plan for the construction site", "Fire equipment inspection records", "Hot work permits and fire watch records", "Emergency evacuation plan and drill records"]'::jsonb,
   'Construction sites have many ignition sources and flammable materials, and escape routes change as the building grows. This plan shows how you prevent fires and get people out safely. Review it every year and for each site.',
   'Example: Lwandle Developments updated its site fire plan for a block of flats in Gqeberha on 14 July 2026 after the stairwells were closed in, and held an evacuation drill the following week.',
   '["Escape routes not updated as the structure changes", "Extinguishers missing or not inspected", "No fire watch after hot work"]'::jsonb,
   'SHE'),
  ('HSF-OV-CONSTR-08',
   '["Signed handover record of the health and safety file to the client", "Index of the handed over file", "As built drawings and maintenance hazard information"]'::jsonb,
   'When the project ends, the Construction Regulations, 2014 expect the health and safety file to be handed to the client so that future maintenance and alterations can be done safely. The signed handover proves you completed this duty. Review the process every year and on each project close out.',
   'Example: Ridgeback Building Contractors handed over the health and safety file for a school hall in Mahikeng on 29 August 2026, with a handover letter signed by the client''s representative.',
   '["File put together in a rush at the end, with missing records", "No signed handover record", "Maintenance hazard information left out"]'::jsonb,
   'OPS'),
  ('HSF-OV-CONSTR-09',
   '["Construction medical certificate of fitness for every person on the site, your own workers and contractors'' workers", "Site access list checked against current certificates", "Contractor confirmations that their workers'' certificates are current"]'::jsonb,
   'On a construction project the Construction Regulations, 2014 expect every person on site to be certified fit for the work they do, and the principal contractor is expected to check this for the whole site. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Ntuli Construction, principal contractor on a school extension in Mthatha, checks every name on its daily site register against a current certificate of fitness, including its two subcontractors'' teams.',
   '["Checking your own workers but not subcontractors", "Day labourers starting before they are assessed"]'::jsonb,
   'OH'),
  ('HSF-OV-EDU-01',
   '["Chemical register for laboratories and workshops", "Safety data sheets for every chemical held", "Laboratory and workshop rules signed by staff", "Storage and disposal records"]'::jsonb,
   'School and college laboratories and workshops hold chemicals that can burn, poison or explode. The Hazardous Chemical Agents Regulations expect you to control exposure for staff, and learners need the same protection. Review it every year.',
   'Example: The fictitious Hillview Technical College keeps a chemical register for its science laboratory, updated on 30 January 2026 by laboratory head Priya Naidoo, with expired chemicals removed by a registered waste contractor.',
   '["Old chemicals left in storerooms for years", "No safety data sheets", "Learners handling chemicals without supervision or eye protection"]'::jsonb,
   'FAC'),
  ('HSF-OV-EDU-02',
   '["Playground and sports equipment inspection checklist", "Defect and repair records", "List of equipment taken out of use"]'::jsonb,
   'Broken swings, loose goalposts and worn climbing frames injure learners. Regular inspections show you check equipment and remove anything unsafe. Review the inspection programme every year.',
   'Example: The fictitious Sunflower Primary School inspects its playground every term; the checklist dated 13 April 2026 shows a cracked slide was closed off and replaced.',
   '["Goalposts not anchored", "Inspections done but not written down", "Damaged equipment left in use"]'::jsonb,
   'FAC'),
  ('HSF-OV-EDU-03',
   '["Driver list with licence and professional driving permit copies and expiry dates", "Vehicle roadworthy and maintenance records", "Learner transport route and passenger lists"]'::jsonb,
   'Learners depend on safe vehicles and qualified drivers, and holding each driver''s professional driving permit and vehicle records shows you check who drives and what they drive. The permit medical stays with the practitioner who did it; only the fitness outcome goes in your File. Review it every year.',
   'Example: The fictitious Lesedi Light Academy keeps a transport file with its two bus drivers'' professional driving permits, both valid and in date, and service records for each bus dated March 2026.',
   '["Permits expired without anyone noticing", "Relief drivers without a permit", "No passenger list per trip"]'::jsonb,
   'OPS'),
  ('HSF-OV-EDU-04',
   '["Biological agent risk assessment for the early childhood setting", "Nappy changing, hand washing and cleaning procedures", "Record of immunisation information offered to staff", "Illness exclusion policy"]'::jsonb,
   'Young children spread infections easily and staff are exposed through nappies, body fluids and close contact, so the Hazardous Biological Agents Regulations expect this exposure to be assessed and controlled. Clinical and immunisation records stay with the occupational health practitioner; only the outcome goes in your File. Review it every year.',
   'Example: The fictitious Little Acorns Day Care in Polokwane assessed its biological risks on 10 February 2026 and keeps nappy changing and cleaning procedures on the wall of each room.',
   '["No gloves at the changing station", "Staff immunisation records kept in the File instead of with the practitioner", "No exclusion policy for sick children"]'::jsonb,
   'SHE'),
  ('HSF-OV-EDU-05',
   '["Emergency plan that accounts for every learner", "Class registers used at assembly points", "Evacuation drill records with times and problems found", "Plan for learners with disabilities"]'::jsonb,
   'In an emergency you must know that every learner is out safely. The plan and drill records show how teachers account for learners and help those who need assistance. Review it every year.',
   'Example: The fictitious Riverside High School held an evacuation drill on 6 May 2026, and every class teacher checked the register at the assembly point within the time set in the plan.',
   '["No plan for learners in toilets or away from class", "Drills held without a record", "No named helper for learners with disabilities"]'::jsonb,
   'SHE'),
  ('HSF-OV-EDU-06',
   '["Reference to the school''s child protection policy", "Name of the designated child protection person", "Record that staff were told how to report concerns"]'::jsonb,
   'Child protection is handled under its own policies and authorities; your File only points to it so the two systems connect. Care Net does not assess or decide child protection matters. Review the reference every year.',
   'Example: The fictitious Mountain View Primary''s File refers to its child protection policy of January 2026 and names deputy principal Thandeka Mabaso as the designated child protection person.',
   '["Placing confidential child protection case details in the File", "No named contact person", "Staff unaware of how to report"]'::jsonb,
   'HR'),
  ('HSF-OV-GOV-01',
   '["Confined space procedure for water and wastewater works", "Entry permits with gas test results", "Standby and rescue arrangements", "Training records of entrants"]'::jsonb,
   'Sewers, pump stations and reservoirs can contain toxic gases such as hydrogen sulphide, and many deaths happen when colleagues rush in to help. Permits, gas tests and rescue plans prevent this. Review the procedure every year.',
   'Example: Tlou Water Services requires a gas test and entry permit for every manhole entry; the permit dated 19 August 2026 at a pump station in Makhanda lists the standby person and the rescue tripod.',
   '["Gas meter not calibrated", "No rescue equipment at the manhole", "Entering to clear blockages without a permit"]'::jsonb,
   'OPS'),
  ('HSF-OV-GOV-02',
   '["Fitness outcome per firefighter, traffic officer or emergency responder, against the inherent requirements of the job", "The written inherent job requirements the assessment was made against", "Restriction and placement record for anyone not fully fit"]'::jsonb,
   'Emergency and traffic services work is physically demanding and affects public safety, so fitness is assessed against the real demands of the job, and testing must be justified by those demands. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Lindiwe Valley Municipality, a fictitious council, files fitness outcomes for its 30 firefighters, assessed against its written firefighter job requirements.',
   '["Testing without written inherent job requirements to justify it", "Restrictions not reflected in shift allocation"]'::jsonb,
   'OH'),
  ('HSF-OV-GOV-03',
   '["Fleet register with every vehicle, its roadworthiness and service dates", "Authorised driver list with licence and permit expiry dates", "Vehicle inspection checklists and accident records"]'::jsonb,
   'Road crashes are a leading cause of death at work for departments that run fleets. The register shows each vehicle is safe and each driver is authorised. Review it every year.',
   'Example: The fictitious Mountainview District Roads Unit keeps a fleet register of all its vehicles, updated on 1 July 2026, with licence and permit expiry dates for every driver.',
   '["Vehicles used with lapsed service or licence discs", "Drivers not checked for valid licences", "Accidents not linked back to driver or vehicle records"]'::jsonb,
   'OPS'),
  ('HSF-OV-GOV-04',
   '["Fire and evacuation plan for each public facility", "Fire equipment inspection records", "Evacuation drill records", "Occupancy and escape route drawings"]'::jsonb,
   'Public facilities such as clinics, libraries and halls hold many members of the public who do not know the building. A tested evacuation plan helps get everyone out safely. Review it every year.',
   'Example: The fictitious Riverbend Civic Library held an evacuation drill on 11 March 2026 with visitors present, and updated its escape route drawings after a new wing opened.',
   '["Escape doors locked during opening hours", "No plan for visitors with disabilities", "Drills never held while the public is present"]'::jsonb,
   'FAC'),
  ('HSF-OV-GOV-05',
   '["Organogram of health and safety appointments across departments", "Signed section 16(2) assignments for each department head", "Accounting officer''s signed acceptance of overall responsibility"]'::jsonb,
   'In government the head of the organisation, often the accounting officer, carries the chief executive''s responsibility under the OHS Act, and duties are usually assigned to department heads under section 16(2). A clear structure shows who is responsible for what in each department. Review it every year and when people change.',
   'Example: The fictitious Imbali Valley District Municipality keeps an appointment organogram signed by the municipal manager on 1 February 2026, with section 16(2) assignments for each of its five directors.',
   '["Assignments not updated when a director leaves", "Gaps where no one is assigned for a department", "Assignee not given the authority or budget to act"]'::jsonb,
   'EXEC'),
  ('HSF-OV-GOV-06',
   '["Section 37(2) written agreements with each contractor", "Contractor health and safety file review checklist", "Procurement specification with health and safety requirements"]'::jsonb,
   'A written agreement under section 37(2) of the OHS Act records that the contractor accepts its own health and safety duties, and it can limit your liability for the contractor''s acts. Without it, you may carry the contractor''s failures as your own. Review your contracts every year.',
   'Example: The fictitious Blue Hills Public Works office signs a section 37(2) agreement with every maintenance contractor; the agreement with Selati Electrical is dated 14 January 2026.',
   '["Contracts signed without a section 37(2) agreement", "Agreement signed but the contractor''s file never reviewed", "No health and safety requirements in the tender"]'::jsonb,
   'PROC'),
  ('HSF-OV-HEALTH-01',
   '["Written immunisation and post exposure protocol signed by the OMP", "Record per worker that immunisation was offered, with the date; acceptance, refusal and vaccination status stay with the occupational health practitioner", "Post exposure incident log, such as needle stick injuries, showing the date and that it was reported, with follow up kept by the practitioner"]'::jsonb,
   'Healthcare and laboratory staff can catch infections from patients and samples, and the Hazardous Biological Agents Regulations expect you to protect them, including a plan for what happens straight after an exposure. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Kekana Family Clinic in Tzaneen files its post exposure protocol, a log showing a nurse''s needle stick injury was reported the same day, and each worker''s immunisation offer record.',
   '["No protocol for after hours exposures", "Vaccination records with clinical details kept in the File"]'::jsonb,
   'OH'),
  ('HSF-OV-HEALTH-02',
   '["Sharps and healthcare risk waste procedure", "Waste manifests or collection certificates from the licensed waste contractor", "Needlestick injury register showing the date, the place and that each injury was reported, with follow up records kept by the occupational health practitioner", "Container supply and placement records"]'::jsonb,
   'Needlestick injuries can transmit HIV and hepatitis, and poorly handled healthcare waste harms staff, waste workers and the public; this record shows waste is separated, contained and removed safely. Clinical follow up records stay with the occupational health practitioner; only the fitness outcome (fit, fit with restrictions or unfit) goes in your File. Review it every year.',
   'Example: The fictitious Ikhaya Care Clinic in Soweto keeps monthly collection certificates from its healthcare waste contractor and a needlestick register, with the last incident reported on 9 July 2026 and the follow up left to its practitioner.',
   '["Sharps containers overfilled", "No collection certificates to prove proper disposal", "Needlestick injuries not reported"]'::jsonb,
   'FAC'),
  ('HSF-OV-HEALTH-03',
   '["Radiation protection officer appointment letter", "Radiation licence for each source or unit", "Personal dose monitoring summaries per worker", "Radiation area signage and rules"]'::jsonb,
   'Ionising radiation from X ray and similar equipment can cause cancer and other harm, so a radiation protection officer and dose records show exposure is monitored and kept as low as possible. Dose records are sensitive: keep the detail with the radiation protection officer and the practitioner and put only summaries in your File. Review it every year.',
   'Example: Pillai Imaging Centre in Port Shepstone appointed radiographer Nadia Khan as its radiation protection officer on 1 March 2026 and files quarterly dose summaries for its staff.',
   '["Dose badges not worn or not returned", "Licence lapsed when equipment was replaced", "No appointed radiation protection officer"]'::jsonb,
   'OH'),
  ('HSF-OV-HEALTH-04',
   '["Risk assessment for cytotoxic drugs and anaesthetic gases", "Handling and spill procedures", "Ventilation and scavenging system test records", "Training records of staff who handle these agents"]'::jsonb,
   'Cytotoxic drugs and waste anaesthetic gases can harm staff who prepare or are exposed to them, including pregnant workers. The Hazardous Chemical Agents Regulations expect you to assess and control this exposure. Review it every year.',
   'Example: Masakhane Private Hospital, a fictitious hospital in Pietermaritzburg, keeps a cytotoxic handling procedure and scavenging system test reports for its theatres dated 20 April 2026.',
   '["No spill kit where cytotoxic drugs are prepared", "Scavenging systems never tested", "Pregnant staff not told about the risk"]'::jsonb,
   'SHE'),
  ('HSF-OV-HEALTH-05',
   '["Patient handling risk assessment", "Hoist and transfer equipment inspection records", "Patient handling training records"]'::jsonb,
   'Lifting and moving patients is one of the biggest causes of back injury among nurses and carers. The assessment and equipment records show you provide hoists, training and enough staff for safe transfers. Review it every year.',
   'Example: Du Toit Frail Care in George assessed patient transfers on 5 May 2026, bought two ceiling hoists and trained all carers in their use.',
   '["Hoists available but not used because slings are missing", "Carers lifting patients alone", "Training given once and never refreshed"]'::jsonb,
   'SHE'),
  ('HSF-OV-HEALTH-06',
   '["Workplace violence risk assessment", "Incident reporting procedure and register for aggression and assault", "Controls such as panic buttons and security escorts", "Debriefing and support records"]'::jsonb,
   'Healthcare staff face abuse and assault from patients and visitors, which causes injury and long term stress. This record shows you identify where violence happens and put protection and support in place. Review it every year.',
   'Example: Sunrise Community Health Centre, a fictitious facility, installed panic buttons in its emergency unit after an assessment on 2 February 2026 and offers debriefing after every reported assault.',
   '["Staff told that abuse is \"part of the job\"", "Incidents not reported or recorded", "No support after an assault"]'::jsonb,
   'HR'),
  ('HSF-OV-HEALTH-07',
   '["Laboratory biosafety risk assessment", "Biosafety cabinet certification records", "Laboratory procedures for handling and disposing of specimens", "Training records of laboratory staff"]'::jsonb,
   'Laboratories that handle infectious specimens must match their controls to the danger of the agents, and the Hazardous Biological Agents Regulations expect this to be assessed and controlled. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in your File. Review it every year.',
   'Example: Olivier Pathology Laboratory in Upington keeps biosafety cabinet certificates dated 16 March 2026 and a signed specimen handling procedure for all staff.',
   '["Biosafety cabinets not certified", "Specimens opened on an open bench", "No spill procedure"]'::jsonb,
   'SHE'),
  ('HSF-OV-HEALTH-08',
   '["Register of clinical staff with their professional registration body and expiry date", "Reference to your process for checking registrations", "Name of the person who keeps the register"]'::jsonb,
   'Clinical staff must be registered with their professional council, and this register shows you check that. Your File only refers to this process; Care Net does not verify or decide professional registration matters. Review it every year.',
   'Example: Nhlapo Wellness Clinic keeps a register of its nurses and doctors with their registration expiry dates, checked by practice manager Liesl Fourie on 1 April 2026.',
   '["Registrations lapsed without anyone noticing", "Locum staff not checked", "Register kept but never updated"]'::jsonb,
   'HR'),
  ('HSF-OV-HOSP-01',
   '["Certificate of acceptability for each food premises", "Food safety and hygiene procedures", "Cleaning schedules and pest control records", "Food handler training records"]'::jsonb,
   'Poor food hygiene can make customers and staff seriously ill and can close your business. The food hygiene rules are enforced by your municipality''s environmental health practitioners, who will inspect your records. Review them every year.',
   'Example: Oosthuizen''s Kitchen restaurant in Cradock keeps its certificate of acceptability on the wall, with pest control reports from its contractor and cleaning schedules signed daily, last checked by manager Andile Mkhize on 2 September 2026.',
   '["Certificate not updated after a change of owner or premises", "Cleaning schedules not signed", "Food handlers never trained"]'::jsonb,
   'OPS'),
  ('HSF-OV-HOSP-02',
   '["Food handler fitness outcome per kitchen and service worker", "Illness reporting procedure staff sign on appointment", "Record of staff excluded from food handling while ill, without clinical detail"]'::jsonb,
   'In hospitality one ill food handler can infect many guests, and the municipal environmental health practitioner will ask how you know your food handlers are fit to work. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Mthimkhulu Guest House in Port Alfred files fitness outcomes for its cook and two kitchen assistants and a signed illness reporting procedure for each.',
   '["Seasonal staff starting in the kitchen before assessment", "No record of who was sent home ill"]'::jsonb,
   'OH'),
  ('HSF-OV-HOSP-03',
   '["Gas installation certificate of conformity for kitchen appliances", "Fire suppression system service records for extraction canopies", "Fire extinguisher and fire blanket inspection records"]'::jsonb,
   'Kitchen gas leaks and fat fires can cause explosions and serious burns. Gas installation certificates and fire system records show the installation was done and is maintained by competent people. Review them every year.',
   'Example: Fortuin Seafood in Hermanus keeps a gas certificate of conformity issued on 18 February 2026 and service records for the canopy fire suppression system.',
   '["New gas appliances connected without a certificate", "Canopy filters full of grease", "Extinguishers not suited to fat fires"]'::jsonb,
   'FAC'),
  ('HSF-OV-HOSP-04',
   '["Slips and burns risk assessment for kitchens and service areas", "Floor cleaning schedules and non slip footwear policy", "Burns incident records and first aid arrangements"]'::jsonb,
   'Slips on wet floors and burns from hot oil, water and surfaces are the most common injuries in kitchens. This record shows you control floors, footwear and hot work practices. Review it every year.',
   'Example: Mokgadi''s Grill House in Braamfontein assessed slips and burns on 7 March 2026, introduced non slip matting at the fryers and made non slip shoes part of the uniform.',
   '["Spills left until the end of the shift", "Staff wearing open or smooth soled shoes", "No burns kit near the fryers"]'::jsonb,
   'OPS'),
  ('HSF-OV-HOSP-05',
   '["Pool safety procedure covering opening hours, supervision and depth signage", "Lifeguard or pool attendant roster with their current lifesaving and first aid certificates", "Daily pool water testing and chemical dosing log", "Copy of your municipality''s pool by law requirements, if your municipality sets any"]'::jsonb,
   'A guest pool can drown a child in minutes, and a pool plant room holds strong chemicals. Guests, insurers and the municipality will ask who watches the pool and how the water is kept safe. The rules come mostly from local by laws, so check with your municipality; review this at least once a year.',
   'Example: Mabaso Country Lodge in Clarens keeps its pool rules, a roster showing that Sipho Radebe is on duty from 09:00 to 18:00, his lifesaving certificate and the daily chlorine log in one folder.',
   '["No record of who was supervising the pool on a given day", "Lifesaving certificates that have lapsed", "Pool chemicals stored next to the guest area"]'::jsonb,
   'FAC'),
  ('HSF-OV-HOSP-06',
   '["List of every cleaning and laundry chemical your housekeepers use, with its safety data sheet", "Housekeeping chemical risk assessment and safe handling procedure", "Training record showing housekeepers were taught dilution, mixing dangers and first aid for splashes", "Photos or inspection notes of the chemical store and dispensing points"]'::jsonb,
   'Housekeepers handle bleach, degreasers and oven cleaners every day, often in small unventilated rooms. Mixing the wrong products can release toxic gas, and splashes cause eye and skin burns. This record shows you manage these substances as the Hazardous Chemical Agents Regulations expect; review it at least once a year.',
   'Example: Jacobs Guest House in Knysna keeps a chemical list of eleven products, each safety data sheet, and a signed record of Nomvula Dube training the six housekeepers on dilution charts in March 2026.',
   '["Safety data sheets missing for products bought from a local supplier", "Chemicals decanted into unlabelled cooldrink bottles", "No eye wash near the dispensing point"]'::jsonb,
   'OPS'),
  ('HSF-OV-MANU-01',
   '["Machine register listing every machine by type, location and guard type", "Guarding inspection checklist for each machine class, signed and dated", "Photos of guards and interlocks in place", "Defect log showing what was found and when it was fixed"]'::jsonb,
   'Unguarded presses, saws, rollers and conveyors cause amputations. An inspector will walk the floor and compare what they see with your register. Grouping machines by class (presses, saws, conveyors, lathes) keeps checks consistent; review the whole set at least once a year and after any change to a machine.',
   'Example: Mokoena Metal Works in Germiston lists its 23 machines in five classes, and its maintenance planner Pieter van Wyk signs a monthly guarding checklist for each class, with photos of the fixed guard on the guillotine.',
   '["Guards removed for maintenance and never refitted", "Interlocks bypassed with cable ties", "New machines not added to the register"]'::jsonb,
   'ENG'),
  ('HSF-OV-MANU-02',
   '["Chemical register for the process: solvents, welding consumables, isocyanate paints and hardeners", "Risk assessment for each process, with the controls (extraction, enclosure, respirators)", "Latest air monitoring report and extraction system test record, where your practitioner requires them", "Respirator fit test and issue records"]'::jsonb,
   'Solvents, welding fume and isocyanates in spray paints can cause lasting lung and nerve damage, and isocyanates can trigger asthma that ends a career. This record shows you know which substances each process uses and how you keep exposure down, as the Hazardous Chemical Agents Regulations expect. Review it at least once a year and whenever a product or process changes.',
   'Example: Zwane Auto Body in Pinetown keeps its spray booth extraction test, the isocyanate risk assessment and fit test records for its three spray painters in one file for its client audits.',
   '["Monitoring done once years ago and never repeated after a process change", "Dust masks used where the risk assessment calls for air fed respirators", "No link between the chemical register and medical surveillance"]'::jsonb,
   'SHE'),
  ('HSF-OV-MANU-03',
   '["Ergonomic risk assessment for each production line or workstation", "Records of changes made, such as adjustable benches, lifting aids or job rotation", "Reports of discomfort at a workstation and what you changed, without medical detail", "Training record on safe lifting and posture"]'::jsonb,
   'Repetitive work, awkward reaching and heavy lifting on a line lead to back, shoulder and wrist injuries that build up slowly and cost you in absence and claims. Showing that you assessed each line and acted on it is what an inspector or client will look for. Review it at least once a year and when a line is redesigned.',
   'Example: Dlamini Packaging in Pietermaritzburg assessed its three packing lines in April 2026, raised two benches, added a vacuum lifter for 25 kg bags and started hourly task rotation.',
   '["Assessing the office but not the factory floor", "No follow through after staff report aches", "One generic assessment used for every line"]'::jsonb,
   'SHE'),
  ('HSF-OV-MANU-04',
   '["Register of vessels, tanks, silos and pits that count as confined spaces", "Confined space entry procedure and permit form", "Completed entry permits with gas test readings", "Rescue plan and training record for entrants, attendants and rescuers"]'::jsonb,
   'Mixing vessels and tanks can hold toxic vapours or too little oxygen, and many deaths are rescuers who went in after a collapsed worker. A signed permit with gas readings proves the space was tested and made safe before entry. Review the register and procedure at least once a year.',
   'Example: Khumalo Chemicals in Sasolburg keeps a register of nine vessels, and every entry into its main reactor has a permit signed by the supervisor with the gas reading taken before entry and a named standby attendant.',
   '["Permits issued without a gas test", "No trained standby person outside", "Rescue plan that relies on calling the fire brigade only"]'::jsonb,
   'OPS'),
  ('HSF-OV-MANU-05',
   '["Forklift operator competency record per operator, naming the machine type used in your plant", "Company authorisation card per operator", "Periodic practical reassessment record"]'::jsonb,
   'In a factory forklifts share space with people on foot, so each operator must be competent on the specific machines and routes in your plant, not only in general. Review it once a year and whenever the work or the people change.',
   'Example: Mathe Plastics in Isando reassesses its eight forklift operators each year on its own reach trucks and loading bay route, and renews their authorisation cards.',
   '["Operators trained on counterbalance forklifts driving reach trucks", "Authorisation cards never withdrawn after a serious incident"]'::jsonb,
   'TRAIN'),
  ('HSF-OV-MANU-06',
   '["Register of dangerous goods held on site, with quantities and storage location", "Safety data sheets and storage layout showing separation of incompatible goods", "Transport documents and driver training records for dangerous goods you dispatch", "Fire and spill equipment inspection records for the store"]'::jsonb,
   'Flammable, corrosive and toxic goods stored or loaded incorrectly cause fires, explosions and spills that reach neighbours and roads. Clients, your insurer and traffic officials will ask for storage and transport documents. Review this at least once a year and whenever you add a new product.',
   'Example: Naidoo Resins in Durban keeps a dangerous goods register, a store plan showing acids kept apart from solvents, and the transport paperwork and driver training record for every load it sends out.',
   '["Incompatible products stored on the same shelf", "Using your own bakkie for dangerous goods without the right documents", "Spill kits empty or missing"]'::jsonb,
   'OPS'),
  ('HSF-OV-MINING-01',
   '["Signed statement of the employer''s health and safety duties under the MHSA regime", "Mine health and safety policy and the organogram showing who holds each responsibility", "Written appointments of managers and supervisors made under the MHSA regime", "Risk assessment summary for the mine"]'::jsonb,
   'On a mine the MHSA regime applies instead of the OHS Act, and the employer''s duties there are wide and personal. This record shows the mine inspector who holds each duty and that the employer understands them. The exact requirements are still being verified in the File library, so ask your practitioner; review at least once a year.',
   'Example: Pretorius Aggregates, a small quarry near Brits, keeps its signed employer duties statement, policy, organogram and the written appointment of its mine manager Johan Botha in this section.',
   '["Using an OHS Act File on a mine or quarry", "Appointments that do not match the current organogram", "No risk assessment behind the policy"]'::jsonb,
   'EXEC'),
  ('HSF-OV-MINING-02',
   '["Mandatory code of practice on fitness to perform work, signed off by the employer", "Record of how the code was drawn up with the health and safety committee", "List of occupations and the fitness requirements set for each", "Certificate of fitness outcomes only (fit, fit with restrictions, unfit), with clinical records kept by the occupational health practitioner"]'::jsonb,
   'Mines must show that every person doing risky work is fit to do it safely. Care Net screens fitness and does not diagnose; the occupational health practitioner keeps the clinical records and only the outcome goes in the File. Follow the Chief Inspector of Mines'' guideline your practitioner works from and review at least once a year.',
   'Example: Pretorius Aggregates keeps its fitness to perform work code, the committee minutes where it was agreed, and a list showing that its haul truck operators hold current certificates of fitness marked fit.',
   '["Filing full medical reports in the File instead of the outcome", "A code copied from another mine that lists occupations you do not have", "No consultation record with the committee"]'::jsonb,
   'OH'),
  ('HSF-OV-MINING-03',
   '["Mandatory code of practice on noise, signed and dated", "Noise survey showing zones and the people exposed", "Hearing protection issue records and hearing conservation training", "Audiometry outcomes from the medical surveillance programme, outcomes only"]'::jsonb,
   'Crushers, drills and haul trucks cause permanent hearing loss. The code sets how the mine measures noise, reduces it and protects and tests the people exposed, and the inspector will check that practice matches the code. Review at least once a year, or as your practitioner sets.',
   'Example: Maseko Sand Mining keeps its noise code, the survey that marked the crusher and screening plant as noise zones, and signed hearing protector issue cards for the eight people who work there.',
   '["Noise survey older than the current plant layout", "Hearing protectors issued without training on fitting them", "Zones not marked with signs on site"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-04',
   '["Mandatory code of practice on airborne pollutants such as dust and silica", "Occupational hygiene sampling reports", "Dust suppression and ventilation controls in place, with maintenance records", "Respirator fit test and issue records"]'::jsonb,
   'Silica and other mine dusts cause silicosis and other lung diseases that show up years later and are compensated under a separate law for mines and works. The code and sampling records prove you measure and control the dust. Review at least once a year, or as your practitioner sets.',
   'Example: Maseko Sand Mining keeps its airborne pollutants code, the hygienist''s sampling report for the screening plant, and water spray maintenance records for the haul road.',
   '["Sampling done only once when the mine opened", "Water sprays broken for weeks without a record", "Dust masks issued without fit testing"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-05',
   '["Mandatory code of practice on thermal stress", "Heat and cold stress assessment for the workings or surface areas", "Heat acclimatisation, water and rest break procedure", "Records of heat related incidents and what was changed"]'::jsonb,
   'Deep or poorly ventilated workings and open pits in summer can cause heat exhaustion and heat stroke, which can kill. The code shows how you measure heat, acclimatise new workers and protect people. Review at least once a year and before the hot season.',
   'Example: Letsoalo Chrome, an example underground operation, keeps its thermal stress code, the ventilation officer''s heat readings and the acclimatisation log for new starters.',
   '["No acclimatisation for workers returning from leave", "Water points not checked", "Assessment done in winter only"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-06',
   '["Mandatory code of practice on fatigue management", "Shift rosters and overtime records", "Fatigue risk assessment for drivers and plant operators", "Records of fatigue related incidents or near misses and what you changed"]'::jsonb,
   'Tired operators of heavy machinery cause serious accidents, especially on night shift and long overtime. The code sets how you plan shifts and spot fatigue, and the rosters prove it works in practice. Review at least once a year and when shift patterns change.',
   'Example: Pretorius Aggregates keeps its fatigue code, the monthly roster and a register where supervisors note any operator stood down for fatigue, such as a night shift loader driver sent home on 14 May 2026.',
   '["A code that does not match the rosters actually worked", "Overtime not tracked for contractors", "No way for workers to report fatigue"]'::jsonb,
   'OPS'),
  ('HSF-OV-MINING-07',
   '["Mandatory code of practice on trackless mobile machinery", "Register of machines with their pre use inspection checklists", "Traffic management plan with road rules, speed limits and pedestrian separation", "Operator licences and training records"]'::jsonb,
   'Collisions between haul trucks, loaders, light vehicles and people on foot are a leading cause of mine deaths. The code and its records prove each machine is checked, each operator is trained and routes are planned. Review at least once a year and when the pit layout changes.',
   'Example: Maseko Sand Mining keeps its code, a traffic plan showing separate light vehicle routes, and daily pre use checklists for its two front end loaders and three tipper trucks.',
   '["Pre use checklists signed without the check being done", "Contractor machines not in the register", "Traffic plan not updated as the pit moves"]'::jsonb,
   'OPS'),
  ('HSF-OV-MINING-08',
   '["Mandatory code of practice on fall of ground", "Geotechnical or rock engineering assessment and inspection reports", "Support standards and making safe procedure", "Records of falls of ground and near misses"]'::jsonb,
   'Falls of rock underground and highwall or slope failures in pits kill and injure. The code sets how ground is assessed, supported and inspected, and the inspection records show it happens at the intervals your mine''s code of practice or your practitioner sets. Review at least once a year and whenever ground conditions change.',
   'Example: Letsoalo Chrome keeps its fall of ground code, the rock engineer''s quarterly report and the shift supervisor''s entry examination book for each working place.',
   '["Inspection books not signed at the intervals your mine''s code of practice or your practitioner sets", "Support standards not updated after a fall of ground", "Surface slopes left out of the code"]'::jsonb,
   'OPS'),
  ('HSF-OV-MINING-09',
   '["Mandatory code of practice on emergency preparedness and response", "Emergency response plan with contact numbers and assembly points", "Drill records with what went wrong and what was fixed", "Agreements with the rescue or emergency services you rely on"]'::jsonb,
   'A mine emergency such as fire, flooding or a fall of ground needs a plan that people know and have practised. The inspector will ask for the plan and the last drill report. Review at least once a year and after every drill or real emergency.',
   'Example: Pretorius Aggregates keeps its emergency code, a plan naming the nearest hospital in Brits, and the report of its June 2026 evacuation drill, which found that one siren was too quiet at the crusher.',
   '["Emergency numbers out of date", "Drills held but no report written", "Contractors not included in drills"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-10',
   '["Your mine''s written certificate of fitness procedure", "Register linking each person to a current certificate of fitness", "Access control rules that stop people without a current certificate"]'::jsonb,
   'Under the MHSA regime a mine runs a system to make sure nobody works without being certified fit, and inspectors look at the system, not just single certificates. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Kgosi Aggregates, a quarry near Brits, files its fitness procedure and a monthly register that its access control office uses to block expired certificates.',
   '["A procedure on paper that access control does not enforce", "Contractors'' certificates tracked outside the system"]'::jsonb,
   'OH'),
  ('HSF-OV-MINING-11',
   '["List of current and former workers who need benefit examinations for occupational lung disease", "Record of examination dates and that each person was referred, with the referral letters kept by the occupational health practitioner", "Proof that results were submitted to the certification body where required", "Outcomes only in the File; the clinical records stay with the occupational health practitioner"]'::jsonb,
   'Mine and works employees exposed to dust are entitled to lung disease examinations and compensation under a separate law for mines and works. Your records show that people were examined and referred so their claims are not lost; Care Net screens fitness and does not diagnose, and the occupational health practitioner keeps the clinical records. Ask your practitioner which examinations apply and review at least once a year.',
   'Example: Maseko Sand Mining keeps a list of its 14 dust exposed workers, the date each was examined in 2026 and the date one worker was referred, with the referral letter and medical details kept by its occupational health practitioner.',
   '["Forgetting former workers and exit examinations", "Filing X ray reports or referral letters in the File", "No proof of submission"]'::jsonb,
   'OH'),
  ('HSF-OV-MINING-12',
   '["Election records for health and safety representatives", "Appointment letters and training records for each representative", "Health and safety committee terms of reference, meeting schedule and minutes", "Inspection reports from representatives and your responses"]'::jsonb,
   'Under the MHSA regime workers take part in safety through elected representatives and committees. The records show the inspector that representatives were properly chosen, trained and listened to. Review at least once a year, or as your practitioner sets.',
   'Example: Letsoalo Chrome keeps the ballot results that elected Lerato Mabena as representative for the shaft, her training certificate, and the committee minutes where her inspection findings were closed out.',
   '["Representatives appointed by management instead of elected", "Minutes without action owners", "Representatives not trained"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-13',
   '["Explosives permits and licences held by the mine or blasting contractor", "Magazine register and stock reconciliation", "Blasting certificates of every person who handles explosives", "Blasting procedure, misfire procedure and blast records"]'::jsonb,
   'Explosives cause catastrophic injuries and are also a security risk if they go missing. Police, the inspector and your insurer will check permits, stock records and who is certified to blast. Review at least once a year and every time the contractor or permit changes.',
   'Example: Pretorius Aggregates uses a blasting contractor, and keeps the contractor''s permits, the certificate of blaster Themba Zulu and a signed blast record for every blast in 2026.',
   '["Stock register not reconciled after each blast", "Contractor certificates not checked", "No written misfire procedure"]'::jsonb,
   'OPS'),
  ('HSF-OV-MINING-14',
   '["Register of winders, hoists, cranes and lifting equipment", "Inspection and test certificates by a competent person", "Operator checks at the intervals your mine''s code of practice or your practitioner sets", "Maintenance and defect records"]'::jsonb,
   'Failure of a winder, hoist or lifting device can kill many people at once. The certificates and checks prove each machine has been tested by someone competent and is checked at the intervals your mine''s code of practice or your practitioner sets. Review at least once a year and use the inspection intervals your practitioner or engineer sets.',
   'Example: Letsoalo Chrome keeps its winder register, the engineer''s test certificate for the man winder and the banksman''s checklist in the engineering office.',
   '["Certificates held by the contractor only", "Slings and chains not in the register", "No defect follow up record"]'::jsonb,
   'ENG'),
  ('HSF-OV-MINING-15',
   '["Ventilation plan and survey results", "Gas and air quality measurement records", "Self rescuer issue and training records", "Mine rescue arrangements or agreement with a rescue service"]'::jsonb,
   'Poor ventilation lets gas, heat and dust build up, and if something goes wrong underground people must be able to escape or be rescued. The records show the air is measured and that people know how to use their self rescuers. Review at least once a year and whenever the workings change.',
   'Example: Letsoalo Chrome keeps its ventilation plan, the weekly gas readings, the self rescuer issue register and its agreement with an example regional rescue service.',
   '["Self rescuers issued but not checked", "Ventilation plan not updated as workings advance", "No rescue agreement for a small operation"]'::jsonb,
   'SHE'),
  ('HSF-OV-MINING-16',
   '["Register of accidents, dangerous occurrences and occupational diseases reported to the mine inspectorate", "Copies of each report and the inspectorate''s acknowledgement", "Investigation reports and actions taken", "Inspectorate instructions or notices and your responses"]'::jsonb,
   'The mine inspectorate must be told about serious accidents and certain occurrences, and it can stop work if it is not. Keeping each report and acknowledgement proves you told them on time and followed up. Ask your practitioner exactly what must be reported and when; review at least once a year.',
   'Example: Maseko Sand Mining keeps a reporting register listing a conveyor injury in February 2026, the report sent to the inspectorate, the acknowledgement and the closed investigation.',
   '["Reporting to the Department of Employment and Labour instead of the mine inspectorate", "No acknowledgement kept", "Instructions from the inspector not closed out"]'::jsonb,
   'SHE'),
  ('HSF-OV-OFFICE-01',
   '["Workstation assessment for each person who works at a screen", "Record of changes made, such as chairs, screen height or keyboards", "Short training record on setting up a workstation", "Home working checklist where staff work remotely"]'::jsonb,
   'Long hours at a screen with a poor chair or badly placed monitor lead to neck, back, wrist and eye strain. A simple assessment and fix list shows you took reasonable steps, which clients and inspectors expect. Review at least once a year and when someone moves desk or starts working from home.',
   'Example: Molefe and Partners Attorneys in Rosebank completed workstation assessments for its 18 staff, bought four footrests and two laptop stands, and repeats the checklist each March.',
   '["Assessing only new staff", "Forgetting people who work from home", "Complaints not recorded"]'::jsonb,
   'SHE'),
  ('HSF-OV-OFFICE-02',
   '["Night shift roster and records of health assessments offered to night workers", "Headset and acoustic exposure assessment for call agents", "Headset issue, hygiene and replacement records", "Procedure for reporting acoustic shock or hearing complaints"]'::jsonb,
   'Contact centre agents working at night face fatigue and health effects, and headsets can expose them to loud sudden sounds. This record shows you plan night work with your people''s health in mind and check what headsets deliver. Follow your practitioner''s advice on assessments and review at least once a year.',
   'Example: Govender Contact Solutions, a contact centre in Umhlanga, keeps its night roster, a record that all 40 night agents were offered a health assessment, and the headset supplier''s sound limiting specification.',
   '["No health assessment offered to night workers", "Shared headsets without hygiene covers", "Hearing complaints not logged"]'::jsonb,
   'HR'),
  ('HSF-OV-OFFICE-03',
   '["Lone working and travel procedure", "Check in log or tracking arrangement for staff working alone or travelling", "Travel risk assessment for regular routes or destinations", "Emergency contact list and incident reports"]'::jsonb,
   'Staff who visit clients alone, work late or drive long distances are at risk of crime, accidents and medical emergencies with no one to help. A check in routine and travel plan show you know where your people are and can respond. Review at least once a year.',
   'Example: Ndlovu Property Valuers in Polokwane requires valuers to send a WhatsApp check in to the office manager after each site visit, and keeps the log with its lone working procedure.',
   '["Procedure exists but no one monitors the check ins", "Sales executives travelling after dark without a plan", "No emergency contact on file"]'::jsonb,
   'HR'),
  ('HSF-OV-OFFICE-04',
   '["Psychosocial risk assessment covering workload, harassment, violence and trauma", "Policy on harassment and bullying, with the reporting channel", "Record of support offered, such as an employee wellness programme", "Staff survey results or complaint summaries, with personal details removed"]'::jsonb,
   'Stress, bullying and trauma harm health as surely as physical hazards and drive absence and staff turnover. Showing that you assessed these risks and offer support is increasingly what clients and inspectors ask about. Review at least once a year.',
   'Example: Van der Merwe Accounting in Bloemfontein ran an anonymous staff survey in May 2026, found deadline pressure in tax season, and added temporary staff and a wellness helpline.',
   '["Treating stress as a private matter only", "No safe way to report a manager", "Keeping named survey answers in the File"]'::jsonb,
   'HR'),
  ('HSF-OV-PETRO-01',
   '["Written assessment of whether your site holds hazardous substances above the major hazard threshold, signed by your practitioner", "Where it is a major hazard installation: the risk assessment by the approved inspection authority or competent person the governing regulations require, and the notifications made", "On site emergency plan and proof it was shared with the local emergency services", "Record of information given to neighbours and the public, where required"]'::jsonb,
   'A major hazard installation can cause a fire, explosion or toxic release that affects people well beyond your fence. Whether the full set of rules applies depends on what you store and in what quantity, so the first document you need is the threshold assessment. Do not guess the thresholds; ask your practitioner and review at least once a year.',
   'Example: Kotze Fuels depot in Beaufort West keeps its practitioner''s letter confirming that its bulk diesel storage falls within the major hazard rules, the risk assessment and the emergency plan shared with the municipal fire service.',
   '["Assuming a small depot is exempt without checking", "Risk assessment not updated after adding tanks", "Emergency plan never shared with the fire service"]'::jsonb,
   'SHE'),
  ('HSF-OV-PETRO-02',
   '["Hazardous area classification drawing showing the zones", "Register of electrical equipment in each zone with its explosion protection rating", "Certificate of compliance for the electrical installation", "Inspection records by a competent electrical person"]'::jsonb,
   'Ordinary electrical equipment can spark and ignite fuel vapour. The zone drawing shows where only intrinsically safe or explosion protected equipment may be used, and the register proves what is installed there. Review at least once a year and whenever equipment is added or replaced.',
   'Example: Mabuza Motors fuel station in Mthatha keeps its zone drawing for the pump islands and tank fills, and a register showing each pump and light fitting in the zone with its protection rating.',
   '["Ordinary cell phones and extension leads used in zones", "Replacement lights not checked for rating", "Zone drawing missing after renovations"]'::jsonb,
   'ENG'),
  ('HSF-OV-PETRO-03',
   '["Transport documents for each dangerous goods load", "Driver training records and professional driving permits", "Vehicle inspection records and emergency equipment checks", "Contracts with transporters stating who is responsible for the load"]'::jsonb,
   'Fuel tankers and dangerous goods vehicles in a crash can cause fires and spills on public roads. Traffic officials and clients will ask for the documents, driver training and vehicle checks. Review at least once a year and when you change transporters.',
   'Example: Kotze Fuels keeps a transport document for every delivery, the dangerous goods training certificate of driver Andile Mthembu and the weekly check of the tanker''s fire extinguishers.',
   '["Using a transporter without checking their driver training", "Emergency information missing from the cab", "No record of who owns the load in transit"]'::jsonb,
   'OPS'),
  ('HSF-OV-PETRO-04',
   '["Emergency plan for the forecourt and tank farm", "Fire equipment inspection and service records", "Drill reports for fire, spill and robbery scenarios", "Contact list and agreement with the local fire service"]'::jsonb,
   'A fuel spill or fire on a forecourt puts customers, staff and passers by at risk. Staff need to know how to use the emergency stop, fight a small fire and evacuate. Review the plan at least once a year and after every drill.',
   'Example: Mabuza Motors keeps its forecourt emergency plan, the extinguisher service record and the report of an April 2026 drill where attendants practised the emergency stop.',
   '["Attendants not shown where the emergency stop is", "Extinguishers past their service date", "No drill on night shift"]'::jsonb,
   'SHE'),
  ('HSF-OV-PETRO-05',
   '["Earthing and bonding test records for tanks, pumps and loading points", "Procedure for bonding tankers during delivery", "Inspection checklist for earthing cables and clamps", "Training records for staff who receive deliveries"]'::jsonb,
   'Static electricity can spark and ignite fuel vapour when fuel flows. Earthing and bonding records prove the electrical path to ground is tested and used on every delivery. Review at least once a year and use the test interval your electrical practitioner sets.',
   'Example: Kotze Fuels keeps the electrician''s earthing test report for its loading bay and a delivery checklist where the receiving attendant ticks that the bonding clamp was attached.',
   '["Damaged clamps left in use", "No test record after electrical work", "Delivery checklist not used on weekends"]'::jsonb,
   'ENG'),
  ('HSF-OV-PETRO-06',
   '["Spill response procedure and spill kit inspection records", "Records of spills and how they were cleaned up and reported", "Tank and pipeline leak testing or monitoring results", "Any environmental authorisation or permit you hold for the site"]'::jsonb,
   'Fuel and chemical spills pollute soil and groundwater and can lead to cleanup orders and claims. Your records show that you can contain a spill quickly and that you watch for leaks. Environmental permits vary by site, so check with your practitioner; review at least once a year.',
   'Example: Mabuza Motors keeps its spill procedure, the monthly spill kit check and the record of a 20 litre diesel spill on 3 August 2026, contained with absorbent and disposed of through a registered waste company.',
   '["Spill kits used and not restocked", "Small spills not recorded", "Wet stock readings not checked for leaks"]'::jsonb,
   'SHE'),
  ('HSF-OV-RETAIL-01',
   '["Racking layout plan showing bays and safe load signs", "Racking inspection reports by a competent person, and routine checks by your own staff", "Damage register showing damage found and repairs done", "Supplier''s load ratings for the racking"]'::jsonb,
   'Overloaded or damaged racking can collapse and crush staff or customers. Inspection reports and a damage register prove you check it and act before it fails. Review at least once a year and use the inspection intervals your practitioner or racking supplier sets.',
   'Example: Mahlaba Wholesalers in Mbombela keeps a racking plan with load signs, a weekly check signed by the warehouse supervisor and the inspector''s report that red tagged two damaged uprights in June 2026.',
   '["Load signs missing", "Damaged uprights left in use", "Racking moved without the supplier''s approval"]'::jsonb,
   'OPS'),
  ('HSF-OV-RETAIL-02',
   '["Loading dock traffic plan showing vehicle routes, pedestrian walkways and reversing areas", "Dock rules for drivers and staff", "Records of dock equipment checks such as dock levellers and wheel chocks", "Incident and near miss records at the dock"]'::jsonb,
   'Reversing trucks, forklifts and people on foot in the same space cause crush injuries. A clear plan and rules separate people from vehicles. Review at least once a year and whenever the dock layout or deliveries change.',
   'Example: Mahlaba Wholesalers painted a pedestrian walkway at its receiving dock, keeps its dock rules signed by delivery drivers and logs daily wheel chock checks.',
   '["Visiting drivers never told the rules", "No banksman for reversing", "Walkways blocked by pallets"]'::jsonb,
   'OPS'),
  ('HSF-OV-RETAIL-03',
   '["Assessment of cold room, freezer and hot area exposure", "Cold room procedures: maximum time inside, protective clothing, door release checks", "Issue records for thermal clothing", "Checks that the inside door release and alarm work"]'::jsonb,
   'Staff working in freezers or hot bakeries and storerooms can suffer cold or heat illness, and people have been trapped in cold rooms. The procedure and door checks show you protect them. Use the exposure limits your practitioner sets and review at least once a year.',
   'Example: Moloi Supermarket in Kimberley keeps its cold room procedure, a weekly test of the inside door release and a register of freezer jackets issued to six staff.',
   '["Inside release not tested", "No thermal clothing for relief staff", "Heat in the bakery never assessed"]'::jsonb,
   'OPS'),
  ('HSF-OV-RETAIL-04',
   '["Security risk assessment for the store, cash office and after hours work", "Cash handling and robbery procedure", "Training records on how to act during and after a robbery", "Incident reports and support offered to staff afterwards"]'::jsonb,
   'Retail staff face armed robbery, which causes physical and lasting psychological harm. A procedure that tells staff not to resist, limits cash on hand and provides support afterwards shows you have taken reasonable steps. Review at least once a year and after every incident.',
   'Example: Moloi Supermarket trained its 12 cashiers on its robbery procedure in February 2026 and arranged counselling for two staff after an attempted robbery in July.',
   '["No trauma support after an incident", "Too much cash left in tills", "New staff not trained"]'::jsonb,
   'FAC'),
  ('HSF-OV-RETAIL-05',
   '["Evacuation plan and floor plan showing exits and assembly points", "Fire equipment inspection and service records", "Fire marshal appointments and training", "Evacuation drill reports that include moving customers out"]'::jsonb,
   'A fire in a shop full of customers who do not know the building can cause panic and deaths. Clear exits, trained marshals and practised drills protect both staff and the public. Your municipality''s fire department may have its own requirements, so check with them; review at least once a year.',
   'Example: Mahlaba Wholesalers held a drill during trading hours in May 2026, cleared the store in four minutes, and moved stock that was blocking an emergency exit.',
   '["Emergency exits locked or blocked by stock", "Marshals who have left the company", "Drills only held after hours"]'::jsonb,
   'FAC'),
  ('HSF-OV-SEC-01',
   '["PSIRA registration certificate per officer showing the grade", "Your company''s PSIRA registration as a security service provider", "Post list showing the grade each post requires and who fills it"]'::jsonb,
   'Security work falls under the PSIRA regime, and clients check that every officer is registered and graded for the post, so an officer placed on the wrong post puts the contract and the public at risk. Review it once a year and whenever the work or the people change.',
   'Example: Letsoalo Protection Services in Mokopane matches each of its 25 officers to a post list and moves an officer whose grade is below what the client contract asks for off the supervisor post.',
   '["Grade on the certificate lower than the post requires", "Officers whose registration lapsed while still on duty"]'::jsonb,
   'HR'),
  ('HSF-OV-SEC-02',
   '["Firearm competency certificate per armed officer for each firearm type carried", "Licence for each company firearm and the safe register", "Firearm issue and return register per shift"]'::jsonb,
   'Armed security work carries a risk to officers and the public, and firearms law expects competency for each firearm type and strict control of who holds which firearm. Review it once a year and whenever the work or the people change.',
   'Example: Mabunda Cash Services in Giyani checks each armed officer''s competency against the firearm issued and reconciles the safe register at every shift change.',
   '["Issuing a shotgun to an officer only certified for handguns", "Firearms leaving the safe with no signature"]'::jsonb,
   'FAC'),
  ('HSF-OV-SEC-03',
   '["Cash in transit vehicle specifications and inspection records", "Route planning and variation procedure", "Crew firearm licences, competency certificates and security officer registration under the PSIRA regime", "Incident and attack reports with lessons learnt"]'::jsonb,
   'Cash in transit crews are targets of violent attacks. Vehicle checks, varied routes and competent crews reduce the risk and are what clients and insurers ask to see. Review at least once a year and after every incident.',
   'Example: Sibiya Cash Services in Ekurhuleni keeps daily vehicle inspection sheets, a route plan that changes weekly and the competency records of its crews.',
   '["Routes that never change", "Vehicle defects not repaired before use", "Firearm competencies that have lapsed"]'::jsonb,
   'OPS'),
  ('HSF-OV-SEC-04',
   '["Post incident support procedure", "Record of debriefs and counselling offered after incidents, without personal clinical details", "Agreement with a counselling or employee wellness provider", "Return to work plan template"]'::jsonb,
   'Security officers who face violence, shootings or death on duty can develop lasting trauma. Offering support quickly helps them recover and return to work, and shows you care for their health. Review at least once a year.',
   'Example: Ngcobo Security in Richards Bay keeps a log showing that officer Bongani Cele was offered counselling within 24 hours of an armed robbery at the site he guarded.',
   '["Waiting for the officer to ask for help", "Keeping counselling notes in the File", "No return to work plan"]'::jsonb,
   'HR'),
  ('HSF-OV-SEC-05',
   '["Canine handler training records", "Dog health, vaccination and fitness records from the veterinarian", "Kennel hygiene and bite incident procedure", "Records of bite incidents and actions taken"]'::jsonb,
   'Working dogs can bite handlers, colleagues and the public, and kennels carry disease risks. Training and health records show the dogs are managed safely. Review at least once a year.',
   'Example: Ngcobo Security keeps handler Mandla Khoza''s training certificate, the vet record for his dog Shaka and a bite incident log with no entries for 2026.',
   '["Dogs handled by untrained guards", "Vaccinations out of date", "Kennels not cleaned on a schedule"]'::jsonb,
   'OPS'),
  ('HSF-OV-SEC-06',
   '["Ergonomic assessment of control room workstations and screens", "Shift and break schedule for controllers", "Lighting and noise checks in the control room", "Record of changes made after complaints"]'::jsonb,
   'Controllers watch many screens for long hours, often at night, which causes eye strain, fatigue and musculoskeletal problems. The assessment and break schedule show you designed the work with their health in mind. Review at least once a year and when the control room changes.',
   'Example: Sibiya Cash Services assessed its control room in March 2026, installed adjustable monitor arms and set a ten minute screen break every two hours.',
   '["No breaks planned for single controller shifts", "Chairs not suitable for 24 hour use", "Glare from windows not fixed"]'::jsonb,
   'SHE'),
  ('HSF-OV-SEC-07',
   '["Lone posting procedure with check in times", "Panic button or radio test records", "Emergency response plan for posts that are alone or remote", "Records of missed check ins and what was done"]'::jsonb,
   'An officer alone at a post who is attacked or falls ill may not be able to call for help. Regular check ins and tested panic buttons make sure someone notices quickly. Review at least once a year.',
   'Example: Ngcobo Security requires hourly radio check ins from officers on lone posts, and its control room log shows a supervisor was sent when an officer missed a check in on 9 June 2026.',
   '["Missed check ins not followed up", "Panic buttons never tested", "No plan for posts without cell signal"]'::jsonb,
   'OPS'),
  ('HSF-OV-TEL-01',
   '["Tower rescue plan for each type of structure", "Rescue kit inspection records", "Rescue training records for every climbing team", "Rescue drill reports"]'::jsonb,
   'If a climber is injured or collapses on a tower, suspension in a harness can become fatal quickly, and emergency services may take too long to arrive. The plan and drill records prove the team on site can bring a person down. Review at least once a year and follow the Construction Regulations, 2014 where towers are built.',
   'Example: Nkosi Tower Services in Mbombela keeps a rescue plan for monopoles and lattice towers, the monthly rescue kit inspection and a drill report from April 2026 where the team lowered a dummy in under ten minutes.',
   '["Relying on the fire brigade for rescue", "Rescue kit not on site", "Climbers never practise a rescue"]'::jsonb,
   'SHE'),
  ('HSF-OV-TEL-02',
   '["Radio frequency exposure assessment for each site or antenna type", "Procedure for switching off or reducing power before climbing near antennas", "Signage and exclusion zone records", "Training records for climbers on radio frequency hazards"]'::jsonb,
   'Standing close to transmitting antennas can heat body tissue. Knowing the exclusion zones and making sure power is reduced before work protects climbers. The detailed rules are still being verified in the File library, so use the limits your practitioner sets; review at least once a year.',
   'Example: Nkosi Tower Services keeps a power down request form signed by the network operator before every antenna job, and photos of the exclusion zone signs at each site.',
   '["Climbing without confirming power down", "Signs missing on rooftop sites", "Contractors not trained"]'::jsonb,
   'SHE'),
  ('HSF-OV-TEL-03',
   '["Register of manholes, cable chambers and plant rooms that count as confined spaces", "Entry permit and gas test records", "Rescue arrangements for each entry", "Training records for entrants and standby persons"]'::jsonb,
   'Manholes and cable chambers can fill with toxic gas or lack oxygen, and data centre plant rooms can hold fire suppression gas. Permits with gas readings prove each entry was made safe. Review at least once a year.',
   'Example: Adams Fibre Networks in Cape Town issues a permit for every manhole entry, and the permit for chamber CH14 shows the gas test reading and the name of the standby person.',
   '["No gas detector on the team", "Standby person going in to help", "Suppression gas risk ignored in plant rooms"]'::jsonb,
   'OPS'),
  ('HSF-OV-TEL-04',
   '["Emergency response plan for remote sites, with nearest medical facilities", "First aid kit and first aider records for field teams", "Communication plan where there is no cell signal", "Travel and check in records"]'::jsonb,
   'Remote tower sites can be hours from help. A plan that names the nearest clinic, trained first aiders and a way to call for help reduces the time to treatment. Review at least once a year.',
   'Example: Nkosi Tower Services keeps a site card for each rural tower listing the nearest clinic and helicopter landing area, and every field team carries a satellite messenger.',
   '["Nearest clinic not identified", "No first aider in the team", "Check ins not monitored"]'::jsonb,
   'SHE'),
  ('HSF-OV-TRANS-01',
   '["Fleet register with each vehicle''s licence, roadworthy status and operator card", "Driver licence and professional driving permit copies with expiry dates", "Vehicle inspection and maintenance records", "Traffic fines and accident records per driver"]'::jsonb,
   'Unroadworthy vehicles and unlicensed drivers cause crashes on public roads and put your business at legal risk. Traffic officials, clients and insurers will check your fleet documents. Review at least once a year and track every expiry date.',
   'Example: Mthembu Logistics in Pietermaritzburg keeps a fleet register for its nine trucks showing each operator card and roadworthy date, with copies of every driver''s professional driving permit.',
   '["Driving permits that expired without anyone noticing", "Operator cards missing for trailers", "Maintenance done but not recorded"]'::jsonb,
   'OPS'),
  ('HSF-OV-TRANS-02',
   '["List of dangerous goods you carry and their classes", "Transport documents and emergency information for each load", "Dangerous goods driver training records", "Vehicle placarding and emergency equipment checks"]'::jsonb,
   'Carrying dangerous goods without proper documents, placards and trained drivers endangers other road users and emergency responders. Clients and traffic officials will ask for these records. Review at least once a year and when you carry a new product.',
   'Example: Mthembu Logistics keeps a folder for each dangerous goods load with the transport document, and a register of the four drivers trained to carry them.',
   '["Placards missing or wrong", "Untrained relief drivers", "Emergency information not in the cab"]'::jsonb,
   'OPS'),
  ('HSF-OV-TRANS-03',
   '["Driver hours and rest records", "Fatigue management procedure", "Tracking or logbook data showing driving time", "Records of fatigue incidents and actions"]'::jsonb,
   'Tired drivers cause serious crashes. Records of hours and rest breaks show you plan trips so drivers can rest. Follow your employment agreements and practitioner''s advice on hours; review at least once a year.',
   'Example: Mthembu Logistics uses tracking data to check that drivers on the Durban to Johannesburg route take a rest stop at Harrismith, and its supervisor reviews the report weekly.',
   '["Overtime not recorded", "No overnight stop planned on long routes", "Drivers paid per trip, which pushes them to skip rest"]'::jsonb,
   'OPS'),
  ('HSF-OV-TRANS-04',
   '["Rail safety critical fitness outcome per train driver, shunter or other safety critical worker", "List of safety critical roles and who fills them", "Restriction and removal from duty record where a person is not fit"]'::jsonb,
   'A rail worker who is not fit for a safety critical task can cause a derailment or collision, and the rail safety regulator expects operators to manage their fitness. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Mosia Rail Logistics in De Aar files a fit outcome for each of its locomotive drivers and shunters and removes one from duty until a restriction is reviewed.',
   '["Safety critical roles not listed, so people in them are missed", "Returning a worker to duty before the OMP reviews a restriction"]'::jsonb,
   'OH'),
  ('HSF-OV-TRANS-05',
   '["Summary of the port rules and permits that apply to your work", "Port access permits and inductions for your workers", "Risk assessments for quayside and cargo handling", "Agreements with the port authority or terminal operator on safety responsibilities"]'::jsonb,
   'Work in ports falls under separate maritime and port rules as well as general safety law, and terminal operators set their own conditions. Keeping the permits and agreements shows you know which rules apply. Ask your practitioner which regime governs your work; review at least once a year.',
   'Example: Reddy Stevedoring in Richards Bay keeps port access permits for its 30 workers, the terminal operator''s induction record and its quayside lashing risk assessment.',
   '["Assuming only the OHS Act applies in a port", "Expired port permits", "No agreement on who manages quayside traffic"]'::jsonb,
   'EXEC'),
  ('HSF-OV-TRANS-06',
   '["Summary of the aviation rules and airport requirements that apply to your ground handling work", "Airside permits and driver authorisations", "Risk assessments for apron work, aircraft towing and baggage handling", "Airport operator safety inductions and audit reports"]'::jsonb,
   'Airside work mixes aircraft, vehicles, jet blast and noise, and falls under aviation rules as well as general safety law. Airports will not let your staff airside without the right permits and training. Ask your practitioner which rules apply; review at least once a year.',
   'Example: Petersen Ground Handling at an example regional airport keeps airside permits for its 25 staff and the airport''s last safety audit report with all findings closed.',
   '["Airside driving permits expired", "No hearing protection plan for apron staff", "Findings from the airport audit left open"]'::jsonb,
   'OPS'),
  ('HSF-OV-TRANS-07',
   '["Load securing procedure for your types of cargo", "Inspection records for straps, chains and securing equipment", "Driver training records on load securing", "Records of shifted or lost loads and what was changed"]'::jsonb,
   'A load that shifts or falls can overturn a truck or kill other road users. The procedure and equipment checks show loads leave your yard secured. Review at least once a year and when you carry a new type of cargo.',
   'Example: Mthembu Logistics keeps a load securing checklist that the dispatcher signs for every truck, and replaced six frayed straps after its July 2026 inspection.',
   '["Damaged straps still in use", "No check before the truck leaves", "Overloading not checked"]'::jsonb,
   'OPS'),
  ('HSF-OV-UTIL-01',
   '["Register of electrical installations and equipment you generate or distribute with", "Appointment of the competent electrical person responsible", "Inspection, test and maintenance records for substations and lines", "Certificates of compliance for installations"]'::jsonb,
   'Generation and distribution equipment operates at voltages that kill instantly, and the register, appointments and inspection records prove each installation is controlled by competent people. If you have no competent person for this appointment, the recruitment button in Section B connects you with Care Net''s Recruitment Portal, or with a sales executive until the portal address is live. Review at least once a year.',
   'Example: Mashaba Solar Farm near Tzaneen keeps its installation register, the appointment letter of its responsible engineer and the annual inspection report for its main substation.',
   '["Contractor work not tested before energising", "No appointment for the responsible person", "Records held only by a former contractor"]'::jsonb,
   'ENG'),
  ('HSF-OV-UTIL-02',
   '["Switching and isolation procedure", "List of people authorised to switch and isolate", "Completed switching instructions and permits to work", "Lockout and tagging equipment records"]'::jsonb,
   'Most electrical deaths happen when equipment someone believed was dead was still live. Written switching instructions, authorised people and lockout prove the equipment was isolated and proven dead before work. Review at least once a year and whenever the network changes.',
   'Example: Mashaba Solar Farm keeps a list of three authorised switching operators and a signed permit to work for every job on its inverter stations, each showing the lockout points.',
   '["Unauthorised people switching", "Locks shared or not personal", "No test before touch"]'::jsonb,
   'ENG'),
  ('HSF-OV-UTIL-03',
   '["Risk assessment for chlorine and dosing chemicals", "Safety data sheets and storage and handling procedures", "Leak detection and alarm test records", "Emergency response plan and breathing apparatus inspection records"]'::jsonb,
   'A chlorine leak can kill workers and harm the public nearby. Your assessment, alarm tests and emergency plan show you control this chemical as the Hazardous Chemical Agents Regulations expect. Review at least once a year and after any leak.',
   'Example: Hadebe Water Services keeps its chlorine risk assessment, the monthly alarm test and records showing its operators practised putting on breathing apparatus in March 2026.',
   '["Alarms never tested", "Breathing apparatus not serviced", "Neighbours not included in the emergency plan"]'::jsonb,
   'SHE'),
  ('HSF-OV-UTIL-04',
   '["Arc flash risk assessment and labels for switchgear", "Arc rated protective clothing issue and inspection records", "Safe working distances and procedures for live work", "Training records for electrical staff"]'::jsonb,
   'An arc flash can cause severe burns, blindness and hearing loss in a fraction of a second. The assessment and labels tell workers the danger at each panel and what protection to wear. Use the values your electrical practitioner sets and review at least once a year.',
   'Example: Mashaba Solar Farm labelled every switchboard with its arc flash category after its assessment and keeps issue records for arc rated suits for its four electricians.',
   '["No labels on panels", "Ordinary overalls used instead of arc rated clothing", "Assessment not updated after changes"]'::jsonb,
   'ENG'),
  ('HSF-OV-UTIL-05',
   '["Register of assets the public can reach, such as substations, reservoirs and pipelines", "Fencing, signage and security inspection records", "Records of trespass, vandalism and cable theft and how you responded", "Public awareness or community notices"]'::jsonb,
   'Under the OHS Act you must also protect people who are not your employees, such as children climbing into substations or people stealing cable. Inspection records and incident follow up show you keep the public away from danger. Review at least once a year.',
   'Example: Hadebe Water Services inspects the fences around its three reservoirs monthly and repaired a cut fence within two days in August 2026, with photos in the File.',
   '["Damaged fences left for weeks", "No danger signs in local languages", "Incidents reported to police but not recorded"]'::jsonb,
   'FAC'),
  ('HSF-OV-UTIL-06',
   '["List of environmental authorisations, licences and permits for your sites", "Copy of each authorisation with its conditions", "Records showing how you meet the conditions", "Correspondence with the environmental authorities"]'::jsonb,
   'Utilities often need environmental authorisations to build and operate, and each comes with conditions. Keeping them with proof you follow the conditions avoids fines and shutdowns. Which authorisations apply depends on your activities, so check with your practitioner; review at least once a year.',
   'Example: Mashaba Solar Farm keeps its environmental authorisation, the list of conditions and the environmental control officer''s monthly reports during construction.',
   '["Authorisations held by the developer, not the operator", "Conditions never tracked", "Expired permits"]'::jsonb,
   'EXEC'),
  ('HSF-OV-WASTE-01',
   '["Waste management licence or registration for each facility or activity that needs one", "Waste manifests or safe disposal certificates for each load", "Training record for staff who complete manifests and handle hazardous waste"]'::jsonb,
   'Environmental waste law controls how waste is stored, moved and disposed of, and a missing manifest can leave you responsible for waste dumped by someone else. Staff who fill in manifests must know how. Review it once a year and whenever the work or the people change.',
   'Example: Ngcobo Waste Solutions in Hammarsdale files its waste licence, a manifest for each hazardous load collected, and the disposal site''s safe disposal certificate that closes it off.',
   '["Manifests started but never closed with a disposal certificate", "Licence conditions not read by the people doing the work"]'::jsonb,
   'OPS'),
  ('HSF-OV-WASTE-02',
   '["Waste classification and handling procedure for hazardous and healthcare risk waste", "Waste manifests or tracking documents for every collection", "Disposal certificates from the treatment or disposal site", "Training and protective equipment records for waste handlers"]'::jsonb,
   'Hazardous and healthcare risk waste can injure, infect or poison handlers and the public. Manifests and disposal certificates prove the waste went where it should, and training records show handlers know the risks. Review at least once a year.',
   'Example: Shabalala Waste in Pretoria keeps a manifest for every collection from its clinic clients and the matching disposal certificate from the treatment plant.',
   '["Missing disposal certificates", "Handlers without gloves or puncture resistant clothing", "Waste mixed with general waste"]'::jsonb,
   'OPS'),
  ('HSF-OV-WASTE-03',
   '["Record per worker exposed to biological agents that immunisation was offered, with the date; acceptance, refusal and vaccination status stay with the occupational health practitioner", "Your biological agent risk assessment showing who is exposed", "Post exposure procedure for needle stick and sewage contact"]'::jsonb,
   'Waste and sewage workers can be exposed to blood, needles and sewage, and the Hazardous Biological Agents Regulations expect you to protect them, including offering immunisation the practitioner recommends. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File. Review it once a year and whenever the work or the people change.',
   'Example: Sithebe Waste Management in Hammarsdale files a dated immunisation offer record for each collection worker and its procedure for a needle found in a bag.',
   '["Keeping vaccination cards or refusal forms in the File instead of with the practitioner", "No procedure for sharps found in general waste"]'::jsonb,
   'OH'),
  ('HSF-OV-WASTE-04',
   '["Landfill gas monitoring records", "Register of confined spaces such as leachate sumps and gas wells", "Entry permits with gas test readings", "Rescue plan and training records"]'::jsonb,
   'Landfills produce methane and other gases that can explode or suffocate workers in pits, sumps and buildings. Gas monitoring and entry permits prove you test before people go in. Review at least once a year.',
   'Example: Modise Landfill Services monitors gas at its site office and sumps weekly, and every sump entry has a permit showing the gas reading and the standby person.',
   '["Offices built on the landfill not monitored", "No gas detector for sump work", "Rescue plan not practised"]'::jsonb,
   'SHE'),
  ('HSF-OV-WASTE-05',
   '["Traffic management plan for the site with routes and pedestrian areas", "Reversing procedure with banksman or camera requirements", "Vehicle reversing alarm and camera checks", "Incident and near miss records"]'::jsonb,
   'Waste trucks reverse often, and workers on foot on landfills and at kerbside collection are regularly run over. A plan, trained banksmen and working alarms keep people out of the danger zone. Review at least once a year and when the site layout changes.',
   'Example: Shabalala Waste fitted reversing cameras to its eight compactor trucks, and its daily check sheet records that each alarm and camera works before the truck leaves.',
   '["Workers riding on the back of trucks", "Faulty alarms not reported", "No banksman at the tipping face"]'::jsonb,
   'OPS'),
  ('HSF-OV-WASTE-06',
   '["Sharps handling procedure", "Needle stick injury reporting and post exposure procedure", "Puncture resistant glove issue records", "Register of needle stick injuries showing the date and that each was reported, with follow up and clinical details kept by the occupational health practitioner"]'::jsonb,
   'Hidden needles in waste can transmit blood borne diseases. Your procedure and register show staff know how to avoid injuries and what to do immediately afterwards, as the Hazardous Biological Agents Regulations expect. Clinical follow up stays with the occupational health practitioner, and only the outcome goes in the File; review at least once a year.',
   'Example: Shabalala Waste recorded a needle stick injury to a sorter in April 2026, sent her to the clinic within an hour under its procedure, and then switched to thicker gloves.',
   '["Injuries not reported", "No quick access to post exposure care", "Clinical details kept in the File"]'::jsonb,
   'OH'),
  ('HSF-OV-WASTE-07',
   '["Dust risk assessment for the transfer station", "Dust monitoring or occupational hygiene reports where your practitioner requires them", "Dust suppression system maintenance records", "Respirator issue and fit test records"]'::jsonb,
   'Tipping and compacting waste, rubble and soil raises dust that may contain silica, which damages lungs over time. Monitoring and suppression records show you know how much dust there is and keep it down, as the Hazardous Chemical Agents Regulations expect. Review at least once a year.',
   'Example: Modise Landfill Services keeps the hygienist''s dust report for its transfer station and a daily log showing the water spray system was running.',
   '["Spray systems off during water restrictions without another control", "Respirators not fit tested", "No monitoring after the site started taking rubble"]'::jsonb,
   'SHE'),
  ('HSF-OV-WASTE-08',
   '["Environmental monitoring plan required by your licence", "Groundwater, surface water and air monitoring results", "Reports submitted to the authorities", "Corrective actions taken when results are high"]'::jsonb,
   'Waste sites can pollute water and air around them, and licences usually require regular monitoring. Keeping results and actions shows you meet the conditions and protect neighbours. The monitoring required depends on your licence, so check its conditions; review at least once a year.',
   'Example: Modise Landfill Services keeps its quarterly borehole results and the report sent to the authorities, including the extra leachate control it added after one high reading.',
   '["Monitoring results never reviewed", "Reports not submitted", "No action on high readings"]'::jsonb,
   'SHE');

insert into hsf_appointment_guidance (appointment_code, what_to_submit, why, example, common_gaps) values
  ('APP-00',
   '["Signed appointment letter stating the scope, sites and period under section 16(2)", "Appointee''s signed acceptance", "Proof that the assignee has the authority and resources to act (job title, reporting line)", "Health and safety training or qualification record"]'::jsonb,
   'The section 16(2) assignee is given specific health and safety duties to carry out day to day and is the default owner of the File, while the chief executive stays responsible. A signed letter with a clear scope and the assignee''s written acceptance is good practice that makes the assignment easy to defend. The competence the law requires is still being confirmed in the library, so keep whatever training or experience supports the appointment.',
   'Example: Ntuli Plant Hire''s managing director assigns workshop manager Zodwa Ntuli under section 16(2) for both of its depots, and the File holds her dated acceptance and her health and safety management certificate.',
   '["Assigning a junior person with no authority", "Leaving out which sites the assignment covers", "No acceptance signature"]'::jsonb),
  ('APP-01',
   '["Signed appointment letter stating the scope, sites and period for the named project", "Appointee''s signed acceptance", "CV and qualifications showing construction management experience", "Registration certificate with the relevant professional body, if held"]'::jsonb,
   'The construction manager is responsible for managing the construction work and its health and safety on the project. Clients and inspectors check this appointment early because many other appointments report to it.',
   'Example: Mthembu Builders appoints Johan van Wyk as construction manager for a clinic extension in Mbombela, with his signed acceptance and his building qualification on file.',
   '["Using one letter for several unrelated projects", "No evidence of construction management experience"]'::jsonb),
  ('APP-02',
   '["Signed appointment letter stating the scope, sites and period, and naming the construction manager it supports", "Appointee''s signed acceptance", "Qualifications or experience record"]'::jsonb,
   'On larger or multi site projects an assistant construction manager helps the construction manager control the work. The appointment makes clear which part of the work the assistant covers.',
   'Example: Mthembu Builders appoints Precious Maseko as assistant construction manager for the second phase of its Mbombela project, reporting to the construction manager.',
   '["Not stating which work or site the assistant is responsible for"]'::jsonb),
  ('APP-03',
   '["Signed appointment letter stating the scope, sites and period for the named project", "Appointee''s signed acceptance", "Current SACPCMP registration in the construction health and safety officer category, where the Construction Regulations, 2014 or your client require it", "CV showing construction health and safety experience"]'::jsonb,
   'The construction health and safety officer advises and monitors health and safety on site. Clients normally check that the officer is registered and competent before site establishment. If you do not have one, the recruitment button on this appointment connects you with Care Net''s Recruitment Portal, or with a sales executive until the portal address is live.',
   'Example: Zulu Developments'' principal contractor files the appointment of Nomsa Khoza as construction health and safety officer with a copy of her current SACPCMP registration card.',
   '["Registration that has expired during the project", "One officer spread across too many sites to be effective"]'::jsonb),
  ('APP-04',
   '["Signed appointment letter stating the scope, sites and period, and naming the work or area supervised", "Appointee''s signed acceptance", "Training or experience record for the type of work supervised", "Certificate of fitness outcome, if the risk assessment requires one"]'::jsonb,
   'Construction supervisors control the work at the face and make sure it is done safely. Naming them in writing shows who was in charge of a task if something goes wrong. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Radebe Construction appoints Sizwe Radebe as supervisor for the concrete works on a Soweto housing project.',
   '["Supervisors appointed for work they have never done", "No appointment for a foreman who is supervising in practice"]'::jsonb),
  ('APP-05',
   '["Signed appointment letter stating the scope, sites and period, including which assessments the person may do", "Appointee''s signed acceptance", "Risk assessment training certificate", "Examples of risk assessments the person has completed"]'::jsonb,
   'The risk assessor identifies hazards and works out controls, and almost every other section of the File depends on that work. Competence matters: a weak risk assessment leads to the wrong training, medicals and controls.',
   'Example: Fourie Manufacturing appoints its production supervisor, Karabo Letsoalo, as risk assessor after a risk assessment course, and files the baseline risk assessment she led.',
   '["Appointing someone with no risk assessment training", "Not involving workers in the assessments"]'::jsonb),
  ('APP-06',
   '["Signed appointment letter stating the scope, sites and period for the site or project", "Appointee''s signed acceptance", "Fall protection planning training certificate", "The fall protection plan the person prepared"]'::jsonb,
   'The fall protection planner writes the plan that prevents people falling when working at height. Falls are a leading cause of serious injury, so clients and inspectors check this appointment whenever height work is done.',
   'Example: Pretorius Roofing appoints Thabo Mokoena as fall protection planner and files the plan he wrote for a factory roof replacement in Vereeniging.',
   '["A generic plan that does not match the actual roof or structure", "Training certificate that has expired"]'::jsonb),
  ('APP-07',
   '["Signed appointment letter stating the scope, sites and period for the site", "Appointee''s signed acceptance", "Scaffold supervisor training certificate", "Scaffold erection records the person has signed"]'::jsonb,
   'The scaffold supervisor controls the erection, alteration and dismantling of scaffolds so they are built safely. A collapsing or badly built scaffold can injure people on it and below it.',
   'Example: Mahlaba Scaffolding appoints Lucky Mahlaba to supervise scaffold erection at a shopping centre refurbishment in Boksburg.',
   '["Scaffolds erected without a supervisor present"]'::jsonb),
  ('APP-08',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Scaffold inspector training certificate", "Latest scaffold inspection register pages"]'::jsonb,
   'The scaffold inspector checks scaffolds before use and at the intervals your risk assessment or the practitioner sets, and after bad weather or changes. The inspection register shows whether the scaffold was safe to use on a given day.',
   'Example: Mahlaba Scaffolding''s inspector, Ayanda Cele, tags each scaffold after inspection and records it in the register kept in the site office.',
   '["Inspections not recorded", "Scaffold tags not updated after an alteration"]'::jsonb),
  ('APP-09',
   '["Signed appointment letter stating the scope, sites and period for the site", "Appointee''s signed acceptance", "Training or experience record in excavation work", "Excavation inspection records the person signed"]'::jsonb,
   'The excavation supervisor makes sure trenches and excavations are shored, inspected and kept safe. Collapse can bury workers in seconds.',
   'Example: Mkhize Pipelines appoints Bongani Mkhize as excavation supervisor for a sewer line in Pietermaritzburg and files his daily inspection sheets.',
   '["No inspection record for the day of an incident", "Supervisor also operating the excavator and not watching the trench"]'::jsonb),
  ('APP-10',
   '["Signed appointment letter stating the scope, sites and period for the demolition project", "Appointee''s signed acceptance", "Demolition training or experience record", "Demolition method statement the person approved"]'::jsonb,
   'The demolition supervisor controls demolition work so structures come down in a planned, safe order and nobody is caught by unexpected collapse or hidden hazards such as asbestos.',
   'Example: Coetzee Demolitions appoints Riaan Coetzee to supervise the demolition of an old warehouse in Gqeberha, with the approved method statement on file.',
   '["No survey for hazardous materials before demolition starts"]'::jsonb),
  ('APP-11',
   '["Signed appointment letter stating the scope, sites and period, and naming the temporary works covered", "Appointee''s signed acceptance", "Engineering qualification and professional registration evidence", "Design drawings and calculations signed by the designer"]'::jsonb,
   'Temporary works such as formwork and propping must be designed by a competent person so they carry the load safely until the permanent structure can. The appointment shows who is accountable for the design.',
   'Example: Mthembu Builders appoints an engineer from Maseko Consulting Engineers as temporary works designer for the slab formwork on its Mbombela project.',
   '["Formwork built from a supplier catalogue with no project specific design"]'::jsonb),
  ('APP-12',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Training or experience record in temporary works", "Signed inspection before loading, such as before a concrete pour"]'::jsonb,
   'The temporary works supervisor makes sure temporary works are built to the design and inspected before they are loaded. Many collapses happen during the pour.',
   'Example: Mthembu Builders'' temporary works supervisor signs the formwork inspection before every slab pour.',
   '["No signed inspection before the pour"]'::jsonb),
  ('APP-13',
   '["Signed appointment letter stating the scope, sites and period, and naming the machines the operator may use", "Appointee''s signed acceptance", "Operator training certificate for each type of machine", "Certificate of fitness outcome from the occupational health practitioner"]'::jsonb,
   'Only trained, medically fit operators should drive construction vehicles and mobile plant, because a single mistake can crush someone. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Mkhize Pipelines appoints Themba Zwane to operate its tractor loader backhoe, with his operator certificate and a certificate of fitness on file.',
   '["Operator trained on one machine but driving another", "Certificate of fitness expired or never done"]'::jsonb),
  ('APP-14',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Training or experience record in mobile plant", "Daily or pre use check records the person reviews"]'::jsonb,
   'The mobile plant supervisor controls where machines work, checks that pre use inspections are done and keeps people and machines apart on site.',
   'Example: Mkhize Pipelines appoints its plant foreman to supervise all earthmoving machines and review the operators'' pre use check sheets each morning.',
   '["No traffic plan separating pedestrians and machines"]'::jsonb),
  ('APP-15',
   '["Signed appointment letter stating the scope, sites and period, and naming the installation covered", "Appointee''s signed acceptance", "Registration of the electrician or electrical tester with the Department of Employment and Labour, where required", "Latest electrical Certificate of Compliance for the installation"]'::jsonb,
   'The electrical installation supervisor is responsible for the safety of your electrical installation. Faulty electrical work causes shocks, burns and fires, so an insurer or inspector will ask who is responsible.',
   'Example: Govender Bakery appoints its maintenance manager to supervise the electrical installation and files the Certificate of Compliance issued by a registered electrician.',
   '["An old Certificate of Compliance that predates later changes to the installation"]'::jsonb),
  ('APP-16',
   '["Signed appointment letter stating the scope, sites and period for the construction site", "Appointee''s signed acceptance", "Electrical qualification and registration evidence", "Inspection records of temporary site electrical supply"]'::jsonb,
   'On construction sites the temporary electrical supply, distribution boards and extension leads are exposed to damage and weather. The construction electrical appointee makes sure they are inspected and safe.',
   'Example: Radebe Construction appoints a registered electrician to look after the site distribution boards and earth leakage units on its Soweto project.',
   '["Damaged leads and missing earth leakage protection not picked up because nobody was appointed"]'::jsonb),
  ('APP-17',
   '["Appointment or engagement letter for the inspector or inspection company", "Proof of the inspector''s registration as a lifting machinery inspector with the Engineering Council of South Africa, and of the inspection company''s registration where the regulations require it", "Latest load test and inspection certificates for each lifting machine and item of tackle"]'::jsonb,
   'Lifting machines and tackle such as chain blocks, slings and cranes must be inspected by a competent person so they do not fail under load. The certificates show each item was safe when last checked, at the intervals the regulations or the practitioner set.',
   'Example: Mabena Steel engages a registered lifting machinery inspector who tests its overhead crane and slings and issues numbered certificates for the register.',
   '["Slings in use with no identification tag", "Inspection certificates missing for hired equipment"]'::jsonb),
  ('APP-18',
   '["Signed appointment letter stating the scope, sites and period, and naming the lifting machines", "Appointee''s signed acceptance", "Operator training certificate for each type of lifting machine", "Certificate of fitness outcome, where the risk assessment requires it"]'::jsonb,
   'Only trained and appointed operators should use lifting machines such as forklifts and cranes. Many workplace deaths involve forklifts. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Naidoo Packaging appoints Sibusiso Ntuli as forklift operator, with his operator certificate and card kept in the File.',
   '["Untrained staff using the forklift \"just for a minute\"", "Operator card expired"]'::jsonb),
  ('APP-19',
   '["Signed appointment letter stating the scope, sites and period, and naming the machinery covered", "Appointee''s signed acceptance", "Qualification or experience in the machinery supervised", "Machinery inspection or maintenance records the person signs"]'::jsonb,
   'The general machinery supervisor makes sure machinery is guarded, maintained and used safely. Unguarded moving parts cause amputations and crush injuries.',
   'Example: Fourie Manufacturing appoints its maintenance fitter, Andries Fourie, to supervise the machinery in its press shop and sign the weekly guard checks.',
   '["Appointing someone with no technical background to supervise machinery"]'::jsonb),
  ('APP-20',
   '["Signed appointment letter stating the scope, sites and period, and naming the pressure equipment", "Appointee''s signed acceptance", "Qualification or experience record", "Latest inspection certificates for pressure vessels such as air receivers and boilers"]'::jsonb,
   'Pressure equipment such as compressors, air receivers and boilers can explode if neglected. The supervisor keeps them inspected and maintained, often with an approved inspection authority.',
   'Example: Pillay Foods appoints its engineering manager as pressure equipment supervisor and files the inspection certificates for its boiler and two air receivers.',
   '["Small air receivers left off the register"]'::jsonb),
  ('APP-21',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Training record in hazardous chemical agents", "Chemical inventory and safety data sheets the person maintains"]'::jsonb,
   'Under the Hazardous Chemical Agents Regulations, chemical exposure must be assessed and controlled. The controller keeps the chemical inventory, safety data sheets and controls in order so workers are not harmed.',
   'Example: Ndlovu Agri appoints Zanele Ndlovu to control its crop spraying chemicals, with an up to date inventory and safety data sheets in the store.',
   '["Safety data sheets older than the product on the shelf", "Chemicals decanted into unlabelled containers"]'::jsonb),
  ('APP-22',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Ladder inspection register with the latest entries", "Brief training record on ladder inspection"]'::jsonb,
   'Ladders look harmless but falls from them are common. The ladder inspector checks every ladder at the intervals your risk assessment or the practitioner sets and removes damaged ones from use.',
   'Example: Moodley Retail appoints a storeman at each branch to inspect ladders and number them in the register.',
   '["Ladders not numbered, so the register cannot show which one was checked"]'::jsonb),
  ('APP-23',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Training or experience record", "Racking or stacking inspection records"]'::jsonb,
   'Stacked goods and racking can collapse or fall on people. The stacking and storage supervisor makes sure stacks are stable and racking is undamaged and not overloaded.',
   'Example: Mokoena Logistics appoints its warehouse supervisor to inspect racking and mark safe load limits in its Isando warehouse.',
   '["Damaged racking uprights left in use"]'::jsonb),
  ('APP-24',
   '["Signed appointment letter stating the scope, sites and period for each first aider", "Appointee''s signed acceptance", "Current first aid certificate from an approved training provider, with expiry date", "List of first aiders per site and shift, compared with the number your headcount requires"]'::jsonb,
   'First aiders give immediate help after an injury until medical help arrives. The number you need depends on your headcount; the File works it out for you. Clients check that every shift is covered and certificates are current.',
   'Example: Naidoo Packaging has three appointed first aiders across its two shifts, and the list on the first aid box names who is on duty.',
   '["Certificates that have expired", "No first aider on the night shift", "First aid box not stocked"]'::jsonb),
  ('APP-25',
   '["Signed appointment letter stating the scope, sites and period or service contract with the fire equipment company", "Appointee''s signed acceptance", "Service records for fire extinguishers and hose reels", "Registration of the service company, where your insurer or municipality requires it"]'::jsonb,
   'Fire equipment must work the first time. The fire equipment inspector makes sure extinguishers and hose reels are checked and serviced at the intervals your risk assessment, insurer or the practitioner sets.',
   'Example: Kruger Timber has a service contract with a local fire equipment company and a named staff member who checks the tags between services.',
   '["Service tags out of date", "Extinguishers blocked by stock"]'::jsonb),
  ('APP-26',
   '["Appointment letters for each fire team member", "Appointee''s signed acceptance", "Fire fighting training certificates", "Records of drills the fire team took part in"]'::jsonb,
   'The fire team responds to small fires before they spread and supports evacuation. Trained people with the right equipment can stop a small fire becoming a disaster.',
   'Example: Kruger Timber appoints four people to its fire team and records their training and the last drill.',
   '["Fire team members who have never used an extinguisher"]'::jsonb),
  ('APP-27',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Emergency response training record", "The emergency plan naming the coordinator"]'::jsonb,
   'The emergency coordinator takes charge during an emergency: raising the alarm, calling emergency services and accounting for everyone. Without one person in charge, emergencies become chaotic.',
   'Example: Moodley Retail names each branch manager as emergency coordinator, with the deputy named for when the manager is away.',
   '["No deputy when the coordinator is on leave"]'::jsonb),
  ('APP-28',
   '["Appointment letters for each evacuation warden, with the area covered", "Appointee''s signed acceptance", "Evacuation training record", "Evacuation drill reports"]'::jsonb,
   'Evacuation wardens clear their area, check nobody is left behind and report at the assembly point. Clients and insurers check that each floor or area has one.',
   'Example: Sithole Security Solutions appoints a warden for each floor of its Braamfontein office and records the drill times.',
   '["Areas without a warden after staff changes"]'::jsonb),
  ('APP-29',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Incident investigation training record", "Sample investigation reports the person completed"]'::jsonb,
   'The incident investigator finds out why an incident happened so it does not happen again. A good investigation looks for root causes, not just someone to blame.',
   'Example: Fourie Manufacturing appoints its health and safety officer as incident investigator and files his report on a hand injury at the guillotine.',
   '["Investigations that stop at \"worker was careless\""]'::jsonb),
  ('APP-30',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Confined space training certificate", "Confined space entry permits the person has issued or supervised"]'::jsonb,
   'Confined spaces such as tanks, pits and silos can have poisonous or oxygen poor air. The supervisor controls every entry through a permit, gas testing and a rescue plan.',
   'Example: Pillay Foods appoints its engineering foreman to supervise entries into its effluent pit, with signed entry permits and gas test readings on file.',
   '["No rescue plan", "Gas detector not calibrated"]'::jsonb),
  ('APP-31',
   '["Signed appointment letter stating the scope, sites and period, and naming the tools", "Appointee''s signed acceptance", "Training certificate for the explosive powered tool type"]'::jsonb,
   'Explosive powered tools such as cartridge nail guns can fire through material and injure people. Only trained, appointed operators should use them.',
   'Example: Khumalo Shopfitters appoints Mandla Khumalo as operator of its cartridge fixing tool, with the supplier''s training certificate on file.',
   '["Tool passed to untrained workers on site"]'::jsonb),
  ('APP-32',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Cartridge and tool issue register", "Training record"]'::jsonb,
   'The issuer keeps the explosive powered tools and cartridges locked away and signs them out only to appointed operators, so they are not misused or lost.',
   'Example: Khumalo Shopfitters'' storeman signs the tool and cartridges out to the appointed operator each morning and counts them back in the evening.',
   '["Cartridges not counted back in"]'::jsonb),
  ('APP-33',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Hot work training record", "Hot work permits the person issued"]'::jsonb,
   'Welding, cutting and grinding can start fires. The hot work supervisor makes sure every job has a permit, a fire watch and fire equipment at hand.',
   'Example: Mabena Steel appoints its workshop foreman as hot work supervisor, who issues permits for all welding outside the welding bay.',
   '["No fire watch after the work stops"]'::jsonb),
  ('APP-34',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Asbestos work training record", "Proof that any asbestos removal contractor is registered for asbestos work, as the governing regulations require"]'::jsonb,
   'Asbestos fibres cause fatal lung disease years after exposure. Any work with asbestos must be supervised and controlled, and removal is left to a registered contractor.',
   'Example: Botha Property Trust appoints a supervisor for the removal of an old asbestos cement roof, done by a registered asbestos contractor.',
   '["Drilling or breaking asbestos cement sheets without knowing what they are"]'::jsonb),
  ('APP-35',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Lead work training record", "Lead exposure risk assessment and air monitoring results"]'::jsonb,
   'Under the Lead Regulations, lead exposure must be controlled. The lead work supervisor makes sure controls, hygiene facilities and medical surveillance are in place. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Venter Battery Recycling appoints a supervisor for its lead recovery area and files the latest exposure monitoring results.',
   '["Workers eating or smoking in the lead area"]'::jsonb),
  ('APP-36',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Noise training record", "Noise zone map and latest noise survey"]'::jsonb,
   'Loud noise causes permanent hearing loss. The noise zone controller makes sure noise zones are marked, hearing protection is worn and people exposed are on medical surveillance. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Kruger Timber appoints its sawmill supervisor to control the noise zones marked on the survey map.',
   '["Noise zone signs missing", "Hearing protection issued but not worn"]'::jsonb),
  ('APP-37',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Radiation protection training record", "The radiation licence or authorisation for the equipment or source"]'::jsonb,
   'Radiation from X ray equipment, gauges and sources harms people you cannot see it affecting. The radiation protection officer controls the licence, dose monitoring and safe use.',
   'Example: Coetzee Testing Services appoints a radiation protection officer for its industrial X ray equipment and files the licence and the dose monitoring summaries.',
   '["Licence not transferred when equipment is moved to a new site"]'::jsonb),
  ('APP-38',
   '["Signed appointment letter stating the scope, sites and period", "Appointee''s signed acceptance", "Food safety or hygiene training certificate", "Certificate issued for the food premises by the municipal environmental health office, where you hold one"]'::jsonb,
   'Food handling mistakes can make customers and staff ill. The food safety and hygiene supervisor makes sure food is stored, prepared and served hygienically and that staff follow the rules.',
   'Example: Govender Bakery appoints its production manager as food safety supervisor and keeps the premises certificate on the wall and in the File.',
   '["Training certificates for only one shift"]'::jsonb),
  ('APP-39',
   '["Signed appointment letter stating the scope, sites and period, and naming the vehicles", "Appointee''s signed acceptance", "Copy of the driving licence and professional driving permit (PrDP), with expiry dates", "Certificate of fitness outcome from the occupational health practitioner"]'::jsonb,
   'Professional drivers carry goods or passengers on public roads, where a crash can harm many people. The appointment, valid licence and permit and medical fitness show the driver may drive. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions, unfit) goes in the File.',
   'Example: Molefe Transport keeps a copy of each driver''s licence and PrDP with the expiry date on its driver register and sends drivers for fitness assessments before renewal.',
   '["Expired PrDP not picked up", "Drivers sharing vehicles they are not appointed for"]'::jsonb),
  ('APP-40',
   '["Appointment letters for the mine manager and each statutory appointee under the MHSA regime", "Signed acceptances", "Certificates of competency or qualifications for each appointee"]'::jsonb,
   'Mines work under the MHSA regime, which has its own set of statutory appointments. This item holds them, alongside the rest of your File. Your mine''s own appointment matrix is the starting point.',
   'Example: Venter Quarries files the mine manager''s appointment and its matrix of other MHSA appointments, each with a signed acceptance.',
   '["Using OHS Act appointments where the MHSA regime applies"]'::jsonb);

insert into hsf_class_guidance (class_code, what_to_submit, why, example, common_gaps) values
  ('D04-01',
   '["Health and safety representative training certificate per designated representative", "Designation letter from Section B for the same person", "Matrix entry with the training date"]'::jsonb,
   'Representatives inspect the workplace and raise concerns for their colleagues, and they can only do that well once trained. An inspector will ask to see both the designation and the training. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Jacobs Printing in Epping designates Fatima Adams as representative for the press floor and files her representative training certificate next to her designation letter.',
   '["Designating a representative and never training them", "Training someone who was not elected or designated"]'::jsonb),
  ('D04-02',
   '["First aid certificate per first aider, with its level and expiry date", "Provider''s approval to train first aiders", "First aider list per site and shift"]'::jsonb,
   'Trained first aiders keep an injured person alive and stable until help arrives, and you need enough of them on every shift. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Mthembu Poultry in Camperdown keeps first aid certificates for four supervisors so each of its two shifts always has two trained first aiders.',
   '["Certificates from a provider that is not approved to train first aiders", "All first aiders on the day shift and none at night"]'::jsonb),
  ('D04-03',
   '["Fire fighting training certificate or attendance register per person", "Content outline showing practical use of the extinguishers you actually have"]'::jsonb,
   'People who know how to use an extinguisher can stop a small fire before it spreads and know when to leave instead. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Moodley Timber in Isipingo sends eight yard staff for fire fighting training and files the provider''s attendance register and certificates.',
   '["Training on extinguisher types you do not have on site", "No practical session, only a talk"]'::jsonb),
  ('D04-04',
   '["Working at height and fall arrest training certificate per person", "Record of harness and rescue practice", "Link to the fall protection plan in Section C"]'::jsonb,
   'Falls from height are one of the most common causes of serious injury, and the Construction Regulations, 2014 expect people working at height to be trained for it. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Zwane Roofing in Kempton Park files a working at height certificate for each roofer, cross referenced to the fall protection plan for its warehouse reroof.',
   '["No rescue training, so nobody knows how to bring down a person hanging in a harness", "Training certificates with no link to the actual fall protection plan"]'::jsonb),
  ('D04-05',
   '["Scaffold erector certificate for each person who erects scaffolding", "Scaffold inspector certificate for the person who signs scaffolds off", "Scaffold inspection register entries signed by that person"]'::jsonb,
   'A poorly built or uninspected scaffold can collapse under the people on it, so both the builders and the inspector must be competent. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Baloyi Scaffolding in Tembisa files erector certificates for its crew and an inspector certificate for foreman Kabelo Maluleke, who signs the weekly scaffold tags.',
   '["Scaffolds signed off by someone with only erector training", "Hired scaffold with no proof of the erector''s training"]'::jsonb),
  ('D04-06',
   '["Confined space entry training certificate per entrant, standby person and supervisor", "Record of rescue drill participation", "Link to the confined space permit procedure in Section G"]'::jsonb,
   'Confined spaces can hold toxic gas or too little oxygen, and many deaths are would be rescuers, so everyone involved must be trained, including the person standing by outside. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Hlongwane Water Services in Emalahleni trains a three person team in confined space entry and rescue before cleaning a municipal reservoir, and files the certificates and drill record.',
   '["Training the entrant but not the standby person", "Gas detector training left out"]'::jsonb),
  ('D04-07',
   '["Operator training certificate for each person who operates a crane, hoist or lifting machine", "Rigger or slinger training record for people who attach loads", "Link to the lifting machine register in Section F"]'::jsonb,
   'A dropped load or overturned crane can kill people nearby, so operators and riggers must be trained on the type of machine they use. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Kruger Engineering in Vereeniging files an overhead crane operator certificate for two workshop staff and a rigging certificate for the slinger who works with them.',
   '["Training on one type of crane but operating another", "Riggers with no training at all"]'::jsonb),
  ('D04-08',
   '["Forklift or mobile plant operator training certificate per operator, stating the machine type", "Operator''s authorisation card issued by your company", "Record of the pre use check training"]'::jsonb,
   'Forklifts and mobile plant cause many workplace deaths through tipping and collisions with people on foot, so only trained, authorised operators may drive them. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Moloi Distribution in Midrand files counterbalance forklift certificates for six operators and issues each a company authorisation card after a practical check.',
   '["Anyone with a key allowed to drive", "Certificates for a different class of machine than the one used"]'::jsonb),
  ('D04-09',
   '["Hazard identification and risk assessment training certificate per person who assesses risk", "An example of a risk assessment that person completed"]'::jsonb,
   'Your risk assessments in Section C are only as good as the people who do them, and an inspector will ask who assessed and how they are competent. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Nel Agricultural Services in Bethlehem sends its farm manager and two supervisors on risk assessment training before they review the baseline risk assessment.',
   '["Risk assessments signed by people with no training at all"]'::jsonb),
  ('D04-10',
   '["Incident investigation training certificate per investigator", "An investigation report that person completed"]'::jsonb,
   'Trained investigators find the real cause of an incident rather than blaming the injured person, so the same thing does not happen again. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Makhubu Security Services in Pretoria trains its operations manager in incident investigation, and her first report finds a broken gate light behind a guard''s fall.',
   '["Investigations that stop at worker carelessness", "Only one trained investigator for several sites"]'::jsonb),
  ('D04-11',
   '["Hazardous chemical handling training record per person who handles chemicals", "Content covering your own safety data sheets, labels, storage and personal protective equipment", "Link to your chemical inventory and hazardous chemical agent risk assessment"]'::jsonb,
   'The Hazardous Chemical Agents Regulations expect people exposed to chemicals to know the risks and controls, since chemicals can burn, poison or cause disease years later. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Mkhize Cleaning Services in Umhlanga trains its cleaners on the four chemicals they use, working through each safety data sheet and the correct gloves.',
   '["Generic chemical training that ignores the products you actually use", "No training when a new chemical arrives"]'::jsonb),
  ('D04-12',
   '["Asbestos awareness training record per person who may disturb asbestos", "Link to your asbestos inventory or survey where you have one"]'::jsonb,
   'Older buildings and plant may contain asbestos, and people who drill, cut or demolish without knowing can breathe in fibres that cause disease decades later. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Smit Maintenance in Kimberley trains its maintenance team in asbestos awareness before work on a school built in the 1970s, and files the attendance register.',
   '["Assuming asbestos is gone from all older buildings", "Training staff but not subcontractors who do the drilling"]'::jsonb),
  ('D04-13',
   '["Lead awareness training record per person exposed to lead", "Content covering hygiene, eating areas and change routines"]'::jsonb,
   'The Lead Regulations expect exposed workers to understand how lead enters the body and how hygiene and controls protect them and their families. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Mabena Radiator Works in Benoni trains its soldering staff on lead hygiene, including washing before eating and leaving work clothes at work.',
   '["No training for cleaners who handle lead dust", "Eating allowed in the work area after training"]'::jsonb),
  ('D04-14',
   '["Hearing conservation training record per person working in noise zones", "Record of hearing protector fit and care instruction", "Link to your noise survey and zone map"]'::jsonb,
   'Noise induced hearing loss is permanent and builds slowly, so people must know where the noise zones are and how to wear protection properly. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Dlamini Sawmills in Sabie trains its mill staff on noise zones and earplug fitting, with each worker demonstrating a correct fit.',
   '["Issuing earplugs without showing how to fit them", "Office staff who walk through noise zones left out"]'::jsonb),
  ('D04-15',
   '["Ergonomics training record per person in lifting, repetitive or screen based work", "Link to the ergonomics risk assessment"]'::jsonb,
   'Back, neck and wrist injuries from lifting, repetitive work or poor workstations are common and costly, and simple training on safe postures prevents many of them. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Khumalo Call Centre in Durban trains its agents on chair and screen set up after its ergonomics assessment, and files the attendance register.',
   '["Training without changing the workstations themselves"]'::jsonb),
  ('D04-16',
   '["Emergency evacuation training record per person, including fire marshals", "Evacuation drill report from Section H showing who took part"]'::jsonb,
   'In a fire or gas leak everyone must know the alarm, the route and the assembly point without thinking. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Maseko Office Supplies in Polokwane trains its marshals and then runs a drill; the report shows the building cleared in time and one blocked exit fixed.',
   '["Training marshals but never running a drill", "New starters not shown the evacuation route"]'::jsonb),
  ('D04-17',
   '["Food handler hygiene training record per food handler", "Content covering hand washing, illness reporting and cross contamination"]'::jsonb,
   'Food handlers who do not follow hygiene rules can make customers seriously ill, and your municipal environmental health practitioner will ask for proof of training. Renew it before the certificate expires; where no expiry is printed, refresh it as your risk assessment or the practitioner sets.',
   'Example: Mabuza Catering in Mbombela trains its kitchen staff in food hygiene and files the certificates next to their food handling fitness outcomes in Section E.',
   '["Training kitchen staff but not the people who serve or deliver food"]'::jsonb),
  ('D05-01',
   '["Copy of the driver''s licence and professional driving permit, front and back", "Date you last checked both were valid", "Link to the permit medical in Section E"]'::jsonb,
   'Drivers carrying passengers, dangerous goods or heavy loads need a professional driving permit, and your insurer or client may ask for it after a crash. Check it before the person drives and renew it before it expires.',
   'Example: Mahlangu Couriers in Centurion files permit copies for its eleven truck drivers and checks them on the first of every month.',
   '["A permit copy with no expiry date recorded", "Relief drivers driving without a permit check"]'::jsonb),
  ('D05-02',
   '["Operator certificate for each person operating plant or machinery, naming the machine type", "Company authorisation to operate that machine", "Expiry or reassessment date"]'::jsonb,
   'Plant and lifting machinery can crush or kill when misused, so only certified, authorised operators may use it. Check the certificate before the person operates and renew it before it expires.',
   'Example: Mabaso Earthworks in Kathu files a front end loader certificate and company authorisation for each of its four operators.',
   '["Certificates for a different machine type than the one operated", "No company authorisation, so anyone certified elsewhere can drive"]'::jsonb),
  ('D05-03',
   '["Copy of the electrician''s registration card as an electrical tester, installation electrician or master installation electrician", "The electrical certificate for any installation work they signed off", "Registration expiry or renewal date"]'::jsonb,
   'Only a registered person may sign off electrical installation work, and faulty electrical work causes fires and electrocution. Check registration before work starts and keep it current.',
   'Example: Nkosi Electrical Contractors in Roodepoort files the registration card of master installation electrician Busisiwe Nkosi with each certificate she issues.',
   '["Using an unregistered electrician because they are cheaper", "Accepting a certificate with no registration number on it"]'::jsonb),
  ('D05-04',
   '["Copy of the gas practitioner''s registration card, showing the gas type and category they may work on", "Certificate of the gas installation they signed off", "Registration expiry date"]'::jsonb,
   'Gas leaks and badly installed cylinders cause fires and explosions, so only a registered gas practitioner may install or alter gas systems. Check the registration category matches the work.',
   'Example: Sibiya Grill House in Soweto files the gas practitioner registration and installation certificate for its new LPG cooking line.',
   '["A practitioner registered for a different gas type or category", "No certificate after a cylinder bank was moved"]'::jsonb),
  ('D05-05',
   '["Copy of the explosives licence or blasting certificate held by each person handling explosives", "Magazine or storage licence where you store explosives", "Licence expiry dates"]'::jsonb,
   'Explosives are tightly controlled because misuse can kill many people at once, so only licensed or certificated people may handle, store or use them. Check each licence before any work and keep copies current.',
   'Example: Themba Quarrying near Kuruman files the blasting certificate of its blaster, Andile Mokoena, and the licence for its explosives magazine.',
   '["Assistants handling explosives without the certificate or direct supervision the rules require", "Storage licence not renewed when the magazine moved"]'::jsonb),
  ('D05-06',
   '["Firearm competency certificate for each person who carries a firearm at work", "Firearm licence for each company firearm and the register of who holds it", "Record of regular practical shooting or proficiency training"]'::jsonb,
   'An armed person without proven competence is a danger to themselves and the public, and firearms law requires competency for each firearm type. Check competency before issuing a firearm and keep records current.',
   'Example: Ngubane Armed Response in Richards Bay files the competency certificate for each armed officer next to the firearm issue register.',
   '["Issuing a firearm type the person is not certified for", "No record of who held which firearm on which shift"]'::jsonb),
  ('D05-07',
   '["PSIRA registration certificate for each security officer, showing their grade", "Company''s PSIRA registration as a security service provider", "Date you last checked each registration was active"]'::jsonb,
   'The private security industry is regulated under the PSIRA regime, so every officer must be registered at a grade that matches the post they fill. Clients often check this before a contract starts.',
   'Example: Mokoena Guarding in Klerksdorp files PSIRA certificates for its 18 officers and checks that the site supervisor holds the grade the client contract asks for.',
   '["Officers placed on posts above their registered grade", "Registrations lapsed because fees were not paid"]'::jsonb),
  ('E06-01',
   '["Lead examination outcome per exposed worker: fit, fit with restrictions or unfit", "The Plan''s lead protocol and exposure group list"]'::jsonb,
   'The Lead Regulations expect exposed workers to be under medical surveillance, because lead builds up in the body and harms the nerves, kidneys and unborn children. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Govender Battery Recyclers in Pietermaritzburg files the lead fitness outcome for each smelter worker; the laboratory results stay with the occupational health practitioner.',
   '["Filing blood lead results in the File", "Not moving a worker when the OMP says unfit for lead work"]'::jsonb),
  ('E06-02',
   '["Asbestos examination outcome per person exposed to asbestos", "Link to the asbestos work plan or abatement contract", "Exit examination outcome when the person leaves asbestos work, where the Plan sets one"]'::jsonb,
   'Asbestos diseases appear many years after exposure, so people who work with it are examined as the Plan and the OMP set, often including when they leave the work. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Petersen Demolition in Kraaifontein files asbestos fitness outcomes for its removal team before stripping roof sheets from an old factory.',
   '["No exit examination when the Plan calls for one", "Contractors'' teams working without outcomes on file"]'::jsonb),
  ('E06-03',
   '["Hazardous chemical agent examination outcome per exposed worker", "The Plan protocol linked to your chemical risk assessment"]'::jsonb,
   'The Hazardous Chemical Agents Regulations call for medical surveillance where the risk assessment shows a chemical may harm health, so early changes are picked up before disease sets in. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Mbatha Paints in Chloorkop files fitness outcomes for its mixers exposed to solvents, as set out in its Plan.',
   '["Surveillance for chemicals that are no longer used, while new ones are missed"]'::jsonb),
  ('E06-04',
   '["Hazardous biological agent examination outcome per exposed worker", "Record that vaccination was offered to each exposed worker, with the date; whether the worker accepted or declined stays with the occupational health practitioner", "The Plan protocol linked to your biological risk assessment"]'::jsonb,
   'The Hazardous Biological Agents Regulations call for surveillance of people exposed to germs at work, such as healthcare, laboratory, waste and sewage workers. Clinical records, including vaccination status and whether a worker accepted or declined a vaccination, stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Nxumalo Veterinary Clinic in Vryheid files fitness outcomes for its animal handlers and a dated record that each was offered the vaccinations its practitioner recommends.',
   '["Keeping vaccination cards with clinical details in the File"]'::jsonb),
  ('E06-05',
   '["Hearing examination outcome per worker in a noise zone: baseline, periodic and exit", "The Plan''s noise protocol and noise zone list", "Evidence that the testing was done by a competent person with suitable equipment"]'::jsonb,
   'Hearing loss from noise is permanent, so baseline and follow up tests show whether your controls are working and protect you in a later compensation claim. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Dlamini Sawmills in Sabie files baseline hearing outcomes for new mill staff and an exit outcome for each person who leaves.',
   '["No baseline test, so later loss cannot be measured", "Audiograms filed instead of the outcome"]'::jsonb),
  ('E06-06',
   '["Radiation worker examination outcome per worker", "The radiation licence conditions that set the examination", "Link to the dose monitoring records kept by the radiation protection officer"]'::jsonb,
   'People who work with X ray units or radioactive sources must be fit for that work and monitored, as the radiation control authority''s licence conditions set. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Sebego Radiology in Mahikeng files the fitness outcome for each radiographer, with dose records kept separately by its radiation protection officer.',
   '["Mixing personal dose results into the medical outcome file"]'::jsonb),
  ('E06-07',
   '["Fitness for work at height outcome per person on the fall protection plan", "Link to the working at height training record in Section D"]'::jsonb,
   'A dizzy spell or an uncontrolled medical condition can turn a slip at height into a fatal fall, so the Construction Regulations, 2014 expect people who work at height to be certified fit for it. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Zwane Roofing in Kempton Park sends its two new roofers for a work at height fitness assessment before their first day on the roof, and files both fit outcomes.',
   '["Assuming a general certificate covers work at height when it does not say so"]'::jsonb),
  ('E06-08',
   '["Fitness for confined space work outcome per entrant and standby person", "Link to the confined space training in Section D"]'::jsonb,
   'Confined spaces are hot, cramped and may need breathing apparatus, so entrants and rescuers must be fit enough to work and get out safely. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Hlongwane Water Services in Emalahleni files confined space fitness outcomes for its reservoir team, including the standby rescuer.',
   '["Standby rescuers never assessed"]'::jsonb),
  ('E06-09',
   '["Night work health assessment outcome per regular night worker", "Record of any move to day work the OMP recommended"]'::jsonb,
   'Regular night work can affect health, and employment law gives night workers protection, including access to a health assessment; your Plan sets how you handle it. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Moodley Bakeries in Chatsworth files night work fitness outcomes for its night shift bakers and moves one to day shift on the OMP''s advice.',
   '["No assessment offered to long term night workers"]'::jsonb),
  ('E06-10',
   '["Food handler fitness outcome per food handler", "Your illness reporting and exclusion procedure, and a record of the dates a food handler was excluded and cleared to return, without the illness"]'::jsonb,
   'Food handlers who are ill can spread infection to customers, so they must be fit to handle food and report illness before a shift. Clinical records stay with the occupational health practitioner; only the outcome (fit, fit with restrictions or unfit) goes in your File.',
   'Example: Mabuza Catering in Mbombela files a fit to handle food outcome for each cook and a record of the dates a cook was kept off shift and cleared to return, with the reason kept by its practitioner.',
   '["Filing medical notes for sick leave instead of the outcome"]'::jsonb);

-- 3. Access: reference content, read by anyone, written by the service role only ----------

do $$
declare
  t text;
begin
  foreach t in array array['hsf_guidance_meta','hsf_section_guidance','hsf_element_guidance',
                           'hsf_appointment_guidance','hsf_class_guidance'] loop
    execute format('alter table %I enable row level security', t);
    execute format('revoke all on %I from public, anon, authenticated', t);
    execute format('grant select on %I to anon, authenticated', t);
    execute format('grant all on %I to service_role', t);
    execute format('create policy %I on %I for select to anon, authenticated using (true)', t || '_read', t);
  end loop;
end;
$$;

-- 4. One document, shaped like hsf/guidance/guidance.json ---------------------------------

create or replace view hsf_public_guidance with (security_invoker = true) as
select jsonb_build_object(
  'meta', jsonb_build_object('version', m.version, 'status', m.status, 'reviewed_by', m.reviewed_by, 'note', m.note),
  'first_file', jsonb_build_object('intro', m.first_file_intro, 'order', m.first_file_order, 'before_you_start', m.before_you_start),
  'sections', coalesce((select jsonb_object_agg(s.section_code, jsonb_build_object(
                'intro', s.intro, 'what_goes_here', s.what_goes_here,
                'who_usually_holds', to_jsonb(s.who_usually_holds), 'first_file_tips', s.first_file_tips))
              from hsf_section_guidance s), '{}'::jsonb),
  'elements', coalesce((select jsonb_object_agg(e.element_code, jsonb_build_object(
                'what_to_submit', e.what_to_submit, 'why', e.why, 'example', e.example,
                'common_gaps', e.common_gaps, 'suggested_department', e.suggested_department))
              from hsf_element_guidance e), '{}'::jsonb),
  'appointments', coalesce((select jsonb_object_agg(a.appointment_code, jsonb_build_object(
                'what_to_submit', a.what_to_submit, 'why', a.why, 'example', a.example, 'common_gaps', a.common_gaps))
              from hsf_appointment_guidance a), '{}'::jsonb),
  'classes', coalesce((select jsonb_object_agg(c.class_code, jsonb_build_object(
                'what_to_submit', c.what_to_submit, 'why', c.why, 'example', c.example, 'common_gaps', c.common_gaps))
              from hsf_class_guidance c), '{}'::jsonb)
) as guidance
  from hsf_guidance_meta m;
comment on view hsf_public_guidance is 'Contract 12.3. The whole guidance as one jsonb document shaped like hsf/guidance/guidance.json (meta, first_file, sections, elements, appointments, classes). Public read on purpose: reference content, nothing personal.';
grant select on hsf_public_guidance to anon, authenticated;

-- 5. Refuse a library item without guidance ----------------------------------------------

do $$
declare
  v_missing text;
begin
  select string_agg(x, ', ' order by x) into v_missing from (
    select 'section ' || code as x from hsf_section where code not in (select section_code from hsf_section_guidance)
    union all select 'element ' || code from hsf_element where code not in (select element_code from hsf_element_guidance)
    union all select 'appointment ' || code from hsf_appointment_type where code not in (select appointment_code from hsf_appointment_guidance)
    union all select 'class ' || code from hsf_element_class where code not in (select class_code from hsf_class_guidance)) m;
  if v_missing is not null then
    raise exception 'HSF-GUIDE-01: library items without guidance: %', v_missing;
  end if;
end;
$$;
